#[derive(Clone, Debug)]
struct PageStartSeekSnapshot {
    paragraph_index: usize,
    body_element_index: usize,
    section_index: usize,
    page_number: usize,  // 1-indexed
    column_index: usize, // 0-indexed column within the page
    page_offset_y: f64,
    current_y: f64,
    last_line_baseline: f64,
    trailing_spacing_after: Option<(usize, usize, f64, f64)>,
    column_layout: ColumnLayout,
    current_text_direction: Option<TextDirection>,
    current_doc_grid: Option<DocGrid>,
    current_doc_grid_char_spacing_px: Option<f64>,
    numbering_counter: NumberingCounter,
    footnote_counter: usize,
    endnote_counter: usize,
    // Snapshot validity guards (page settings).
    margin_top: f64,
    page_height: f64,
    page_width: f64,
    /// True when this snapshot's resume anchor is a paragraph that STARTS on
    /// `page_number` but CROSSES onto a later page (a "spanning" snapshot). Such
    /// snapshots are stored in `page_start_seek_cache_by_page` keyed by a page the
    /// paragraph crosses INTO (which is strictly greater than `page_number`), so
    /// `page_number != keyed_page` for them. They resume the walk at the
    /// paragraph start (mid-page Y on `page_number`), NOT at the top of the keyed
    /// page. Consumption is gated by the `span_seek` escape hatch and the
    /// strict "start page before the visible window" rule. Normal page-top
    /// snapshots have `spanning == false`.
    spanning: bool,
    /// Tables rendered before this point (`table_counter` at capture time).
    /// A layout-extension seek restores it and keeps the first
    /// `table_counter` entries of the table resize metadata, so tables laid
    /// out before the resume point keep their handles.
    table_counter: usize,
}

