const PAGE_GAP_PX: f64 = 16.0;
/// Padding (CSS px) added around the edited paragraph's band rect in "band
/// redraw" mode, so selection highlights and antialiased glyph ink at the band
/// edges are not clipped. Mirrors the 2px padding used by
/// `compute_paragraph_dirty_rect_with_y_bounds` (the reverted S2 precedent).
const BAND_PAD_PX: f64 = 2.0;

/// Fraction of the trailing region below the edited paragraph's last baseline
/// (`end_y - baseline`) that the band bottom may extend into. `end_y` is the
/// paragraph advance bottom (== the next paragraph's start_y) and that trailing
/// region is the last line's glyph descent plus the inter-paragraph leading; the
/// following line's ascent occupies the BOTTOM of the leading, so staying within
/// half of the region keeps the band clear of the next line's ink while still
/// covering the edited paragraph's own descenders. See [`band_local_bounds`].
const BAND_DESCENT_RATIO: f64 = 0.5;

/// Tolerance when matching a line's bottom against [`BandRedrawPlan::paint_bottom`].
const BAND_PAINT_EPS: f64 = 0.01;

/// How far above the band (CSS px) band mode still draws a line: a line whose
/// bottom is within this distance of the band top paints under the clip.
const BAND_ABOVE_SLACK: f64 = 80.0;

/// Paragraphs on each side of the edited one whose ink a band may reach and
/// repaint under its clip; reaching more falls back to the dirty-page render.
const BAND_MAX_REPAINTED_NEIGHBORS: usize = 2;

/// Page-local vertical bounds `(top, bottom)` for a band redraw of a single
/// paragraph, given its page-local start Y, advance-end Y, and last-line
/// baseline Y. The band clears + clips this rect and repaints ONLY the edited
/// paragraph, so the bottom must stop above the following line's ink: it is
/// bounded by the last baseline plus a fraction of the trailing descent+leading
/// region (never the full advance-end, which reaches the next line's ascent).
/// The top keeps a small pad above the first line for antialiasing.
fn band_local_bounds(start_local: f64, end_local: f64, baseline_local: f64) -> (f64, f64) {
    let trailing = (end_local - baseline_local).max(0.0);
    let ink_bottom = (baseline_local + trailing * BAND_DESCENT_RATIO).min(end_local);
    let local_top = (start_local - BAND_PAD_PX).max(0.0);
    let local_bottom = ink_bottom.max(start_local + 1.0);
    (local_top, local_bottom)
}

/// Safety guard for [`band_local_bounds`]: whether a painted line's measured ink
/// extent (page-local top/bottom, from per-run ascent/descent metrics) escapes
/// the band rect. `BAND_DESCENT_RATIO` assumes normal line spacing where the
/// trailing region below the last baseline is descent + inter-paragraph leading;
/// under `lineRule="exact"` (or tight `atLeast`) spacing the paragraph's own
/// descenders can fall below that split — the band clear would then erase old
/// descender pixels the clipped repaint cannot restore (the inverse of the
/// next-line ascent clip). When this returns true the render must escalate to a
/// full repaint via the existing band-escalation path.
fn band_ink_escapes_band(band_top: f64, band_bottom: f64, ink_top: f64, ink_bottom: f64) -> bool {
    if !(ink_top.is_finite() && ink_bottom.is_finite()) {
        // Unmeasurable ink cannot be proven covered — escalate.
        return true;
    }
    ink_bottom > band_bottom || ink_top < band_top
}

fn segment_text_is_whitespace(text: &str) -> bool {
    text.chars().all(char::is_whitespace)
}

fn segment_suppresses_line_height(
    segment_start: usize,
    segment_end: usize,
    base_offset: usize,
    neutral_ranges: &[(usize, usize)],
) -> bool {
    neutral_ranges.iter().any(|(start, end)| {
        base_offset + *start <= segment_start && segment_end <= base_offset + *end
    })
}

/// Returns whether the device-aligned band clip reaches measured ink belonging
/// to an adjacent paragraph. Canvas clips are expanded by one device pixel in
/// [`CanvasRenderer::device_aligned_vertical_clip_rect_for_dpr`], so comparing
/// the unaligned CSS bounds alone is insufficient: a nominal gap can disappear
/// after outward rounding. Band mode paints only the edited paragraph; touching
/// either neighbour therefore requires the full-page fallback.
fn band_clip_overlaps_neighbor_ink(
    band_top: f64,
    band_bottom: f64,
    device_pixel_ratio: f64,
    previous_ink_bottom: Option<f64>,
    next_ink_top: Option<f64>,
) -> bool {
    let dpr = device_pixel_ratio.max(1.0);
    let device_guard = 1.0 / dpr;
    let aligned_top = (band_top * dpr).floor() / dpr - device_guard;
    let aligned_bottom = (band_bottom * dpr).ceil() / dpr + device_guard;

    previous_ink_bottom.is_some_and(|bottom| aligned_top < bottom)
        || next_ink_top.is_some_and(|top| aligned_bottom > top)
}

/// A band plan is indexed by paragraph number, so its cached last baseline must
/// still identify the same paragraph as the pre-edit selection layout. Structural
/// edits shift paragraph indexes; a stale cache slot can otherwise clear a valid
/// band belonging to an unrelated paragraph while repainting the edited one.
fn band_layout_matches_selection_baseline(
    cached_absolute_baseline: f64,
    selection_absolute_baseline: f64,
) -> bool {
    const EPS: f64 = 0.001;
    cached_absolute_baseline.is_finite()
        && selection_absolute_baseline.is_finite()
        && (cached_absolute_baseline - selection_absolute_baseline).abs() < EPS
}

/// Extra pages on each side of the visible window whose canvas backing is kept
/// materialized. A small buffer absorbs minor scroll jitter and reduces
/// re-materialization churn (and the rare clean-page-reuse blank) when the
/// caret/visible window shifts by a page during incremental edits.
const PAGE_BACKING_KEEP_BUFFER: usize = 2;
/// Extra pages on each side of the visible window for which the paragraph render
/// cache (draw commands + selection layout) is retained. Larger than the canvas
/// backing buffer because re-rendering an off-window paragraph is cheaper than a
/// blank scroll-back flash, and a generous buffer keeps ordinary scrolling on
/// cache hits while still bounding total retained draw commands.
const RENDER_CACHE_KEEP_BUFFER_PAGES: usize = 8;
/// Floor capacity for the paragraph wrap cache (also the default for small
