#[derive(Debug, Clone, Copy, PartialEq)]
struct TextBoxVerticalLayout {
    offset: f64,
    line_gap: f64,
}

fn text_box_vertical_layout(
    alignment: TextBoxVerticalAlignment,
    available_height: f64,
    content_height: f64,
    line_count: usize,
) -> TextBoxVerticalLayout {
    let remaining = (available_height - content_height).max(0.0);
    let (offset, line_gap) = match alignment {
        TextBoxVerticalAlignment::Top => (0.0, 0.0),
        TextBoxVerticalAlignment::Center => (remaining / 2.0, 0.0),
        TextBoxVerticalAlignment::Bottom => (remaining, 0.0),
        TextBoxVerticalAlignment::Justified if line_count > 1 => {
            (0.0, remaining / (line_count - 1) as f64)
        }
        TextBoxVerticalAlignment::Distributed if line_count > 0 => {
            let line_gap = remaining / line_count as f64;
            (line_gap / 2.0, line_gap)
        }
        TextBoxVerticalAlignment::Justified | TextBoxVerticalAlignment::Distributed => (0.0, 0.0),
    };
    TextBoxVerticalLayout { offset, line_gap }
}
