const DARK_MODE_TEXT_COLOR: &str = "#f5f8ff";
// Word keeps CJK glyph boxes tight to the top of the computed line box.
// Reserving extra leading below text avoids artificial gaps right after tables.
const LINE_TOP_LEADING_SHARE: f64 = 0.0;

/// Resolve the fraction of a line box's spare leading that sits *above* the
/// content from a paragraph's `w:textAlignment` token (ECMA-376 Part 1
/// §17.3.1.39). The spare leading is `(line_height - content_height)`; the
/// returned share decides where the glyphs sit vertically inside the line box:
/// `top` pins the content to the top (share 0), `bottom` to the bottom
/// (share 1), `center` halfway. `baseline`/`auto`/unknown/absent fall back to
/// the application default ([`LINE_TOP_LEADING_SHARE`]) so existing documents
/// keep their current vertical metrics.
fn text_alignment_top_leading_share(token: Option<&str>) -> f64 {
    match token {
        Some("top") => 0.0,
        Some("center") => 0.5,
        Some("bottom") => 1.0,
        _ => LINE_TOP_LEADING_SHARE,
    }
}

/// Section-level vertical justification (`w:vAlign` inside `w:sectPr`,
/// ECMA-376 Part 1 §17.6.22, `ST_VerticalJc`). Decides where a page's body
/// content sits within the text region when it does not fill the page.
///
/// Pure decision core for section vertical alignment, consumed by the
/// measure-then-translate render wiring ([`page_valign_offsets_from_heights`]
/// + the per-page offset applied at every body-page start).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SectionVerticalAlign {
    /// `top` (default): content starts at the top margin — no offset.
    Top,
    /// `center`: leftover space is split evenly above and below the content.
    Center,
    /// `both`: distribute extra space between paragraphs (justify). The MVP
    /// treats it as `top` until inter-paragraph distribution is wired.
    Both,
    /// `bottom`: content is pushed down so it ends at the bottom margin.
    Bottom,
}

/// Maps a normalized `w:vAlign` token to [`SectionVerticalAlign`]. `top` and any
/// unknown / absent token collapse to [`SectionVerticalAlign::Top`] (the Word
/// default = no vertical offset), so existing documents are unchanged.
fn resolve_section_vertical_align(token: Option<&str>) -> SectionVerticalAlign {
    match token {
        Some("center") => SectionVerticalAlign::Center,
        Some("both") => SectionVerticalAlign::Both,
        Some("bottom") => SectionVerticalAlign::Bottom,
        _ => SectionVerticalAlign::Top,
    }
}

/// Computes the vertical offset (px) to add to a page's body content so it is
/// justified per the section's `w:vAlign`. `page_content_height` is the usable
/// text-region height (body top → body bottom) and `used_content_height` is how
/// much of it the page's content actually occupies.
///
/// `center` returns half the leftover, `bottom` the full leftover, `top`/`both`
/// return `0.0` (both is approximated as top until inter-paragraph
/// distribution lands). The result is clamped to `>= 0.0`, so content that
/// overflows the page (used >= available) is never pushed *up* off the top.
fn section_vertical_align_offset(
    align: SectionVerticalAlign,
    page_content_height: f64,
    used_content_height: f64,
) -> f64 {
    let leftover = (page_content_height - used_content_height).max(0.0);
    match align {
        SectionVerticalAlign::Top | SectionVerticalAlign::Both => 0.0,
        SectionVerticalAlign::Center => leftover / 2.0,
        SectionVerticalAlign::Bottom => leftover,
    }
}

/// Maps each page's natural used body-content height to its vertical offset for
/// section `w:vAlign`, producing the per-page offset vector the renderer applies
/// at every body-page start. A thin wrapper over [`section_vertical_align_offset`]
/// so the measure→translate bridge has one tested entry point.
#[cfg(test)]
fn page_valign_offsets_from_heights(
    align: SectionVerticalAlign,
    page_content_height: f64,
    used_heights: &[f64],
) -> Vec<f64> {
    used_heights
        .iter()
        .map(|&used| section_vertical_align_offset(align, page_content_height, used))
        .collect()
}

fn page_valign_offsets_from_sections(
    default_align: SectionVerticalAlign,
    section_alignments: &[SectionVerticalAlign],
    page_sections: &[usize],
    available_heights: &[f64],
    used_heights: &[f64],
) -> Vec<f64> {
    used_heights
        .iter()
        .enumerate()
        .map(|(page, &used)| {
            let align = page_sections
                .get(page)
                .and_then(|section| section_alignments.get(*section))
                .copied()
                .unwrap_or(default_align);
            let available = available_heights.get(page).copied().unwrap_or(0.0);
            section_vertical_align_offset(align, available, used)
        })
        .collect()
}

