enum FloatingPaintObject {
    Image {
        run_index: usize,
        image: RunImage,
    },
    TextBox {
        run_index: usize,
        text_box: RunTextBox,
    },
}

impl FloatingPaintObject {
    fn run_index(&self) -> usize {
        match self {
            Self::Image { run_index, .. } | Self::TextBox { run_index, .. } => *run_index,
        }
    }

    fn layout(&self) -> &RunImageLayout {
        match self {
            Self::Image { image, .. } => &image.layout,
            Self::TextBox { text_box, .. } => &text_box.layout,
        }
    }

    fn paint_order_key(&self) -> (u32, usize) {
        (
            self.layout()
                .relative_height
                .unwrap_or(DEFAULT_FLOAT_RELATIVE_HEIGHT),
            self.run_index(),
        )
    }
}

