#[derive(Debug, Default)]
struct TextBatchScratch {
    fonts: Vec<Rc<str>>,
    text: String,
    x_positions: Vec<f64>,
    font_indexes: Vec<u16>,
    font_index_by_slot: [u16; 4],
    first_font_slot: Option<ResolvedFontSlot>,
    single_font_run: bool,
}

impl TextBatchScratch {
    fn clear_for_len(&mut self, len: usize) {
        self.fonts.clear();
        self.text.clear();
        self.x_positions.clear();
        self.font_indexes.clear();
        self.text.reserve(len);
        self.x_positions.reserve(len);
        self.first_font_slot = None;
        self.single_font_run = true;
    }

    fn clear_font_indexes_for_len(&mut self, len: usize) {
        self.fonts.clear();
        self.font_indexes.clear();
        self.fonts.reserve(len.min(4));
        self.font_indexes.reserve(len);
        self.font_index_by_slot.fill(u16::MAX);
    }

    fn observe_font_slot(&mut self, style: &ResolvedRunStyle, font_slot: ResolvedFontSlot) {
        if !self.single_font_run {
            return;
        }
        match self.first_font_slot {
            Some(active_slot)
                if active_slot != font_slot
                    && !<CanvasRenderer>::same_text_run_font_descriptor(
                        style.descriptor_for_slot(active_slot),
                        style.descriptor_for_slot(font_slot),
                    ) =>
            {
                self.single_font_run = false;
            }
            Some(_) => {}
            None => self.first_font_slot = Some(font_slot),
        }
    }

    fn font_index(&mut self, style: &ResolvedRunStyle, font_slot: ResolvedFontSlot) -> u16 {
        let slot_index = <CanvasRenderer>::font_slot_index(font_slot);
        let cached_index = self.font_index_by_slot[slot_index];
        if cached_index != u16::MAX {
            return cached_index;
        }

        let font_descriptor = style.descriptor_for_slot(font_slot);
        let index = <CanvasRenderer>::text_run_font_index(&mut self.fonts, font_descriptor);
        self.font_index_by_slot[slot_index] = index;
        index
    }
}

