    /// Returns the lazy-edit visible-window seek diagnostics
    /// `(exact_hits, fallback_hits, misses)` for `debugRendererStats`.
    pub fn window_seek_stats(&self) -> (u64, u64, u64) {
        (
            self.window_seek_exact_hits.get(),
            self.window_seek_fallback_hits.get(),
            self.window_seek_misses.get(),
        )
    }

    /// Enables or disables the opt-in "band redraw" fast path (URL param
    /// `band_redraw=1`). Default is disabled, in which case rendering is
    /// byte-for-byte identical to a build without this feature.
    pub fn set_band_redraw_enabled(&mut self, enabled: bool) {
        self.band_redraw_enabled = enabled;
    }

    /// Marks (or unmarks) the current render as an IME composition-preview pass.
    /// While set, band redraw is disqualified in `compute_band_redraw_plan`
    /// (bumping `band_redraw_fallback_ime`). The non-lazy composition path sets
    /// this because its destructive full-page snapshot leaves the offscreen page
    /// blank between previews. Lazy composition uses non-destructive bitmap
    /// extraction and therefore leaves it unset.
    pub fn set_band_redraw_suppressed_for_composition(&mut self, suppressed: bool) {
        self.band_redraw_suppressed_ime = suppressed;
    }

    /// Marks the next render as the replay of a structural edit (undo/redo of a
    /// paragraph split or merge). While set, band redraw is disqualified in
    /// `compute_band_redraw_plan` (bumping `band_redraw_fallback_structural`).
    ///
    /// Band redraw retains every pixel outside the edited paragraph's band, and
    /// its stability check only proves that the edited paragraph itself did not
    /// move. Undoing a paragraph break merges the following (usually empty)
    /// paragraph back: the edited paragraph keeps its start, page and height —
    /// the check passes — while the whole document below shifts up by the merged
    /// paragraph's height, so the retained pixels below the band still show the
    /// pre-undo lines. One-shot: cleared at render end.
    pub fn set_band_redraw_suppressed_for_structural_edit(&mut self, suppressed: bool) {
        self.band_redraw_suppressed_structural = suppressed;
    }

    /// Enables or disables the spanning-paragraph seek fast path. It is enabled
    /// by default; URL param `span_seek=0` is the escape hatch. When disabled,
    /// the lazy visible-window seek is byte-for-byte identical to a build without
    /// this feature (spanning snapshots are still recorded but never consumed).
    pub fn set_span_seek_enabled(&mut self, enabled: bool) {
        self.span_seek_enabled = enabled;
    }

    /// Whether spanning-paragraph seek consumption is enabled for this renderer.
    pub fn span_seek_enabled(&self) -> bool {
        self.span_seek_enabled
    }

    /// Span-seek diagnostics for `debugRendererStats.span_seek`
    /// `(recorded, consumed, rejected_visible_start, rejected_geometry)`. All
    /// counters are monotonic (session lifetime).
    pub fn span_seek_stats(&self) -> (u64, u64, u64, u64) {
        (
            self.span_seek_recorded.get(),
            self.span_seek_consumed.get(),
            self.span_seek_rejected_visible_start.get(),
            self.span_seek_rejected_geometry.get(),
        )
    }

    /// Whether band redraw is enabled for this renderer.
    pub fn band_redraw_enabled(&self) -> bool {
        self.band_redraw_enabled
    }

    /// Edit-pixel-reuse signal for the just-completed edit render: `Some((page0,
    /// kind))` when the caret page's full canvas is valid (see
    /// [`EditRenderKind`]), else `None`. One-shot — reset at every render entry.
    /// Read once by the `insert_text` payload builder.
    pub fn last_edit_full_page_valid(&self) -> Option<(usize, EditRenderKind)> {
        self.last_edit_full_page_valid
    }

    /// Edit-pixel-reuse signal for a band escalation. The escalated re-render
    /// repaints the visible pages in full, so the edited paragraph's page is
    /// fully valid — but that recursive pass cannot see the edit any more
    /// (`forced_dirty_from` is cleared once a seek is active), so it reports
    /// nothing on its own. Record the caret page as a full paint here unless
    /// the re-render already produced a signal; without a cached layout for
    /// the paragraph there is no page to name.
    pub(crate) fn record_escalated_edit_render(&mut self, edited_paragraph: Option<usize>) {
        if self.last_edit_full_page_valid.is_some() {
            return;
        }
        let Some(edited_paragraph) = edited_paragraph else {
            return;
        };
        if let Some(page_1based) = self.cached_paragraph_start_page(edited_paragraph) {
            self.last_edit_full_page_valid =
                Some((page_1based.saturating_sub(1), EditRenderKind::Full));
        }
    }

    /// Dirty visible pages lazy band edits left unpainted (session lifetime).
    pub fn band_redraw_skipped_pages(&self) -> u64 {
        self.band_redraw_skipped_pages.get()
    }

    /// Makes band renders paint only the band page. Set for lazy sessions,
    /// whose page pixels are fetched, and repainted, on demand.
    pub fn set_band_redraw_paints_band_page_only(&mut self, enabled: bool) {
        self.band_redraw_paints_band_page_only = enabled;
    }

    /// Band-redraw diagnostics for `debugRendererStats.band_redraw`.
    ///
    /// Returns `(eligible, taken, fallback_reasons)` where the reasons vector is
    /// `(name, count)` pairs. All counters are monotonic (session lifetime).
    #[allow(clippy::type_complexity)]
    pub fn band_redraw_stats(&self) -> (u64, u64, Vec<(&'static str, u64)>) {
        (
            self.band_redraw_eligible.get(),
            self.band_redraw_taken.get(),
            vec![
                ("disabled", self.band_redraw_fallback_disabled.get()),
                ("no_edit", self.band_redraw_fallback_no_edit.get()),
                ("full_repaint", self.band_redraw_fallback_full_repaint.get()),
                ("pageless", self.band_redraw_fallback_pageless.get()),
                ("notes", self.band_redraw_fallback_notes.get()),
                (
                    "line_numbering",
                    self.band_redraw_fallback_line_numbering.get(),
                ),
                (
                    "not_plain_paragraph",
                    self.band_redraw_fallback_not_plain_paragraph.get(),
                ),
                ("floating", self.band_redraw_fallback_floating.get()),
                ("numbering", self.band_redraw_fallback_numbering.get()),
                ("multi_page", self.band_redraw_fallback_multi_page.get()),
                ("multi_column", self.band_redraw_fallback_multi_column.get()),
                ("line_height", self.band_redraw_fallback_line_height.get()),
                ("empty_line", self.band_redraw_fallback_empty_line.get()),
                (
                    "page_not_dirty",
                    self.band_redraw_fallback_page_not_dirty.get(),
                ),
                ("no_layout", self.band_redraw_fallback_no_layout.get()),
                ("unstable", self.band_redraw_fallback_unstable.get()),
                ("ink_overflow", self.band_redraw_fallback_ink_overflow.get()),
                ("neighbor_ink", self.band_redraw_fallback_neighbor_ink.get()),
                ("ime", self.band_redraw_fallback_ime.get()),
                ("structural", self.band_redraw_fallback_structural.get()),
            ],
        )
    }

    /// Initial-render glyph-batch diagnostics
    /// `(batch_runs, batch_glyphs, fallback_runs, fallback_glyphs)` for
    /// `debugRendererStats`. See the `glyph_batch_*` fields.
    pub fn glyph_batch_stats(&self) -> (u64, u64, u64, u64) {
        (
            self.glyph_batch_batch_runs.get(),
            self.glyph_batch_batch_glyphs.get(),
            self.glyph_batch_fallback_runs.get(),
            self.glyph_batch_fallback_glyphs.get(),
        )
    }

    #[inline]
    fn record_glyph_batch_run(&self, glyphs: u64) {
        self.glyph_batch_batch_runs
            .set(self.glyph_batch_batch_runs.get() + 1);
        self.glyph_batch_batch_glyphs
            .set(self.glyph_batch_batch_glyphs.get() + glyphs);
    }

    #[inline]
    fn record_glyph_fallback_run(&self, glyphs: u64) {
        self.glyph_batch_fallback_runs
            .set(self.glyph_batch_fallback_runs.get() + 1);
        self.glyph_batch_fallback_glyphs
            .set(self.glyph_batch_fallback_glyphs.get() + glyphs);
    }

    /// Returns an immutable reference to the decoration plugin registry.
    pub fn decoration_registry(&self) -> &crate::plugins::DecorationRegistry {
        &self.decoration_registry
    }

    /// Looks up plugin decorations for one paragraph's text.
    ///
    /// 本文と表のセルで描画経路が分かれているので、その 2 つから同じ手順で
    /// 引けるようにここへ出してある。当たらなければ `pending_decorations` へ
    /// 積み、描画の外でプラグインを回してもらう (段落はいったん装飾なしで
    /// 描かれ、結果が返ってから塗り直される)。
    pub(crate) fn decorations_for_paragraph_text(
        &self,
        paragraph_text: &str,
        paragraph_index: usize,
    ) -> Vec<crate::plugins::DecoratedRange> {
        if !self.has_active_decoration_plugins() || paragraph_text.is_empty() {
            return Vec::new();
        }
        // Record the (text -> paragraph_index) association up front so a later
        // `applyDecorationResults` call can target render-cache invalidation at
        // precisely the paragraphs that render with this text, instead of
        // nuking every paragraph's cached DrawCommands.
        self.decoration_cache
            .borrow_mut()
            .record_paragraph_index(paragraph_text, paragraph_index);
        if let Some(cached) = self.decoration_cache.borrow().get(paragraph_text) {
            return cached.to_vec();
        }
        self.pending_decorations
            .borrow_mut()
            .insert(paragraph_text.to_string());
        Vec::new()
    }

    pub(crate) fn spelling_decorations<'a>(
        &self,
        text: &str,
        runs: impl IntoIterator<Item = (usize, usize, Option<&'a RunProperties>)>,
        paragraph_index: usize,
    ) -> Vec<crate::plugins::DecoratedRange> {
        if self.spelling_export_mode || !self.spelling_cache.borrow().enabled {
            return Vec::new();
        }
        self.decoration_cache
            .borrow_mut()
            .record_paragraph_index(text, paragraph_index);
        self.spelling_cache.borrow_mut().decorations(text, runs)
    }

    #[inline]
    fn has_active_decoration_plugins(&self) -> bool {
        self.decoration_registry.is_enabled() && !self.decoration_registry.is_empty()
    }

    /// Registers a plugin and invalidates every cached decoration. All
    /// subsequently rendered paragraphs will cache-miss once and enter
    /// the async refresh path.
    pub fn register_plugin(&mut self, plugin: Box<dyn crate::plugins::DecorationPlugin>) {
        self.decoration_registry.register(plugin);
        self.decoration_cache.borrow_mut().bump_version();
        self.pending_decorations.borrow_mut().clear();
    }

    /// Unregisters every plugin with the given name and invalidates every
    /// cached decoration. Returns the same boolean semantics as
    /// [`crate::plugins::DecorationRegistry::unregister`].
    pub fn unregister_plugin(&mut self, name: &str) -> bool {
        let removed = self.decoration_registry.unregister(name);
        if removed {
            self.decoration_cache.borrow_mut().bump_version();
            self.pending_decorations.borrow_mut().clear();
        }
        removed
    }

    /// Enables or disables all plugin invocations. Disabling also clears
    /// any pending requests (there is no point chasing them) and bumps
    /// the cache version so that re-enabling starts from a clean slate.
    pub fn set_plugins_enabled(&mut self, enabled: bool) {
        let was_enabled = self.decoration_registry.is_enabled();
        self.decoration_registry.set_enabled(enabled);
        if was_enabled != enabled {
            self.decoration_cache.borrow_mut().bump_version();
            self.pending_decorations.borrow_mut().clear();
        }
    }

    /// Drains the set of paragraph texts that rendered with no cached
    /// decoration. Intended for the JS-side async orchestrator.
    pub fn take_pending_decorations(&self) -> Vec<String> {
        self.pending_decorations.borrow_mut().drain()
    }

    pub fn has_pending_decorations(&self) -> bool {
        !self.pending_decorations.borrow().is_empty()
    }

    /// Inserts plugin-produced ranges for a paragraph text. Returns
    /// `true` iff the cache meaningfully changed — the caller uses this
    /// signal to decide whether to trigger a re-render.
    pub fn apply_decoration_result(
        &self,
        text: String,
        ranges: Vec<crate::plugins::DecoratedRange>,
    ) -> bool {
        self.decoration_cache.borrow_mut().put(text, ranges)
    }

    pub fn clear_decoration_cache(&self) {
        self.decoration_cache.borrow_mut().clear();
        self.pending_decorations.borrow_mut().clear();
    }

    /// Invalidates paragraph render-cache entries for every paragraph
    /// that is known to currently render with any of the supplied
    /// texts. Returns the number of distinct paragraph indexes that
    /// were invalidated (useful for diagnostics).
    ///
    /// This is the targeted alternative to
    /// [`Self::clear_paragraph_render_cache`] that
    /// `applyDecorationResults` uses after new decorations arrive.
    /// The reverse index is populated by the render seam via
    /// [`crate::plugins::DecorationCache::record_paragraph_index`],
    /// so any paragraph whose text was rendered at least once since
    /// the last cache clear will be found.
    pub fn invalidate_render_cache_for_decoration_texts(&mut self, texts: &[String]) -> usize {
        let outcome = self.invalidate_and_mark_dirty_rects_for_decoration_texts(texts);
        outcome.invalidated_paragraphs
    }

    /// Same as [`Self::invalidate_render_cache_for_decoration_texts`]
    /// but also marks dirty rectangles for every affected paragraph
    /// using the geometry stored in its (still-valid) render cache
    /// entry BEFORE the entry is invalidated.
    ///
    /// The returned struct reports:
    ///
    /// * `invalidated_paragraphs`: number of distinct paragraph
    ///   indexes whose render cache was wiped.
    /// * `dirty_rects_marked`: number of per-paragraph dirty rects
    ///   pushed to the dirty-region tracker. This may be less than
    ///   `invalidated_paragraphs` if any target paragraph had no
    ///   cached render entry to derive a rect from.
    /// * `all_rects_resolved`: true iff `dirty_rects_marked ==
    ///   invalidated_paragraphs`. The embedder uses this flag to
    ///   decide whether the subsequent rerender can rely on the
    ///   dirty-rect path or needs a `mark_full_repaint()` fallback.
    pub fn invalidate_and_mark_dirty_rects_for_decoration_texts(
        &mut self,
        texts: &[String],
    ) -> DecorationInvalidationOutcome {
        if texts.is_empty() {
            return DecorationInvalidationOutcome::default();
        }
        let mut targeted: std::collections::BTreeSet<usize> = std::collections::BTreeSet::new();
        {
            let cache = self.decoration_cache.borrow();
            for text in texts {
                for idx in cache.paragraph_indexes_for(text) {
                    targeted.insert(*idx);
                }
            }
        }
        if targeted.is_empty() {
            return DecorationInvalidationOutcome::default();
        }

        // Step 1: collect dirty rects from the still-valid cache
        // entries. We snapshot geometry up-front so invalidation (step
        // 2) cannot race with rect derivation.
        //
        // `CachedParagraphRender` stores absolute document-Y
        // coordinates (with page gaps folded in) exactly as
        // `DirtyRect` expects, so no coordinate translation is
        // needed here. The rect spans the page's full width because
        // a decoration change can touch any horizontal position
        // within the paragraph.
        let mut rects: Vec<DirtyRect> = Vec::with_capacity(targeted.len());
        {
            let render_cache = self.paragraph_render_cache.borrow();
            for idx in &targeted {
                if let Some(Some(entry)) = render_cache.entries.get(*idx) {
                    let height = (entry.end_y - entry.start_y).max(0.0);
                    if height <= 0.0 {
                        continue;
                    }
                    let page_0idx = entry.start_page.saturating_sub(1);
                    rects.push(DirtyRect::new(
                        0.0,
                        entry.start_y,
                        self.page_width,
                        height,
                        page_0idx,
                    ));
                }
            }
        }

        // Step 2: invalidate the render cache entries. This must
        // happen AFTER we read their geometry above because the
        // snapshot fields disappear once an entry is replaced with
        // None.
        {
            let mut render_cache = self.paragraph_render_cache.borrow_mut();
            for idx in &targeted {
                render_cache.invalidate_at(*idx);
            }
        }

        // Step 3: push the collected rects through the public
        // dirty-rect surface so the existing bitmap-update pipeline
        // picks them up.
        let dirty_rects_marked = rects.len();
        for rect in rects {
            self.mark_dirty_rect(rect);
        }

        DecorationInvalidationOutcome {
            invalidated_paragraphs: targeted.len(),
            dirty_rects_marked,
            all_rects_resolved: dirty_rects_marked == targeted.len(),
        }
    }

