    /// Measures text width using the cache to avoid redundant Canvas API calls.
    /// If the measurement is cached, returns the cached result immediately.
    /// Otherwise, calls the Canvas `measure_text` API and caches the result.
    ///
    /// The `font_descriptor` parameter is the CSS font string that should already
    /// be set on the context (e.g., "12pt Arial"). This is used as part of the
    /// cache key to differentiate measurements for different fonts.
    ///
    /// ## Performance
    ///
    /// This uses a fast-path lookup that avoids allocating strings on cache hits.
    /// Allocations only occur on cache misses when a new key needs to be stored.
    #[cfg_attr(feature = "otel", tracing::instrument(skip_all))]
    #[inline]
    fn measure_text_cached(&self, text: &str, font_descriptor: &str) -> Result<f64, JsValue> {
        // The Word-oracle override is test/tooling-only: it is engaged solely by
        // `set_word_oracle_advances` (the browser-word-oracle harness), never by
        // the production IDE/playground. Gate it behind an explicit flag so the
        // production measurement path is `cache -> canvas` with no oracle work.
        if self.word_oracle_active.get() {
            if let Some(width) = self.measure_text_from_word_oracle(text, font_descriptor) {
                return Ok(width);
            }
        }
        let mut cache = self.text_measure_cache.borrow_mut();
        cache.measure_with(self, text, font_descriptor)
    }

    /// Like [`Self::measure_text_cached`], but keyed by the caller's precomputed
    /// font-descriptor hash so cache hits resolve the interned font id from the
    /// hash (no per-lookup descriptor-string hashing / byte compare). See S4.
    #[cfg_attr(feature = "otel", tracing::instrument(skip_all))]
    #[inline]
    fn measure_text_cached_with_hash(
        &self,
        text: &str,
        font_descriptor: &str,
        font_descriptor_hash: u64,
    ) -> Result<f64, JsValue> {
        if self.word_oracle_active.get() {
            if let Some(width) = self.measure_text_from_word_oracle(text, font_descriptor) {
                return Ok(width);
            }
        }
        let mut cache = self.text_measure_cache.borrow_mut();
        cache.measure_with_hash(self, text, font_descriptor, font_descriptor_hash)
    }

    /// Interns a descriptor into this renderer's shared measure-cache interner,
    /// returning a stable id. Called once at applied-style resolution so direct
    /// layout measurements can key on the ids stored in `ResolvedRunStyle`.
    #[inline]
    fn intern_font_descriptor(&self, font_descriptor: &str) -> u32 {
        self.text_measure_cache
            .borrow()
            .interner()
            .borrow_mut()
            .intern(font_descriptor)
    }

    /// Like [`Self::measure_text_cached`], but keyed by an already-resolved
    /// interned `font_id` (from [`Self::intern_font_descriptor`]). Cache hits
    /// skip interning/hashing the descriptor entirely (S4).
    #[cfg_attr(feature = "otel", tracing::instrument(skip_all))]
    #[inline]
    fn measure_text_cached_with_id(
        &self,
        text: &str,
        font_descriptor: &str,
        font_id: u32,
    ) -> Result<f64, JsValue> {
        if self.word_oracle_active.get() {
            if let Some(width) = self.measure_text_from_word_oracle(text, font_descriptor) {
                return Ok(width);
            }
        }
        let mut cache = self.text_measure_cache.borrow_mut();
        cache.measure_with_id(self, text, font_descriptor, font_id)
    }

    /// Word-oracle measurement override. Only reachable when `word_oracle_active`
    /// is set (oracle/test mode); see [`Self::measure_text_cached`].
    fn measure_text_from_word_oracle(&self, text: &str, font_descriptor: &str) -> Option<f64> {
        let size_key = parse_font_descriptor_size_pt(font_descriptor).map(font_size_key);
        let advances = self.word_oracle_advances.borrow();
        let text_advances = self.word_oracle_text_advances.borrow();
        if let Some(advance) = size_key
            .as_ref()
            .and_then(|size_key| advances.get(&(size_key.clone(), text.to_string())))
            .or_else(|| text_advances.get(text))
        {
            return Some(*advance);
        }
        let mut width = 0.0_f64;
        for ch in text.chars() {
            let text = ch.to_string();
            let advance = size_key
                .as_ref()
                .and_then(|size_key| advances.get(&(size_key.clone(), text.clone())))
                .or_else(|| text_advances.get(&text))?;
            width += *advance;
        }
        Some(width)
    }

    pub fn set_word_oracle_advances(&mut self, advances: Vec<WordOracleAdvanceInput>) -> usize {
        let mut map = FxHashMap::default();
        let mut text_samples: FxHashMap<String, (f64, usize)> = FxHashMap::default();
        let mut paragraph_samples: FxHashMap<usize, FxHashMap<usize, f64>> = FxHashMap::default();
        for advance in advances {
            if !advance.size_pt.is_finite()
                || !advance.advance_pt.is_finite()
                || advance.advance_pt < 0.0
                || advance.text.is_empty()
            {
                continue;
            }
            let advance_px = points_to_px(advance.advance_pt as f32);
            if advance_px > 0.0 {
                let key = (font_size_key(advance.size_pt), advance.text.clone());
                map.insert(key, advance_px);
                let sample = text_samples.entry(advance.text.clone()).or_insert((0.0, 0));
                sample.0 += advance_px;
                sample.1 += 1;
            }
            if let (Some(paragraph_index), Some(text_offset)) =
                (advance.paragraph_index, advance.text_offset)
            {
                paragraph_samples
                    .entry(paragraph_index)
                    .or_default()
                    .insert(text_offset, advance_px);
            }
        }
        let text_map = text_samples
            .into_iter()
            .filter_map(|(text, (sum, count))| (count > 0).then_some((text, sum / count as f64)))
            .collect();
        let paragraph_map = paragraph_samples
            .into_iter()
            .map(|(paragraph_index, advances)| (paragraph_index, Rc::new(advances)))
            .collect();
        *self.word_oracle_advances.borrow_mut() = map;
        *self.word_oracle_text_advances.borrow_mut() = text_map;
        *self.word_oracle_paragraph_advances.borrow_mut() = paragraph_map;
        // Engage the oracle override only when text advances were actually
        // loaded; clearing (empty input) returns the renderer to the plain
        // production measurement path.
        self.word_oracle_active.set(
            !self.word_oracle_advances.borrow().is_empty()
                || !self.word_oracle_text_advances.borrow().is_empty(),
        );
        self.clear_text_measure_cache();
        self.clear_paragraph_wrap_cache();
        self.clear_paragraph_layout_cache();
        self.clear_paragraph_render_cache();
        self.skip_change_detection_once();
        self.word_oracle_advances.borrow().len()
    }

    pub fn word_oracle_advance_stats(&self) -> (usize, usize, usize, Vec<(usize, usize)>) {
        let paragraph_advances = self.word_oracle_paragraph_advances.borrow();
        let paragraph_advance_count = paragraph_advances
            .values()
            .map(|advances| advances.len())
            .sum();
        let mut paragraph_counts = paragraph_advances
            .iter()
            .map(|(paragraph, advances)| (*paragraph, advances.len()))
            .collect::<Vec<_>>();
        paragraph_counts.sort_by_key(|(paragraph, _)| *paragraph);
        (
            self.word_oracle_advances.borrow().len(),
            self.word_oracle_text_advances.borrow().len(),
            paragraph_advance_count,
            paragraph_counts,
        )
    }

    pub fn word_oracle_report_x_offset_count(&self) -> usize {
        self.word_oracle_report_x_offsets.borrow().len()
    }

