    #[inline]
    fn font_vertical_metrics_cached(
        &self,
        font_descriptor: &str,
        fallback_ascent: f64,
        fallback_descent: f64,
    ) -> Result<(f64, f64), JsValue> {
        if let Some(metrics) = self
            .font_vertical_metrics_cache
            .borrow()
            .get(font_descriptor)
            .copied()
        {
            return Ok(metrics);
        }

        self.set_host_font_if_changed(font_descriptor);
        // Representative sample with ascender/descender and East Asian glyph.
        let metrics = self.host.measure_text_metrics(VERTICAL_METRICS_SAMPLE)?;

        let ascent = if metrics.actual_bounding_box_ascent.is_finite()
            && metrics.actual_bounding_box_ascent > 0.0
        {
            metrics.actual_bounding_box_ascent
        } else if metrics.font_bounding_box_ascent.is_finite()
            && metrics.font_bounding_box_ascent > 0.0
        {
            metrics.font_bounding_box_ascent
        } else {
            fallback_ascent
        };

        let descent = if metrics.actual_bounding_box_descent.is_finite()
            && metrics.actual_bounding_box_descent > 0.0
        {
            metrics.actual_bounding_box_descent
        } else if metrics.font_bounding_box_descent.is_finite()
            && metrics.font_bounding_box_descent > 0.0
        {
            metrics.font_bounding_box_descent
        } else {
            fallback_descent
        };

        self.font_vertical_metrics_cache
            .borrow_mut()
            .insert(font_descriptor.to_string(), (ascent, descent));

        Ok((ascent, descent))
    }

    #[inline]
    fn font_line_box_height_cached(&self, font_descriptor: &str) -> Result<Option<f64>, JsValue> {
        if let Some(height) = self
            .font_line_box_height_cache
            .borrow()
            .get(font_descriptor)
            .copied()
        {
            return Ok(Some(height));
        }

        self.set_host_font_if_changed(font_descriptor);
        let metrics = self.host.measure_text_metrics(VERTICAL_METRICS_SAMPLE)?;
        let ascent = metrics.font_bounding_box_ascent;
        let descent = metrics.font_bounding_box_descent;
        if ascent.is_finite() && ascent > 0.0 && descent.is_finite() && descent >= 0.0 {
            let height = ascent + descent;
            self.font_line_box_height_cache
                .borrow_mut()
                .insert(font_descriptor.to_string(), height);
            return Ok(Some(height));
        }

        Ok(None)
    }

    /// Sets the canvas font only if it differs from the currently tracked font.
    /// This avoids redundant WASM→JS string decoding for repeated set_font calls
    /// with the same font descriptor.
    ///
    /// Returns `true` if the font was actually changed, `false` if skipped.
    #[inline]
    /// Sets the font on `painter` unless it is already active.
    ///
    /// The font is painter state, not renderer state, so it has to be applied to
    /// the surface being drawn on rather than to `self.host.context()`. With the
    /// canvas backend the two are the same object; with any other backend they
    /// are not, and setting it on the host would silently paint the run in
    /// whatever font that surface happened to have.
    /// Records `font_descriptor` as the active font, reporting whether that was
    /// a change.
    ///
    /// Tracking is separate from applying because the two have different
    /// destinations: painting applies to whichever [`Painter`] the caller
    /// passed, measurement applies to the host, which may have no painter at
    /// all.
    ///
    /// Both destinations share this one record, which is only sound while they
    /// are the same surface — today they always are, since the host's
    /// measurement default and every paint target are the one canvas. The
    /// record means "this descriptor has been applied", not "applied to X", so
    /// a host whose measurement surface is *not* its paint target (the native
    /// shaping backend, once it exists) has to keep the two in step itself, or
    /// a paint following a measurement of the same descriptor will skip a
    /// `set_font` it actually needed.
    fn record_font_if_changed(&self, font_descriptor: &str) -> bool {
        let mut current = self.current_font.borrow_mut();
        if current.as_deref() == Some(font_descriptor) {
            return false;
        }
        *current = Some(Rc::from(font_descriptor));
        true
    }

    fn set_font_if_changed<P: Painter>(&self, painter: &P, font_descriptor: &str) -> bool {
        let changed = self.record_font_if_changed(font_descriptor);
        if changed {
            painter.set_font(font_descriptor);
        }
        changed
    }

    /// [`Self::set_font_if_changed`] against the host rather than a painter.
    ///
    /// Measurement runs before anything is painted and must work on a host
    /// with no canvas, so it cannot go through [`CanvasRenderHost::painter`].
    fn set_host_font_if_changed(&self, font_descriptor: &str) -> bool {
        let changed = self.record_font_if_changed(font_descriptor);
        if changed {
            self.host.set_font(font_descriptor);
        }
        changed
    }

    #[inline]
    /// `Rc`-keyed variant of [`Self::set_font_if_changed`], which skips a string
    /// compare when the caller already holds the interned descriptor.
    fn set_font_if_changed_rc<P: Painter>(&self, painter: &P, font_descriptor: &Rc<str>) -> bool {
        let mut current = self.current_font.borrow_mut();
        if current.as_ref().is_some_and(|active| {
            Rc::ptr_eq(active, font_descriptor) || active.as_ref() == font_descriptor.as_ref()
        }) {
            return false;
        }
        painter.set_font(font_descriptor);
        *current = Some(font_descriptor.clone());
        true
    }

    /// Resets the font state tracker. Call this after operations that may
    /// change the canvas context state externally (e.g., save/restore).
    #[inline]
    #[allow(dead_code)]
    fn reset_font_state(&self) {
        *self.current_font.borrow_mut() = None;
    }

    /// Sets the canvas fill style only when it differs from the cached value.
    #[inline]
    fn set_fill_style_if_changed(&self, color: &str) -> bool {
        let mut current = self.current_fill_color.borrow_mut();
        if current.as_deref() == Some(color) {
            return false;
        }
        self.host.painter().set_fill_style_str(color);
        *current = Some(Rc::from(color));
        true
    }

    /// Invalidates the fill style cache (e.g., after `context.restore()`).
    #[inline]
    fn reset_fill_style_state(&self) {
        *self.current_fill_color.borrow_mut() = None;
    }

    /// Invalidates the renderer-side font + fill-style trackers after switching
    /// to a different page canvas/context.
    ///
    /// The host may now *skip* re-applying the default font/fill when it
    /// activates a page whose backing store is unchanged (see
    /// `render_host::OffscreenRenderHost::activate_extra_canvas`). In that case
    /// the activated context keeps whatever font/fill it last held, which may
    /// differ from this renderer's cached belief (a single tracker shared across
    /// all pages). Clearing the trackers here forces the next
    /// `set_font_if_changed` / `set_fill_style_if_changed` to issue a real
    /// `set_font` / `set_fill_style`, so the context is deterministically
    /// (re)configured before the first glyph of the new page is drawn. This is
    /// strictly safer than the previous behavior, where the host reset the
    /// context font to the default while the shared tracker still believed the
    /// previous page's font.
    #[inline]
    fn invalidate_context_state_tracking(&self) {
        *self.current_font.borrow_mut() = None;
        *self.current_fill_color.borrow_mut() = None;
    }

