    #[cfg(test)]
    fn advance_grapheme_context(
        text: &str,
        prev_prev_grapheme: &mut Option<String>,
        prev_grapheme: &mut Option<String>,
    ) {
        for grapheme in text.graphemes(true) {
            *prev_prev_grapheme = prev_grapheme.take();
            *prev_grapheme = Some(grapheme.to_string());
        }
    }

    #[allow(clippy::too_many_arguments)]
    /// Draws `text` starting at `x`, applying per-grapheme advance adjustments.
    ///
    /// Generic over the painter so the caller's surface is the one drawn on;
    /// the font is set on that same surface rather than on the host's, which
    /// is what makes passing a surface other than the host's meaningful.
    fn draw_text_with_spacing<P>(
        &self,
        context: &P,
        text: &str,
        mut x: f64,
        y: f64,
        letter_spacing: f64,
        style: &AppliedRunStyle,
        paragraph_style: Option<&ParagraphStyle>,
        initial_prev_prev_grapheme: Option<&str>,
        initial_prev_grapheme: Option<&str>,
        initial_prev_glyph_width: Option<f64>,
        next_grapheme_after_segment: Option<&str>,
    ) -> Result<(f64, TextAdvanceState), JsValue>
    where
        P: Painter,
        P::Error: PainterError,
    {
        if text.is_empty() {
            return Ok((
                0.0,
                TextAdvanceState {
                    prev_prev_grapheme: initial_prev_prev_grapheme.map(CompactString::new),
                    prev_grapheme: initial_prev_grapheme.map(CompactString::new),
                    prev_adjusted_glyph_width: initial_prev_glyph_width,
                    ..TextAdvanceState::default()
                },
            ));
        }

        // Table rendering temporarily switches baseline to "top".
        // Keep body text on alphabetic baseline even if context state leaked.
        context.set_text_baseline("alphabetic");

        let draw_enabled = self.should_draw_current_page_for_render();

        let mut width = 0.0;
        let mut snap_to_chars_cell_width_cache = FxHashMap::default();
        let initial_state = TextAdvanceState {
            prev_prev_grapheme: initial_prev_prev_grapheme.map(CompactString::new),
            prev_grapheme: initial_prev_grapheme.map(CompactString::new),
            prev_adjusted_glyph_width: initial_prev_glyph_width,
            ..TextAdvanceState::default()
        };
        let resolved_override;
        let resolved_run_style = if (letter_spacing - style.letter_spacing_px).abs() < f64::EPSILON
        {
            self.resolved_run_style(style)
        } else {
            resolved_override = {
                let mut resolved = self.resolved_run_style(style).clone();
                resolved.letter_spacing_px = letter_spacing;
                resolved
            };
            &resolved_override
        };

        let end_state = walk_text_advance_steps(
            self,
            text,
            resolved_run_style,
            paragraph_style,
            &initial_state,
            next_grapheme_after_segment,
            &mut snap_to_chars_cell_width_cache,
            |step| {
                // Advances come from the measurer, which sets its own font, so
                // an undrawn line (band cull, undrawn page) needs no painter font.
                if draw_enabled {
                    self.set_font_if_changed(context, step.font_descriptor);
                }
                let leading_advance = step.advance.implicit_latin_gap
                    + step.advance.implicit_numeric_gap
                    + step.advance.kerning_adjustment
                    + step.advance.snap_leading;
                if leading_advance.abs() > f64::EPSILON {
                    x += leading_advance;
                    width += leading_advance;
                }
                if draw_enabled {
                    if (style.text_scale_x - 1.0).abs() > f64::EPSILON {
                        context.save();
                        context
                            .translate(x, y)
                            .map_err(PainterError::into_js_value)?;
                        context
                            .scale(style.text_scale_x, 1.0)
                            .map_err(PainterError::into_js_value)?;
                        context
                            .fill_text(step.grapheme, 0.0, 0.0)
                            .map_err(PainterError::into_js_value)?;
                        context.restore();
                    } else {
                        context
                            .fill_text(step.grapheme, x, y)
                            .map_err(PainterError::into_js_value)?;
                    }
                }
                x += step.advance.glyph_box_width;
                width += step.advance.glyph_box_width;
                Ok(())
            },
        )?;

        Ok((width, end_state))
    }

    /// The width [`Self::draw_text_with_spacing`] returns for `text` with no
    /// neighbouring graphemes, without touching any painter.
    fn text_width_with_spacing(
        &self,
        text: &str,
        letter_spacing: f64,
        style: &AppliedRunStyle,
    ) -> Result<f64, JsValue> {
        if text.is_empty() {
            return Ok(0.0);
        }
        let resolved_override;
        let resolved_run_style = if (letter_spacing - style.letter_spacing_px).abs() < f64::EPSILON
        {
            self.resolved_run_style(style)
        } else {
            resolved_override = {
                let mut resolved = self.resolved_run_style(style).clone();
                resolved.letter_spacing_px = letter_spacing;
                resolved
            };
            &resolved_override
        };
        let mut width = 0.0;
        walk_text_advance_steps(
            self,
            text,
            resolved_run_style,
            None,
            &TextAdvanceState::default(),
            None,
            &mut FxHashMap::default(),
            |step| {
                let leading_advance = step.advance.implicit_latin_gap
                    + step.advance.implicit_numeric_gap
                    + step.advance.kerning_adjustment
                    + step.advance.snap_leading;
                if leading_advance.abs() > f64::EPSILON {
                    width += leading_advance;
                }
                width += step.advance.glyph_box_width;
                Ok(())
            },
        )?;
        Ok(width)
    }

    #[allow(dead_code)]
    fn measure_text_with_spacing(
        &self,
        text: &str,
        style: &AppliedRunStyle,
        paragraph_style: Option<&ParagraphStyle>,
    ) -> Result<f64, JsValue> {
        if text.is_empty() {
            return Ok(0.0);
        }
        let segment = TextSegment {
            text: text.to_string(),
            start: 0,
            end: text.len(),
            properties: None,
            revision: None,
            hyperlink: None,
            leading_width: 0.0,
        };
        let render_pass_arena = Rc::clone(&self.render_pass_arena);
        let render_pass_arena = render_pass_arena.borrow();
        let planned = self.build_fragment_layout(
            &render_pass_arena,
            &segment,
            style,
            paragraph_style,
            None,
            None,
            None,
            None,
        )?;
        Ok(planned.width)
    }

    fn underline_spans_for_text(
        &self,
        text: &str,
        style: &AppliedRunStyle,
        width: f64,
    ) -> Result<Vec<(f64, f64)>, JsValue> {
        if !style
            .underline_kind
            .as_deref()
            .is_some_and(|kind| kind.eq_ignore_ascii_case("words"))
        {
            return Ok((width.is_finite() && width > 0.0)
                .then_some((0.0, width))
                .into_iter()
                .collect());
        }
        let segment = TextSegment {
            text: text.to_string(),
            start: 0,
            end: text.len(),
            properties: None,
            revision: None,
            hyperlink: None,
            leading_width: 0.0,
        };
        let render_pass_arena = Rc::clone(&self.render_pass_arena);
        let render_pass_arena = render_pass_arena.borrow();
        let planned = self.build_fragment_layout(
            &render_pass_arena,
            &segment,
            style,
            None,
            None,
            None,
            None,
            None,
        )?;
        Ok(underline_spans_for_planned_glyphs(
            style.underline_kind.as_deref(),
            text,
            &planned.glyph_steps,
            width,
        ))
    }

    fn numbering_first_line_ascent(&self, numbering: &PendingNumberingRender) -> Option<f64> {
        if jade_docx_layout::line_metrics::word_layout_platform()
            != jade_docx_layout::line_metrics::WordLayoutPlatform::Mac
        {
            return None;
        }
        let style = self.resolve_applied_run_style_cached(numbering.display_props.as_ref());
        let mut ascent: Option<f64> = None;
        let mut previous_descriptor = None;
        let mut previous_ascent = None;
        for text in numbering
            .deleted_text
            .iter()
            .map(String::as_str)
            .chain(std::iter::once(numbering.display_text.as_str()))
        {
            for grapheme in text
                .graphemes(true)
                .filter(|g| !g.chars().all(char::is_whitespace))
            {
                let script = jade_docx_layout::line_wrap::classify_script(grapheme);
                let descriptor = style.resolved.descriptor_for_grapheme(grapheme, script);
                if previous_descriptor != Some(descriptor) {
                    previous_descriptor = Some(descriptor);
                    previous_ascent =
                        jade_docx_layout::line_metrics::word_numbering_font_ascent_px(descriptor);
                }
                let value = (previous_ascent? - style.baseline_shift_px).max(0.0);
                ascent = Some(ascent.map_or(value, |current| current.max(value)));
            }
        }
        ascent
    }

    /// Content top offset and height of an empty paragraph's line. A numbered
    /// one holds its label; where text lines take Word's line box per face
    /// (`word_line_box`), so does the label, over every glyph including its
    /// spaces.
    fn empty_paragraph_content_metrics(
        &mut self,
        pending_numbering: Option<&PendingNumberingRender>,
        line_height: f64,
        word_line_box: bool,
    ) -> Result<(f64, f64), JsValue> {
        if let Some(numbering) = pending_numbering {
            let mut metric_text = String::new();
            if let Some(deleted_text) = numbering.deleted_text.as_deref() {
                metric_text.push_str(deleted_text);
            }
            metric_text.push_str(&numbering.display_text);

            if !metric_text.is_empty() {
                let style = self.apply_run_style(numbering.display_props.as_ref())?;
                if word_line_box {
                    let mut extent: Option<(f64, f64)> = None;
                    for grapheme in metric_text.graphemes(true) {
                        let script = jade_docx_layout::line_wrap::classify_script(grapheme);
                        let descriptor = style.resolved.descriptor_for_grapheme(grapheme, script);
                        let Some((ascent, descent)) =
                            jade_docx_layout::line_metrics::word_font_vertical_metrics_px(
                                descriptor,
                            )
                        else {
                            extent = None;
                            break;
                        };
                        extent =
                            Some(extent.map_or((ascent, descent), |(a, d)| {
                                (a.max(ascent), d.max(descent))
                            }));
                    }
                    if let Some((ascent, descent)) = extent {
                        let shift = style.baseline_shift_px;
                        return Ok((shift - ascent, (ascent + descent).max(1.0)));
                    }
                }
                let metric_text_len = metric_text.len();
                let segment = TextSegment {
                    text: metric_text,
                    start: 0,
                    end: metric_text_len,
                    properties: numbering.display_props.clone().map(Rc::new),
                    revision: None,
                    hyperlink: None,
                    leading_width: 0.0,
                };
                let render_pass_arena = Rc::clone(&self.render_pass_arena);
                let render_pass_arena = render_pass_arena.borrow();
                let planned = self.build_fragment_layout(
                    &render_pass_arena,
                    &segment,
                    &style,
                    None,
                    None,
                    None,
                    None,
                    None,
                )?;
                let content_height = (planned.bottom_offset - planned.top_offset).max(1.0);
                return Ok((planned.top_offset, content_height));
            }
        }

        Ok((-line_height * 0.8, line_height.max(1.0)))
    }

    /// Draws a margin line number (`w:lnNumType`, §17.6.8) for the current
    /// wrapped line. The number is right-aligned `distance` left of the text
    /// margin and shares the line baseline. It is emitted both immediately and
    /// through shared glyph commands so it replays through the paragraph draw cache.
    fn draw_line_number(
        &mut self,
        number: u32,
        baseline_y: f64,
        distance_px: f64,
        commands_out: &mut Option<&mut Vec<DrawCommand>>,
        paragraph_index: usize,
        text_margin_x: f64,
    ) -> Result<(), JsValue> {
        let text = number.to_string();
        let props = Rc::clone(self.line_number_run_properties.get_or_insert_with(|| {
            let direct = self.styles_part.as_ref().and_then(|styles| {
                styles
                    .resolve_character_style_id("Line Number")
                    .map(|id| RunProperties {
                        style: Some(id.into()),
                        ..Default::default()
                    })
            });
            Rc::new(
                self.styles_part
                    .as_ref()
                    .and_then(|styles| {
                        styles.resolve_effective_run_properties(None, direct.as_ref())
                    })
                    .unwrap_or_default(),
            )
        }));
        let style = self.apply_run_style(Some(props.as_ref()))?;
        let text_y = baseline_y + style.baseline_shift_px;
        self.draw_numbering_text_plan(
            (&text, paragraph_index),
            (text_margin_x - distance_px, text_y),
            Some(props.as_ref()),
            &style,
            NumberingTextContext {
                paragraph_style: None,
                suffix_space: false,
                following_grapheme: None,
                margin_line_number: true,
            },
            commands_out,
        )?;
        Ok(())
    }

    fn build_numbering_layout<'arena>(
        &self,
        arena: &'arena Bump,
        text: &str,
        style: &AppliedRunStyle,
        context: NumberingTextContext<'_>,
        ink_bounds: FragmentInkBounds,
    ) -> Result<PlannedSegmentLayout<'arena>, JsValue> {
        let marker_style = context
            .paragraph_style
            .map(ParagraphStyle::for_numbering_marker);
        let paragraph_style = marker_style.as_deref();
        let suffix_start = context
            .suffix_space
            .then(|| text.strip_suffix(' '))
            .flatten()
            .map(str::len);
        let label_end = suffix_start.unwrap_or(text.len());
        let segment = TextSegment {
            text: text[..label_end].to_string(),
            start: 0,
            end: label_end,
            properties: None,
            revision: None,
            hyperlink: None,
            leading_width: 0.0,
        };
        let mut plan = self.build_fragment_layout_with_ink_bounds(
            arena,
            &segment,
            style,
            paragraph_style,
            None,
            None,
            None,
            if suffix_start.is_some() {
                Some(" ")
            } else {
                context.following_grapheme
            },
            ink_bounds,
        )?;
        if suffix_start.is_none() {
            return Ok(plan);
        }

        // The generated separator uses the high-ANSI face, while the label
        // retains its ASCII/East Asian font slots. Both advances still come
        // from the shared layout walk, including grid pitch and tracking.
        let mut suffix_style = style.clone();
        let mut resolved = (*style.resolved).clone();
        if let Some(descriptor) =
            jade_docx_layout::line_metrics::word_numbering_suffix_space_descriptor(
                &resolved.font_descriptor_latin_hansi,
            )
        {
            // Word for Mac: an Arial-width space whatever the label's faces.
            let descriptor: Rc<str> = Rc::from(descriptor);
            resolved = jade_docx_layout::font_resolver::ResolvedRunStyle::new(
                Rc::clone(&descriptor),
                descriptor,
                Rc::clone(&resolved.font_descriptor_east_asia),
                Rc::clone(&resolved.font_descriptor_complex),
                resolved.letter_spacing_px,
                resolved.text_scale_x,
                resolved.enable_pair_kerning,
                None,
            );
        } else {
            resolved.font_descriptor_latin_ascii = Rc::clone(&resolved.font_descriptor_latin_hansi);
            resolved.font_descriptor_latin_ascii_hash = resolved.font_descriptor_latin_hansi_hash;
            resolved.font_descriptor_latin_ascii_id = resolved.font_descriptor_latin_hansi_id;
            resolved.font_hint = None;
        }
        suffix_style.resolved = Rc::new(resolved);
        let suffix_segment = TextSegment {
            text: " ".into(),
            start: label_end,
            end: text.len(),
            properties: None,
            revision: None,
            hyperlink: None,
            leading_width: 0.0,
        };
        let suffix = self.build_fragment_layout_with_ink_bounds(
            arena,
            &suffix_segment,
            &suffix_style,
            paragraph_style,
            None,
            None,
            None,
            context.following_grapheme,
            ink_bounds,
        )?;
        let mut glyphs = plan.fragment.glyphs.to_vec();
        glyphs.extend(suffix.fragment.glyphs.iter().cloned().map(|mut glyph| {
            glyph.x += plan.width;
            glyph
        }));
        for mut step in suffix.glyph_steps {
            step.text_start += label_end as u32;
            step.text_end += label_end as u32;
            step.x_offset += plan.width;
            step.font_slot = ResolvedFontSlot::LatinHansi;
            plan.glyph_steps.push(step);
        }
        plan.width += suffix.width;
        plan.fragment.end = text.len();
        plan.fragment.width = plan.width;
        plan.fragment.glyphs = glyphs.into();
        plan.top_offset = plan.top_offset.min(suffix.top_offset);
        plan.bottom_offset = plan.bottom_offset.max(suffix.bottom_offset);
        plan.end_state = suffix.end_state;
        Ok(plan)
    }

    fn measure_numbering_text_plan(
        &self,
        text: &str,
        style: &AppliedRunStyle,
        context: NumberingTextContext<'_>,
    ) -> Result<f64, JsValue> {
        let arena = Rc::clone(&self.render_pass_arena);
        let arena = arena.borrow();
        // Advance measurement consumes no vertical ink bounds. This also
        // avoids initializing fallback glyphs absent from the marker text.
        let plan =
            self.build_numbering_layout(&arena, text, style, context, FragmentInkBounds::Unused)?;
        Ok(plan.width)
    }

    // Numbering has no wrapped-line clusters. Retain the shared advance plan
    // for cache replay instead of letting Text regroup and space it again.
    #[allow(clippy::too_many_arguments)]
    fn draw_numbering_text_plan(
        &mut self,
        source: (&str, usize),
        position: (f64, f64),
        props: Option<&RunProperties>,
        style: &AppliedRunStyle,
        context: NumberingTextContext<'_>,
        commands_out: &mut Option<&mut Vec<DrawCommand>>,
    ) -> Result<f64, JsValue> {
        let (text, paragraph_index) = source;
        let arena = Bump::new();
        // Marker painting consumes advances only; auxiliary capture is the
        // sole consumer of this plan's vertical ink box. Empty numbered
        // paragraphs resolve their content box separately before painting.
        let ink_bounds = if self.auxiliary_story_capture_mode.enabled()
            && self.should_draw_current_page_for_render()
        {
            FragmentInkBounds::Measure
        } else {
            FragmentInkBounds::Unused
        };
        let plan = self.build_numbering_layout(&arena, text, style, context, ink_bounds)?;
        // distance measures from the right edge of a margin line number to
        // the column's text margin. The shared glyph plan owns its width.
        let position = if context.margin_line_number {
            ((position.0 - plan.width).max(2.0), position.1)
        } else {
            position
        };
        let text_style = self.cmd_text_style(props, style);
        if let Some(buf) = commands_out.as_deref_mut() {
            self.push_text_commands_for_plan(
                buf,
                position.0,
                position.1,
                &text_style,
                text,
                &plan.glyph_steps,
            );
        }
        self.draw_planned_text(
            &self.host.painter(),
            position.0,
            position.1,
            &text_style,
            (text, style.resolved.as_ref()),
            &plan.glyph_steps,
        )
        .map_err(PainterError::into_js_value)?;
        if self.auxiliary_story_capture_mode.enabled() && self.should_draw_current_page_for_render()
        {
            // Reuse the painted plan; markers must not enter editable body offsets.
            let page = self.current_page_number.saturating_sub(1);
            let top = position.1 + plan.top_offset - style.baseline_shift_px;
            self.auxiliary_story_debug_lines
                .push(AuxiliaryStoryLineDebug {
                    story: if context.margin_line_number {
                        "line_number"
                    } else {
                        "numbering"
                    },
                    page,
                    line: LayoutLineDebug {
                        paragraph: paragraph_index,
                        line: 0,
                        page,
                        column_index: self.column_index,
                        vertical: false,
                        start: 0,
                        end: text.len(),
                        text: text.to_string(),
                        top,
                        absolute_top: self.page_offset_y + top,
                        height: plan.bottom_offset - plan.top_offset,
                        baseline: position.1,
                        absolute_baseline: self.page_offset_y + position.1,
                        report_x_offset: 0.0,
                        start_x: position.0,
                        end_x: position.0 + plan.width,
                        cursor_end_x: position.0 + plan.width,
                        visual_end_x: position.0 + plan.width,
                        allowed_trailing_overflow_width: 0.0,
                        fragments: vec![LayoutFragmentDebug {
                            start: 0,
                            end: text.len(),
                            x: position.0,
                            width: plan.width,
                            baseline: position.1,
                            glyphs: plan
                                .fragment
                                .glyphs
                                .iter()
                                .map(|glyph| LayoutGlyphDebug {
                                    start: glyph.start,
                                    end: glyph.end,
                                    text: text[glyph.start..glyph.end].to_string(),
                                    x: glyph.x,
                                    width: glyph.width,
                                })
                                .collect(),
                        }],
                        tab_leaders: Vec::new(),
                        tab_stops: Vec::new(),
                    },
                });
        }
        Ok(plan.width)
    }

    fn draw_pending_numbering_marker(
        &mut self,
        pending: &PendingNumberingRender,
        baseline_y: f64,
        line_height: f64,
        paragraph_style: Option<&ParagraphStyle>,
        commands_out: &mut Option<&mut Vec<DrawCommand>>,
    ) -> Result<(), JsValue> {
        const DELETED_INSERT_GAP_PX: f64 = 4.0;
        let context = self.host.painter();
        let mut current_x = pending.number_x;
        let numbering_context = NumberingTextContext {
            margin_line_number: false,
            paragraph_style,
            suffix_space: pending.suffix_space,
            following_grapheme: pending.following_grapheme.as_deref(),
        };

        if let Some(deleted_text) = pending.deleted_text.as_deref() {
            let mut deleted_props = pending.display_props.clone().unwrap_or_default();
            deleted_props.strike = Some(true);
            if deleted_props.color.is_none() {
                deleted_props.color = Some(REVISION_DELETED_COLOR.into());
            }
            let deleted_props = Some(deleted_props);
            let deleted_style = self.apply_run_style(deleted_props.as_ref())?;
            let deleted_text_y = baseline_y + deleted_style.baseline_shift_px;
            let deleted_width = self.draw_numbering_text_plan(
                (deleted_text, pending.paragraph_index),
                (current_x, deleted_text_y),
                deleted_props.as_ref(),
                &deleted_style,
                numbering_context,
                commands_out,
            )?;
            if deleted_style.strike || deleted_style.double_strike {
                self.draw_strike_through(
                    &context,
                    current_x,
                    deleted_text_y,
                    deleted_width,
                    deleted_style.font_size_pt,
                    deleted_style.double_strike,
                )
                .map_err(PainterError::into_js_value)?;
            }
            let deleted_height = line_height.max(1.0);
            self.revision_debug_regions
                .borrow_mut()
                .push(RevisionDebugInfo {
                    page: self.current_page_number,
                    kind: RevisionDebugKind::Deleted,
                    x: current_x,
                    y: self.page_offset_y + (baseline_y - line_height),
                    width: deleted_width,
                    height: deleted_height,
                    text: deleted_text.to_string(),
                });

            if let Some(buf) = commands_out.as_deref_mut() {
                let text_style = self.cmd_text_style(deleted_props.as_ref(), &deleted_style);
                if deleted_style.strike || deleted_style.double_strike {
                    buf.push(DrawCommand::StrikeThrough {
                        x: current_x,
                        y: deleted_text_y,
                        width: deleted_width,
                        font_size_pt: deleted_style.font_size_pt,
                        color: text_style.fill_color,
                        double: deleted_style.double_strike,
                    });
                }
            }
            current_x += deleted_width + DELETED_INSERT_GAP_PX;
        }

        if let Some(picture) = pending.picture.as_ref() {
            // The picture sits on the line's baseline, where the bullet's
            // glyph would.
            let image = RunImage {
                data_uri: Some(picture.data_uri.clone()),
                ..RunImage::default()
            };
            return self.draw_image_element(
                &image,
                ImageDrawSpec {
                    x: current_x,
                    y: baseline_y - picture.height * 0.85,
                    width: picture.width,
                    height: picture.height,
                    rotation_deg: 0.0,
                    flip_horizontal: false,
                    flip_vertical: false,
                    crop: None,
                    paragraph_index: pending.paragraph_index,
                    run_index: usize::MAX,
                },
            );
        }

        let style = self.apply_run_style(pending.display_props.as_ref())?;
        let text_y = baseline_y + style.baseline_shift_px;
        let marker_width = self.draw_numbering_text_plan(
            (pending.display_text.as_str(), pending.paragraph_index),
            (current_x, text_y),
            pending.display_props.as_ref(),
            &style,
            numbering_context,
            commands_out,
        )?;
        self.band_guard_numbering_marker(pending.paragraph_index, baseline_y, &style);
        if style.strike || style.double_strike {
            self.draw_strike_through(
                &context,
                current_x,
                text_y,
                marker_width,
                style.font_size_pt,
                style.double_strike,
            )
            .map_err(PainterError::into_js_value)?;
        }
        let underline_spans = if style.underline {
            self.underline_spans_for_text(&pending.display_text, &style, marker_width)?
        } else {
            Vec::new()
        };
        if style.underline {
            for &(offset, underline_width) in &underline_spans {
                self.draw_underline(
                    &context,
                    current_x + offset,
                    text_y,
                    underline_width,
                    style.font_size_pt,
                    style.underline_kind.as_deref(),
                    style.underline_color.as_deref(),
                )
                .map_err(PainterError::into_js_value)?;
            }
        }
        if let Some(buf) = commands_out.as_deref_mut() {
            let text_style = self.cmd_text_style(pending.display_props.as_ref(), &style);
            if style.strike || style.double_strike {
                buf.push(DrawCommand::StrikeThrough {
                    x: current_x,
                    y: text_y,
                    width: marker_width,
                    font_size_pt: style.font_size_pt,
                    color: text_style.fill_color.clone(),
                    double: style.double_strike,
                });
            }
            if style.underline {
                let underline_color = style
                    .underline_color
                    .clone()
                    .unwrap_or(text_style.fill_color);
                for &(offset, underline_width) in &underline_spans {
                    buf.push(DrawCommand::Underline {
                        x: current_x + offset,
                        y: text_y,
                        width: underline_width,
                        font_size_pt: style.font_size_pt,
                        color: underline_color.clone(),
                        kind: style.underline_kind.clone(),
                    });
                }
            }
        }

        self.numbering_debug_regions
            .borrow_mut()
            .push(NumberingDebugInfo {
                page: self.current_page_number,
                paragraph: pending.paragraph_index,
                x: pending.number_x,
                y: self.page_offset_y + (baseline_y - line_height),
                width: (current_x + marker_width - pending.number_x).max(0.0),
                height: line_height.max(1.0),
                text: pending.display_text.clone(),
            });

        Ok(())
    }

    /// Draws `w:strike` / `w:dstrike` (ECMA-376 Part 1 §17.3.2.9 / §17.3.2.37).
    ///
    /// The line sits 0.3em above the baseline, which is roughly half of Noto's
    /// x-height and matches where Word places it. `double` keeps that position
    /// as the centre and puts one line either side rather than shifting the
    /// single line, so a run does not appear to move when `w:dstrike` is
    /// toggled. Line weight is 0.05em with a 1px floor so the rule stays
    /// visible at small sizes.
    fn draw_strike_through<P: Painter>(
        &self,
        context: &P,
        start_x: f64,
        baseline_y: f64,
        width: f64,
        font_size_pt: f32,
        double: bool,
    ) -> Result<(), P::Error> {
        if width <= 0.0 {
            return Ok(());
        }
        if !self.should_draw_current_page_for_render() {
            return Ok(());
        }

        let font_px = points_to_px(font_size_pt);
        let strike_y = baseline_y - font_px * 0.3;
        context.save();
        // Decorations take the colour of the text they belong to, which the
        // caller has already set as the fill style.
        context.use_fill_style_for_stroke();
        context.set_line_width((font_px * 0.05).max(1.0));
        context.begin_path();
        if double {
            // Two parallel lines straddling the single-strike baseline
            // (`w:dstrike`, ECMA-376 Part 1 §17.3.2.9).
            let gap = (font_px * 0.06).max(1.0);
            context.move_to(start_x, strike_y - gap);
            context.line_to(start_x + width, strike_y - gap);
            context.move_to(start_x, strike_y + gap);
            context.line_to(start_x + width, strike_y + gap);
        } else {
            context.move_to(start_x, strike_y);
            context.line_to(start_x + width, strike_y);
        }
        context.stroke();
        context.restore();

        Ok(())
    }

    /// Draws `w:em` emphasis marks (ECMA-376 Part 1 §17.3.2.12) — a small
    /// mark centered above (or, for `underDot`, below) each non-blank glyph in
    /// the segment. Emits one [`DrawCommand::EmphasisMark`] per mark so the
    /// cache-replay path reproduces identical geometry.
    #[allow(clippy::too_many_arguments)]
    fn draw_emphasis_marks<P: Painter>(
        &self,
        context: &P,
        start_x: f64,
        baseline_y: f64,
        top_offset: f64,
        bottom_offset: f64,
        segment_width: f64,
        font_size_pt: f32,
        segment_text: &str,
        glyph_steps: &[PlannedGlyphLayoutStep],
        mark: EmphasisMark,
        color: &str,
        commands_out: Option<&mut Vec<DrawCommand>>,
    ) -> Result<(), P::Error> {
        let glyphs: Vec<(f64, bool)> = glyph_steps
            .iter()
            .map(|step| (step.x_offset, step.text(segment_text).trim().is_empty()))
            .collect();
        let centers = emphasis_mark_center_offsets(&glyphs, segment_width);
        if centers.is_empty() {
            return Ok(());
        }

        let radius = emphasis_mark_radius(font_size_pt);
        let font_px = points_to_px(font_size_pt);
        let gap = (font_px * 0.06).max(1.0);
        let center_y = if mark.is_below() {
            baseline_y + bottom_offset + radius + gap
        } else {
            baseline_y + top_offset - radius - gap
        };
        let filled = mark.is_filled();
        let draw_now = self.should_draw_current_page_for_render();
        let two_pi = std::f64::consts::PI * 2.0;

        let mut commands_out = commands_out;
        for offset in centers {
            let cx = start_x + offset;
            if draw_now {
                context.save();
                context.begin_path();
                context.arc(cx, center_y, radius, 0.0, two_pi)?;
                if filled {
                    context.set_fill_style_str(color);
                    context.fill();
                } else {
                    context.set_stroke_style_str(color);
                    context.set_line_width((radius * 0.5).max(1.0));
                    context.stroke();
                }
                context.restore();
            }
            if let Some(buf) = commands_out.as_deref_mut() {
                buf.push(DrawCommand::EmphasisMark {
                    x: cx,
                    y: center_y,
                    radius,
                    filled,
                    color: Rc::from(color),
                });
            }
        }
        if draw_now {
            self.reset_fill_style_state();
        }

        Ok(())
    }

    /// Draws the ruby guide (`w:ruby`, ECMA-376 Part 1 §17.3.3.25) over its
    /// base segment and returns the guide baseline and characters.
    /// Shared layout already widened the base to a wider guide
    /// (`jade_docx_layout::ruby`); a narrower guide spreads over the base by
    /// `w:rubyAlign`. Its baseline sits `w:hpsRaise` above the base baseline,
    /// in whole points. Visual-only: the guide is not selectable content
    /// (matching Word). Emitted both immediately and as `DrawCommand::Text`s so
    /// it replays through the paragraph draw cache.
    #[allow(clippy::too_many_arguments)]
    fn draw_ruby_text(
        &self,
        ruby: &ResolvedRuby,
        segment_x: f64,
        segment_width: f64,
        baseline_y: f64,
        top_offset: f64,
        base_color: &str,
        commands_out: Option<&mut Vec<DrawCommand>>,
    ) -> Result<(f64, Vec<RubyGuideGlyph>), JsValue> {
        if ruby.text.is_empty() {
            return Ok((baseline_y, Vec::new()));
        }
        let props = Some(RunProperties {
            color: Some(base_color.to_string().into()),
            ..(*ruby.properties).clone()
        });
        let style = self.apply_run_style(props.as_ref())?;
        let mut glyphs = Vec::new();
        for grapheme in ruby.text.graphemes(true) {
            let width = self.measure_text_with_spacing(grapheme, &style, None)?;
            glyphs.push(RubyGuideGlyph {
                text: grapheme.to_string(),
                x: 0.0,
                width,
            });
        }
        let guide_width: f64 = glyphs.iter().map(|glyph| glyph.width).sum();
        let (leading, gap) = jade_docx_layout::ruby::ruby_distribution(
            ruby.align.as_deref(),
            glyphs.len(),
            segment_width - guide_width,
        );
        let mut x = segment_x + leading;
        for glyph in &mut glyphs {
            glyph.x = x;
            x += glyph.width + gap;
        }
        let y = match ruby.raise_pt {
            Some(raise) => baseline_y - points_to_px(raise),
            None => {
                // Without `w:hpsRaise` the guide baseline sits just above the
                // base glyph-box top, leaving room for its own descenders.
                let guide_px = points_to_px(ruby.size_pt);
                baseline_y + top_offset - (guide_px * 0.2).max(1.0)
            }
        };
        let context = self.host.painter();
        let text_style = self.cmd_text_style(props.as_ref(), &style);
        let mut commands_out = commands_out;
        for RubyGuideGlyph { text, x, .. } in &glyphs {
            self.draw_text_with_spacing(
                &context,
                text,
                *x,
                y,
                style.letter_spacing_px,
                &style,
                None,
                None,
                None,
                None,
                None,
            )?;
            if let Some(buf) = commands_out.as_deref_mut() {
                buf.push(DrawCommand::Text {
                    text: Rc::from(text.as_str()),
                    x: *x,
                    y,
                    style: text_style.clone(),
                });
            }
        }
        Ok((y, glyphs))
    }

    /// Records a drawn ruby guide for full-layout captures, like tab leaders:
    /// it paints outside editable text offsets.
    fn capture_ruby_guide(
        &mut self,
        baseline: f64,
        glyphs: &[RubyGuideGlyph],
        paragraph: usize,
        line_index: usize,
        line: &SelectionLineLayout,
    ) {
        if !self.auxiliary_story_capture_mode.enabled()
            || !self.should_draw_current_page_for_render()
            || glyphs.is_empty()
        {
            return;
        }
        let start_x = glyphs[0].x;
        let end_x = glyphs.last().map_or(start_x, |glyph| glyph.x + glyph.width);
        let mut text = String::new();
        let mut debug_glyphs = Vec::with_capacity(glyphs.len());
        for glyph in glyphs {
            let start = text.len();
            text.push_str(&glyph.text);
            debug_glyphs.push(LayoutGlyphDebug {
                start,
                end: text.len(),
                text: glyph.text.clone(),
                x: glyph.x - start_x,
                width: glyph.width,
            });
        }
        let page = self.current_page_number.saturating_sub(1);
        self.auxiliary_story_debug_lines
            .push(AuxiliaryStoryLineDebug {
                story: "ruby",
                page,
                line: LayoutLineDebug {
                    paragraph,
                    line: line_index,
                    page,
                    column_index: line.column_index,
                    vertical: line.vertical,
                    start: 0,
                    end: text.len(),
                    top: line.content_top,
                    absolute_top: line.absolute_content_top,
                    height: line.content_height,
                    baseline,
                    absolute_baseline: baseline + line.absolute_top - line.top,
                    report_x_offset: 0.0,
                    start_x,
                    end_x,
                    cursor_end_x: end_x,
                    visual_end_x: end_x,
                    allowed_trailing_overflow_width: 0.0,
                    fragments: vec![LayoutFragmentDebug {
                        start: 0,
                        end: text.len(),
                        x: start_x,
                        width: end_x - start_x,
                        baseline,
                        glyphs: debug_glyphs,
                    }],
                    text,
                    tab_leaders: Vec::new(),
                    tab_stops: Vec::new(),
                },
            });
    }

    /// Draws `w:u` (ECMA-376 Part 1 §17.3.2.40) in the current text colour.
    ///
    /// The rule sits 0.15em below the baseline — close enough to clear most
    /// descenders without detaching from the text. Weight matches
    /// [`Self::draw_strike_through`] so the two decorations look like one family.
    /// Callers that need an explicit colour (plugin overlays) use
    /// [`Self::draw_colored_underline`] instead.
    #[allow(clippy::too_many_arguments)]
    fn draw_underline<P: Painter>(
        &self,
        context: &P,
        start_x: f64,
        baseline_y: f64,
        width: f64,
        font_size_pt: f32,
        kind: Option<&str>,
        color: Option<&str>,
    ) -> Result<(), P::Error> {
        if width <= 0.0 {
            return Ok(());
        }
        if !self.should_draw_current_page_for_render() {
            return Ok(());
        }

        context.save();
        match color {
            Some(color) => context.set_stroke_style_str(color),
            // Decorations take the colour of the text they belong to, which
            // the caller has already set as the fill style.
            None => context.use_fill_style_for_stroke(),
        }
        crate::draw_command::executor::stroke_underline_with_kind(
            context,
            start_x,
            baseline_y,
            width,
            font_size_pt,
            kind,
        )?;
        context.restore();

        Ok(())
    }

    /// Underline variant used by plugin decorations: takes an explicit CSS
    /// color string instead of inheriting the current `fillStyle`, so
    /// overlays (e.g. red `◯` underline) do not require changing the fill
    /// state used for text rendering.
    fn draw_colored_underline<P: Painter>(
        &self,
        context: &P,
        start_x: f64,
        baseline_y: f64,
        width: f64,
        font_size_pt: f32,
        color: &str,
    ) -> Result<(), P::Error> {
        if width <= 0.0 {
            return Ok(());
        }
        if !self.should_draw_current_page_for_render() {
            return Ok(());
        }

        let font_px = points_to_px(font_size_pt);
        let underline_y = baseline_y + font_px * 0.15;

        context.save();
        context.set_stroke_style_str(color);
        context.set_line_width((font_px * 0.05).max(1.0));
        context.begin_path();
        context.move_to(start_x, underline_y);
        context.line_to(start_x + width, underline_y);
        context.stroke();
        context.restore();

        Ok(())
    }

    /// Draws a character border (`w:bdr`, ECMA-376 Part 1 §17.3.2.4) as a box
    /// of four thin filled rectangles inside the shared outer box `(x, y, w, h)`.
    /// The immediate fill is gated on the page-draw flag, while the
    /// `DrawCommand::FillRect` entries are always emitted so the cache-replay
    /// path reproduces identical geometry. Layout already includes border width
    /// and `w:space`; painting must not expand that box again. MVP: a solid
    /// stroke (double/dashed line styles remain follow-ups).
    fn draw_character_border<P: Painter>(
        &self,
        context: &P,
        edge: &ResolvedBorderEdge,
        rect: (f64, f64, f64, f64),
        mut commands_out: Option<&mut Vec<DrawCommand>>,
    ) {
        let (x, y, w, h) = rect;
        if w <= 0.0 || h <= 0.0 {
            return;
        }
        let rects = character_border_side_rects(x, y, w, h, edge.width_px);
        let draw = self.should_draw_current_page_for_render();
        if draw {
            context.save();
            context.set_fill_style_str(&edge.color);
        }
        for (rx, ry, rw, rh) in rects {
            if draw {
                context.fill_rect(rx, ry, rw, rh);
            }
            if let Some(buf) = commands_out.as_deref_mut() {
                buf.push(DrawCommand::FillRect {
                    x: rx,
                    y: ry,
                    width: rw,
                    height: rh,
                    color: Rc::clone(&edge.color),
                });
            }
        }
        if draw {
            context.restore();
            self.reset_fill_style_state();
        }
    }

    /// Squiggly-underline variant used by plugin decorations (lint-style
    /// wavy underline). Delegates to the shared executor helper so the
    /// direct-draw path and the cache-replay path produce identical
    /// geometry.
    fn draw_colored_squiggly<P: Painter>(
        &self,
        context: &P,
        start_x: f64,
        baseline_y: f64,
        width: f64,
        font_size_pt: f32,
        color: &str,
    ) -> Result<(), P::Error> {
        if width <= 0.0 {
            return Ok(());
        }
        if !self.should_draw_current_page_for_render() {
            return Ok(());
        }
        crate::draw_command::executor::execute_squiggly_underline(
            context,
            start_x,
            baseline_y,
            width,
            font_size_pt,
            color,
        )
    }

    fn draw_control_mark<P>(
        &self,
        context: &P,
        symbol: &str,
        x: f64,
        baseline_y: f64,
        style: &AppliedRunStyle,
    ) -> Result<f64, JsValue>
    where
        P: Painter,
        P::Error: PainterError,
    {
        if symbol.is_empty() {
            return Ok(0.0);
        }
        // An undrawn line still needs the mark's width for its line end. The
        // width depends only on `style`, so skip the painter state the mark
        // would borrow: the save, colour, font and restore, and the tracker
        // invalidation they force on the next run.
        if !self.should_draw_current_page_for_render() {
            return self.text_width_with_spacing(
                symbol,
                style.letter_spacing_px * CONTROL_MARK_FONT_SCALE,
                style,
            );
        }

        context.save();
        context.set_fill_style_str(CONTROL_MARK_COLOR);

        let scaled_font_size_pt =
            (style.font_size_pt as f64 * CONTROL_MARK_FONT_SCALE).max(1.0) as f32;
        let scaled_letter_spacing = style.letter_spacing_px * CONTROL_MARK_FONT_SCALE;
        let scaled_baseline_shift = style.baseline_shift_px * CONTROL_MARK_FONT_SCALE;
        let font_descriptor =
            style.descriptor_with_size(ScriptCategory::Latin, scaled_font_size_pt);
        context.set_font(&font_descriptor);

        let reduction_points = style.font_size_pt * ((1.0 - CONTROL_MARK_FONT_SCALE) * 0.5) as f32;
        let baseline_lift = points_to_px(reduction_points);
        let text_y = baseline_y + scaled_baseline_shift - baseline_lift;
        let (width, _) = self.draw_text_with_spacing(
            context,
            symbol,
            x,
            text_y,
            scaled_letter_spacing,
            style,
            None,
            None,
            None,
            None,
            None,
        )?;
        context.restore();
        // Font fallback inside `draw_text_with_spacing` goes through the
        // tracker, and the restore just undid it.
        self.invalidate_context_state_tracking();
        Ok(width)
    }

    fn advance_page_offset(&mut self, previous_page_height: f64) {
        if self.pageless_mode {
            return;
        }

        self.page_offset_y += previous_page_height + PAGE_GAP_PX;
    }

    /// Materializes the backing for `next_page` (1-based) at the start of a page
    /// advance, then clears it and draws its crop marks.
    ///
    /// The expensive part is `host.start_new_page`, which activates a canvas
    /// (context switch + rebuild bookkeeping). For an incremental edit deep in a
    /// large document the render walk crosses every prefix page, but pages
    /// entirely before the dirty/visible window are neither drawn nor resized —
    /// their canvases need no touching at all. When `next_page` will not be drawn
    /// this pass (`should_draw_page_for_current_render` is false), we advance the
    /// host's page cursor via `advance_page_without_touch`, which keeps the page
    /// bookkeeping consistent without activating the canvas. The host returns
    /// `false` if the page slot is unallocated or its logical size changed. For
    /// a new out-of-window slot, `advance_page_with_placeholder` allocates only
    /// the canvas and bookkeeping; otherwise pages that must be materialized or
    /// resized fall back to the full `start_new_page` path.
    ///
    /// `clear_current_page_for_render` and `draw_content_crop_marks_for_page` are
    /// themselves gated by `should_draw_page_for_current_render`, so they are
    /// no-ops on a skipped page; keeping the calls preserves identical behavior
    /// for pages that *are* drawn.
    /// Restores the band-redraw clip (if this pass set one) on the CURRENT
    /// context. Must be called before the render walk switches to a different
    /// page's canvas context (page advance), because the clip lives on the caret
    /// page's context and a later page has a freshly-built, unclipped context —
    /// restoring then would unbalance the wrong stack. Idempotent.
    fn restore_band_clip_if_active(&mut self) {
        if self.band_redraw_clip_active {
            self.host.painter().restore();
            self.invalidate_context_state_tracking();
            self.band_redraw_clip_active = false;
        }
    }

    /// The only way the renderer may move the host to another page's drawing
    /// context (start, advance, jump, activate, or begin a render).
    ///
    /// Page contexts are retained across renders, so any state a pass leaves
    /// on the context it is leaving outlives the pass. The band-redraw clip
    /// is such state: a page switch that skipped the release left the caret
    /// page clipped to the band, and every later repaint of that page only
    /// reached the old band rows. Routing every switch through here makes the
    /// release impossible to forget; the
    /// `host_page_switches_go_through_switch_host_page` test rejects direct
    /// calls.
    fn switch_host_page<R>(
        &mut self,
        switch: impl FnOnce(&mut crate::render_host::BoxedRenderHost<HostPainter>) -> R,
    ) -> R {
        self.restore_band_clip_if_active();
        switch(&mut self.host)
    }

    fn begin_next_page_backing(&mut self, next_page: usize) -> Result<(), JsValue> {
        self.apply_mirrored_margins_for_page(next_page);
        self.current_page_started_this_pass = true;
        if self.drawing_uncached_paragraph {
            // The walk is painting a paragraph that continues onto `next_page`,
            // so its remaining lines are drawn there. Make the page dirty as it
            // starts: a later cache-miss promotion would come after those lines
            // were already gated away, leaving the page's top blank.
            self.mark_page_dirty_for_current_render(next_page);
        }
        let can_skip_canvas = !self.should_draw_page_for_current_render(next_page);
        let (page_width, page_height, margin_top) =
            (self.page_width, self.page_height, self.margin_top);
        let skipped_existing = can_skip_canvas
            && self
                .switch_host_page(|host| host.advance_page_without_touch(page_width, page_height));
        let skipped_placeholder = can_skip_canvas
            && !skipped_existing
            && self.switch_host_page(|host| {
                host.advance_page_with_placeholder(page_width, page_height)
            })?;
        if !skipped_existing && !skipped_placeholder {
            self.switch_host_page(|host| host.start_new_page(page_width, page_height, margin_top))?;
            self.invalidate_context_state_tracking();
            self.clear_current_page_for_render(next_page)?;
            self.draw_content_crop_marks_for_page(next_page);
        }
        Ok(())
    }

    fn apply_mirrored_margins_for_page(&mut self, page_number: usize) {
        if !self.mirror_margins || self.pageless_mode {
            return;
        }
        let previous_left = self.margin_left;
        let margins = resolve_page_margins(
            self.odd_page_margin_left_pt,
            self.odd_page_margin_right_pt,
            0.0,
            0.0,
            false,
            true,
            page_number,
        );
        self.margin_left = points_to_px(margins.left);
        self.margin_right = points_to_px(margins.right);
        let delta = self.margin_left - previous_left;
        if delta.abs() > f64::EPSILON {
            for offset in &mut self.column_layout.offsets {
                *offset += delta;
            }
        }
    }

