    /// Opt-in diagnostics for rich header/footer layout in the next render.
    /// Ordinary editing never retains these potentially repeated page lines.
    pub fn set_auxiliary_story_capture_enabled(&mut self, enabled: bool) {
        self.auxiliary_story_capture_mode = if enabled {
            AuxiliaryStoryCaptureMode::Auxiliary
        } else {
            AuxiliaryStoryCaptureMode::Disabled
        };
        self.auxiliary_story_debug_lines.clear();
    }

    pub fn auxiliary_story_debug_lines(&self) -> &[AuxiliaryStoryLineDebug] {
        &self.auxiliary_story_debug_lines
    }

    fn text_box_source_inventory_complete(&self) -> bool {
        let Some(document) = self.last_document.as_ref() else {
            return false;
        };
        if document
            .body
            .as_ref()
            .is_some_and(|body| blocks_contain_nested_text_box(&body.elements))
            || document
                .footnotes
                .values()
                .chain(document.endnotes.values())
                .any(|note| blocks_contain_text_box(&note.body))
        {
            return false;
        }
        let rich_bodies = [
            self.header_body.as_ref(),
            self.footer_body.as_ref(),
            self.header_body_first.as_ref(),
            self.footer_body_first.as_ref(),
            self.header_body_even.as_ref(),
            self.footer_body_even.as_ref(),
        ];
        !rich_bodies
            .into_iter()
            .flatten()
            .any(|body| blocks_contain_text_box(&body.elements))
            && !self.section_header_footers.iter().any(|section| {
                [
                    section.header_body.as_ref(),
                    section.footer_body.as_ref(),
                    section.header_body_first.as_ref(),
                    section.footer_body_first.as_ref(),
                    section.header_body_even.as_ref(),
                    section.footer_body_even.as_ref(),
                ]
                .into_iter()
                .flatten()
                .any(|body| blocks_contain_text_box(&body.elements))
            })
    }

    fn known_uncaptured_stories(
        &self,
        page_count: usize,
        auxiliary_lines: &[AuxiliaryStoryLineDebug],
    ) -> Vec<&'static str> {
        let mut gaps = Vec::new();
        if let Some(document) = self.last_document.as_ref() {
            if document.footnotes.iter().any(|(id, note)| {
                if matches!(
                    note.note_type.as_deref(),
                    Some("separator" | "continuationSeparator" | "continuationNotice")
                ) {
                    return false;
                }
                let Some(base) = self.footnote_surface_bases.get(id) else {
                    return true;
                };
                let count = Self::body_element_paragraph_surface_count(&note.body);
                count == 0
                    || (0..count).any(|offset| {
                        !auxiliary_lines.iter().any(|entry| {
                            entry.story == "footnote" && entry.line.paragraph == base + offset
                        })
                    })
            }) {
                gaps.push("footnotes");
            }
            if document.endnotes.iter().any(|(id, note)| {
                if matches!(
                    note.note_type.as_deref(),
                    Some("separator" | "continuationSeparator" | "continuationNotice")
                ) {
                    return false;
                }
                let Some(position) = self
                    .endnote_order
                    .iter()
                    .position(|ordered_id| ordered_id == id)
                else {
                    return true;
                };
                let base = Self::body_paragraph_surface_count(document)
                    + document
                        .footnotes
                        .values()
                        .map(|note| Self::body_element_paragraph_surface_count(&note.body))
                        .sum::<usize>()
                    + self.endnote_order[..position]
                        .iter()
                        .filter_map(|ordered_id| document.endnotes.get(ordered_id))
                        .map(|note| Self::body_element_paragraph_surface_count(&note.body).max(1))
                        .sum::<usize>();
                let count = Self::body_element_paragraph_surface_count(&note.body).max(1);
                (0..count).any(|offset| {
                    !auxiliary_lines.iter().any(|entry| {
                        entry.story == "endnote" && entry.line.paragraph == base + offset
                    })
                })
            }) {
                gaps.push("endnotes");
            }
            let rich_bodies = [
                self.header_body.as_ref(),
                self.footer_body.as_ref(),
                self.header_body_first.as_ref(),
                self.footer_body_first.as_ref(),
                self.header_body_even.as_ref(),
                self.footer_body_even.as_ref(),
            ];
            if document
                .body
                .as_ref()
                .is_some_and(|body| blocks_contain_text_box(&body.elements))
                || rich_bodies
                    .into_iter()
                    .flatten()
                    .any(|body| blocks_contain_text_box(&body.elements))
                || self.section_header_footers.iter().any(|section| {
                    [
                        section.header_body.as_ref(),
                        section.footer_body.as_ref(),
                        section.header_body_first.as_ref(),
                        section.footer_body_first.as_ref(),
                        section.header_body_even.as_ref(),
                        section.footer_body_even.as_ref(),
                    ]
                    .into_iter()
                    .flatten()
                    .any(|body| blocks_contain_text_box(&body.elements))
                })
                || document
                    .footnotes
                    .values()
                    .chain(document.endnotes.values())
                    .filter(|note| {
                        !matches!(
                            note.note_type.as_deref(),
                            Some("separator" | "continuationSeparator" | "continuationNotice")
                        )
                    })
                    .any(|note| blocks_contain_text_box(&note.body))
            {
                gaps.push("text_boxes");
            }
        }
        if (1..=page_count).any(|page| {
            [HeaderFooterRole::Header, HeaderFooterRole::Footer]
                .into_iter()
                .any(|role| {
                    let lines = if self.section_header_footers.is_empty() {
                        match role {
                            HeaderFooterRole::Header => select_header_footer_variant_for_page(
                                page,
                                self.is_first_page_of_section(page),
                                self.title_page,
                                self.even_and_odd_headers,
                                self.header_lines.as_deref(),
                                self.header_lines_first.as_deref(),
                                self.header_lines_even.as_deref(),
                            ),
                            HeaderFooterRole::Footer => select_header_footer_variant_for_page(
                                page,
                                self.is_first_page_of_section(page),
                                self.title_page,
                                self.even_and_odd_headers,
                                self.footer_lines.as_deref(),
                                self.footer_lines_first.as_deref(),
                                self.footer_lines_even.as_deref(),
                            ),
                        }
                    } else {
                        self.section_hf_lines_for_page(page, role)
                    };
                    let body = if self.section_header_footers.is_empty() {
                        match role {
                            HeaderFooterRole::Header => select_header_footer_variant_for_page(
                                page,
                                self.is_first_page_of_section(page),
                                self.title_page,
                                self.even_and_odd_headers,
                                self.header_body.as_ref(),
                                self.header_body_first.as_ref(),
                                self.header_body_even.as_ref(),
                            ),
                            HeaderFooterRole::Footer => select_header_footer_variant_for_page(
                                page,
                                self.is_first_page_of_section(page),
                                self.title_page,
                                self.even_and_odd_headers,
                                self.footer_body.as_ref(),
                                self.footer_body_first.as_ref(),
                                self.footer_body_even.as_ref(),
                            ),
                        }
                    } else {
                        self.section_hf_body_for_page(page, role)
                    };
                    body.is_none() && lines.is_some_and(|lines| !lines.is_empty())
                })
        }) {
            gaps.push("legacy_header_footer");
        }
        gaps
    }

    /// Rebuilds diagnostics from page one with no lazy limit or seek replay.
    /// This is deliberately expensive and should only run for release captures.
    pub fn capture_full_layout_debug(&mut self) -> Result<FullLayoutDebugSnapshot, JsValue> {
        if self.last_document.is_none() {
            return Err(JsValue::from_str("Document not loaded"));
        }
        let saved_limit = self.layout_page_limit;
        let saved_visible = self.visible_page_range.clone();
        let saved_capture = self.auxiliary_story_capture_mode;
        let saved_force_full_repaint = self.force_full_repaint_once;
        let saved_disable_seek_replay = self.disable_seek_replay_once;
        let saved_hf_story_layouts = std::mem::take(&mut self.hf_story_layouts);
        self.layout_page_limit = None;
        self.visible_page_range = None;
        self.auxiliary_story_capture_mode = AuxiliaryStoryCaptureMode::Full;
        self.force_full_repaint_once = true;
        self.disable_seek_replay_once = true;

        let result = self.rerender_with_cached_state();
        let snapshot = result.map(|()| {
            let (source_text_stories, source_surface_indices_complete) =
                source_text_stories(self.last_document.as_ref().expect("document was loaded"));
            let mut body_lines = Vec::new();
            let mut auxiliary_lines = self.auxiliary_story_debug_lines.clone();
            let mut clipped_table_lines = HashMap::new();
            let mut painted_table_lines = HashMap::new();
            auxiliary_lines.retain(|entry| {
                if entry.story == "table_clip_projection" {
                    clipped_table_lines.insert(
                        (entry.line.paragraph, entry.line.line, entry.line.page),
                        entry.line.clone(),
                    );
                    false
                } else if entry.story == "table_paint_projection" {
                    painted_table_lines.insert(
                        (entry.line.paragraph, entry.line.line, entry.line.page),
                        entry.line.clone(),
                    );
                    false
                } else {
                    true
                }
            });
            let auxiliary_line_keys = auxiliary_lines
                .iter()
                .filter(|entry| matches!(entry.story, "text_box" | "endnote"))
                .map(|entry| (entry.line.paragraph, entry.line.line, entry.line.page))
                .collect::<HashSet<_>>();
            for mut line in self.layout_debug_lines() {
                if let Some(painted) =
                    clipped_table_lines.remove(&(line.paragraph, line.line, line.page))
                {
                    // Preserve every diagnostic field and source range; only
                    // the capture's visible-glyph projection changes.
                    for (fragment, painted) in line.fragments.iter_mut().zip(painted.fragments) {
                        let mut visible = painted.glyphs.iter().peekable();
                        fragment.glyphs.retain(|glyph| {
                            if visible.peek().is_some_and(|next| {
                                next.start == glyph.start && next.end == glyph.end
                            }) {
                                visible.next();
                                true
                            } else {
                                false
                            }
                        });
                    }
                }
                if let Some(painted) =
                    painted_table_lines.remove(&(line.paragraph, line.line, line.page))
                {
                    // Capture actual mixed-orientation paint origins without
                    // changing the logical selection line or source ranges.
                    line.fragments = painted.fragments;
                    for fragment in &mut line.fragments {
                        fragment.x += 2.0 * line.report_x_offset;
                    }
                }
                if auxiliary_line_keys.contains(&(line.paragraph, line.line, line.page)) {
                    continue;
                }
                if self
                    .footnote_surface_ranges
                    .iter()
                    .any(|(start, end)| (*start..*end).contains(&line.paragraph))
                {
                    auxiliary_lines.push(AuxiliaryStoryLineDebug {
                        story: "footnote",
                        page: line.page,
                        line,
                    });
                } else {
                    body_lines.push(line);
                }
            }
            FullLayoutDebugSnapshot {
                page_count: self.page_count(),
                complete: self.last_layout_complete(),
                body_lines,
                known_uncaptured_stories: self
                    .known_uncaptured_stories(self.page_count(), &auxiliary_lines),
                auxiliary_lines,
                text_box_regions: self.text_box_debug_regions.borrow().clone(),
                grouped_shape_text_regions: self.grouped_shape_text_regions.borrow().clone(),
                source_text_stories,
                source_surface_indices_complete,
                text_box_source_inventory_complete: self.text_box_source_inventory_complete(),
            }
        });
        self.layout_page_limit = saved_limit;
        self.visible_page_range = saved_visible;
        self.auxiliary_story_capture_mode = saved_capture;
        self.auxiliary_story_debug_lines.retain(|entry| {
            !matches!(
                entry.story,
                "table_clip_projection" | "table_paint_projection"
            )
        });
        self.force_full_repaint_once = saved_force_full_repaint;
        self.disable_seek_replay_once = saved_disable_seek_replay;
        self.hf_story_layouts = saved_hf_story_layouts;
        if !saved_capture.enabled() {
            self.auxiliary_story_debug_lines.clear();
        }
        snapshot
    }

    /// Layout lines (with glyph geometry) for `paragraphs` only, in the order
    /// given. Unknown indices are skipped. Callers that highlight a handful of
    /// search matches use this instead of serializing every glyph in the
    /// document.
    pub fn layout_debug_lines_for_paragraphs(&self, paragraphs: &[usize]) -> Vec<LayoutLineDebug> {
        self.layout_debug_lines_for(paragraphs.iter().copied())
    }

    fn layout_debug_lines_for(
        &self,
        paragraph_indices: impl IntoIterator<Item = usize>,
    ) -> Vec<LayoutLineDebug> {
        let mut lines = Vec::new();
        let paragraphs = self.selection.paragraphs();
        let page_with_gap = self.page_height + PAGE_GAP_PX;
        let report_x_offsets = self.word_oracle_report_x_offsets.borrow();

        for paragraph_index in paragraph_indices {
            let Some(paragraph) = paragraphs.get(paragraph_index) else {
                continue;
            };
            let paragraph_len = paragraph.text.len();
            for (line_index, line) in paragraph.lines.iter().enumerate() {
                let (start, end) = Self::line_text_range(line, paragraph_len);
                let text = paragraph.text.get(start..end).unwrap_or("").to_string();
                let page = if self.pageless_mode || page_with_gap <= 0.0 {
                    0
                } else {
                    let value = (line.absolute_content_top / page_with_gap).floor();
                    if value.is_finite() && value >= 0.0 {
                        value as usize
                    } else {
                        0
                    }
                };
                let report_x_offset = if self.rendering_header_footer_story {
                    0.0
                } else {
                    report_x_offsets
                        .get(&paragraph_index)
                        .copied()
                        .unwrap_or_default()
                        .for_line(line_index)
                };
                lines.push(LayoutLineDebug {
                    paragraph: paragraph_index,
                    line: line_index,
                    page,
                    column_index: line.column_index,
                    vertical: line.vertical,
                    start,
                    end,
                    text,
                    top: line.content_top,
                    absolute_top: line.absolute_content_top,
                    height: line.content_height,
                    baseline: line.baseline,
                    absolute_baseline: line.baseline + (line.absolute_top - line.top),
                    report_x_offset,
                    start_x: line.start_x + report_x_offset,
                    end_x: line.visual_end_x() + report_x_offset,
                    cursor_end_x: line.cursor_end_x + report_x_offset,
                    visual_end_x: line.visual_end_x() + report_x_offset,
                    allowed_trailing_overflow_width: line.allowed_trailing_overflow_width,
                    fragments: line
                        .fragments
                        .iter()
                        .map(|fragment| LayoutFragmentDebug {
                            start: fragment.start,
                            end: fragment.end,
                            x: fragment.x + report_x_offset,
                            width: fragment.width,
                            baseline: line.baseline + fragment.baseline_shift_px,
                            glyphs: fragment
                                .glyphs
                                .iter()
                                .map(|glyph| LayoutGlyphDebug {
                                    start: glyph.start,
                                    end: glyph.end,
                                    text: paragraph
                                        .text
                                        .get(glyph.start..glyph.end)
                                        .unwrap_or("")
                                        .to_string(),
                                    x: glyph.x + report_x_offset,
                                    width: glyph.width,
                                })
                                .collect(),
                        })
                        .collect(),
                    tab_leaders: line.tab_leaders.to_vec(),
                    tab_stops: line.tab_stops.to_vec(),
                });
            }
        }

        lines
    }

    fn line_text_range(line: &SelectionLineLayout, paragraph_len: usize) -> (usize, usize) {
        let (start, end) = line
            .logical_source_range()
            .unwrap_or((paragraph_len, paragraph_len));
        (start.min(paragraph_len), end.min(paragraph_len))
    }

