    pub fn hyperlink_regions(&self) -> &[HyperlinkRegion] {
        &self.hyperlink_regions
    }

    /// Links painted on a page, including auxiliary stories and drawings.
    /// Capture after that page's repaint, before advancing the render window.
    pub fn page_hyperlink_regions(&self, page_index: usize) -> Vec<HyperlinkRegion> {
        let origin = self.page_top_y(page_index);
        self.hyperlink_regions
            .iter()
            .filter(|region| region.page == page_index + 1)
            .map(|region| {
                let mut region = region.clone();
                region.page = page_index;
                region.y -= origin;
                region
            })
            .collect()
    }

