    /// Resolves bookmarks against shared selection geometry without moving
    /// the live caret. Read after the complete document has been laid out.
    pub fn page_bookmarks(&self, document: &WordDocument) -> Vec<PageBookmark> {
        let Some(model) = document.document.as_deref() else {
            return Vec::new();
        };
        model
            .bookmarks
            .iter()
            .filter_map(|bookmark| {
                let paragraph = document.bookmark_surface_index(bookmark.start_paragraph)?;
                let caret = self.selection.caret_metrics_at_position(TextPosition {
                    paragraph,
                    offset: bookmark.start_offset,
                })?;
                let page_index = self.page_for_y(caret.absolute_top);
                Some(PageBookmark {
                    name: bookmark.name.clone(),
                    page_index,
                    x: caret.x,
                    y: caret.absolute_top - self.page_top_y(page_index),
                })
            })
            .collect()
    }

    pub fn append_object_hyperlink_regions(&self, regions: &mut Vec<HyperlinkRegion>) {
        // Text links are regenerated from the current document below so metadata-only
        // edits cannot leave stale targets behind. DrawingML child-shape links have no
        // text range, so retain their painted geometry from the renderer instead.
        regions.extend(
            self.hyperlink_regions
                .iter()
                .filter(|region| region.start == region.end)
                .cloned(),
        );
    }

    pub fn derive_hyperlink_regions_from_document(
        &self,
        document: &WordDocument,
    ) -> Vec<HyperlinkRegion> {
        let mut paragraph_links: Vec<Vec<(usize, usize, RunHyperlink)>> = Vec::new();
        for paragraph_index in 0..document.paragraph_count() {
            let Some(paragraph) = document.paragraph(paragraph_index) else {
                paragraph_links.push(Vec::new());
                continue;
            };
            let mut offset = 0usize;
            let mut links = Vec::new();
            for run in &paragraph.runs {
                let start = offset;
                // Field result text is stored outside `run.text`: complex and
                // simple fields keep Word's displayed value in `cached_text`
                // (or a renderer-resolved value). Count the same visible text
                // used by paragraph layout, otherwise HYPERLINK field runs
                // collapse to a zero-width interaction region.
                if let Some(field) = run.field.as_ref() {
                    offset = offset.saturating_add(
                        self.resolve_run_field(field)
                            .map(|value| value.len())
                            .unwrap_or(run.text.len()),
                    );
                } else {
                    offset = offset.saturating_add(run.text.len());
                }
                let end = offset;
                if start < end {
                    if let Some(link) = run.hyperlink.as_ref() {
                        links.push((start, end, link.clone()));
                    }
                }
            }
            paragraph_links.push(links);
        }

        let mut regions = Vec::new();
        let page_with_gap = self.page_height + PAGE_GAP_PX;
        for (paragraph_index, paragraph_layout) in self.selection.paragraphs().iter().enumerate() {
            let Some(links) = paragraph_links.get(paragraph_index) else {
                continue;
            };
            if links.is_empty() {
                continue;
            }
            for line in &paragraph_layout.lines {
                let page = if self.pageless_mode || page_with_gap <= 0.0 {
                    0
                } else {
                    let value = (line.absolute_content_top / page_with_gap).floor();
                    if value.is_finite() && value >= 0.0 {
                        value as usize
                    } else {
                        0
                    }
                };
                for (link_start, link_end, link) in links {
                    for fragment in line.fragments.iter() {
                        let start = (*link_start).max(fragment.start);
                        let end = (*link_end).min(fragment.end);
                        if start >= end {
                            continue;
                        }
                        let Some(x0) = Self::fragment_x_at_offset(fragment, start) else {
                            continue;
                        };
                        let Some(x1) = Self::fragment_x_at_offset(fragment, end) else {
                            continue;
                        };
                        let width = (x1 - x0).max(0.0);
                        if width <= 0.0 {
                            continue;
                        }
                        regions.push(HyperlinkRegion {
                            page,
                            paragraph: paragraph_index,
                            start,
                            end,
                            x: x0,
                            y: line.absolute_content_top,
                            width,
                            height: line.content_height.max(1.0),
                            target: link.target.clone(),
                            target_mode: link.target_mode.clone(),
                            anchor: link.anchor.clone(),
                            tooltip: link.tooltip.clone(),
                            target_frame: link.target_frame.clone(),
                        });
                    }
                }
            }
        }
        regions
    }

    fn fragment_x_at_offset(fragment: &SelectionFragmentLayout, offset: usize) -> Option<f64> {
        if offset <= fragment.start {
            return Some(fragment.x);
        }
        if offset >= fragment.end {
            return Some(fragment.x + fragment.width);
        }
        for glyph in fragment.glyphs.iter() {
            if offset == glyph.start {
                return Some(fragment.x + glyph.x);
            }
            if offset == glyph.end {
                return Some(fragment.x + glyph.x + glyph.width);
            }
            if glyph.start < offset && offset < glyph.end {
                let span = glyph.end.saturating_sub(glyph.start);
                if span == 0 {
                    return Some(fragment.x + glyph.x);
                }
                let ratio = (offset - glyph.start) as f64 / span as f64;
                return Some(fragment.x + glyph.x + glyph.width * ratio);
            }
        }
        None
    }

    pub fn hyperlink_regions_js_value(&self) -> JsValue {
        if let Some(cached) = self.hyperlink_regions_js_cache.borrow().as_ref() {
            return cached.clone();
        }
        let value = to_value(&self.hyperlink_regions).unwrap_or(JsValue::NULL);
        *self.hyperlink_regions_js_cache.borrow_mut() = Some(value.clone());
        value
    }

