    pub fn hit_test_object(&self, x: f64, y: f64) -> Option<ObjectDebugInfo> {
        self.object_debug_regions
            .borrow()
            .iter()
            .rev()
            .find(|region| {
                let page_offset_y =
                    region.page.saturating_sub(1) as f64 * (self.page_height + PAGE_GAP_PX);
                let global_y = region.y + page_offset_y;
                let center_x = region.x + region.width / 2.0;
                let center_y = global_y + region.height / 2.0;
                let dx = x - center_x;
                let dy = y - center_y;
                let radians = (-region.rotation_deg).to_radians();
                let local_x = dx * radians.cos() - dy * radians.sin();
                let local_y = dx * radians.sin() + dy * radians.cos();
                local_x.abs() <= region.width / 2.0 && local_y.abs() <= region.height / 2.0
            })
            .cloned()
    }

    pub fn object_region(&self, target: FloatingObjectTarget) -> Option<ObjectDebugInfo> {
        self.object_debug_regions
            .borrow()
            .iter()
            .find(|region| {
                region.kind == target.kind
                    && region.paragraph_index == target.paragraph_index
                    && region.run_index == target.run_index
            })
            .cloned()
    }

    pub fn mark_object_target_page_dirty(&self, target: FloatingObjectTarget) {
        if let Some(region) = self.object_region(target) {
            let page = region.page.saturating_sub(1);
            use jade_docx_layout::layout_cache::DirtyRect;
            self.mark_dirty_rect(DirtyRect::full_page_at(
                self.page_width,
                self.page_height,
                page,
                self.page_top_y(page),
            ));
        } else {
            self.mark_paragraph_dirty(target.paragraph_index);
        }
    }

