    /// Updates the cached `Options` with the latest `render_changes` value so
    /// that subsequent re-renders reuse the toggled state without requiring a
    /// full document reload.
    pub fn set_render_changes_flag(&mut self, value: bool) {
        if let Some(options) = self.last_options.as_mut() {
            options.render_changes = value;
            if value {
                options.render_original = false;
            }
        }
    }

    /// Selects All Markup, No Markup, or Original without mutating revisions.
    pub fn set_revision_display_flags(&mut self, render_changes: bool, render_original: bool) {
        if let Some(options) = self.last_options.as_mut() {
            options.render_changes = render_changes;
            options.render_original = render_original;
        }
    }

    /// Updates non-printing control-mark visibility for the next cached-state
    /// re-render without changing document or history state.
    pub fn set_formatting_marks_flag(&mut self, value: bool) {
        if let Some(options) = self.last_options.as_mut() {
            options.show_formatting_marks = value;
        }
    }

    /// Updates editor-only page chrome in the cached render options. Pixel
    /// export toggles these flags immediately before a forced page repaint.
    pub fn set_page_export_render_options(
        &mut self,
        show_formatting_marks: bool,
        show_crop_marks: bool,
    ) {
        if let Some(options) = self.last_options.as_mut() {
            if options.show_formatting_marks != show_formatting_marks
                || options.show_crop_marks != show_crop_marks
            {
                self.last_layout_complete = false;
            }
            options.show_formatting_marks = show_formatting_marks;
            options.show_crop_marks = show_crop_marks;
        }
    }

    /// Changes the host's raster density, keeping layout in CSS pixels, and
    /// returns the previous one. Everything is repainted on the next render.
    pub fn set_raster_scale(&mut self, scale: f64) -> Result<f64, JsValue> {
        let previous = self.host.device_pixel_ratio();
        if previous != scale {
            self.restore_band_clip_if_active();
            self.host.set_device_pixel_ratio(scale)?;
            self.invalidate_context_state_tracking();
            // Layout cache entries also retain draw commands with clips snapped
            // at the previous density. Wrap results remain valid in CSS units.
            self.clear_paragraph_layout_cache();
            self.clear_paragraph_render_cache();
            self.last_layout_complete = false;
            self.mark_full_repaint();
        }
        Ok(previous)
    }

    pub fn set_spelling_export_mode(&mut self, enabled: bool) {
        if self.spelling_export_mode != enabled {
            self.spelling_export_mode = enabled;
            // Draw commands can contain waves from an earlier editor pass.
            self.clear_paragraph_render_cache();
            self.mark_full_repaint();
        }
    }

