    fn band_test_paragraph(runs: Vec<Run>) -> Paragraph {
        Paragraph {
            runs,
            properties: None,
            node_id: None,
            comment_ranges: Vec::new(),
            comment_markers: Vec::new(),
        }
    }

    fn band_plain_run() -> Run {
        Run {
            text: "x".to_string(),
            properties: None,
            image: None,
            text_box: None,
            math: None,
            field: None,
            hyperlink: None,
            node_id: None,
            text_node_id: None,
            revision_node_id: None,
            comment_reference_ids: Vec::new(),
            footnote_reference_ids: Vec::new(),
            endnote_reference_ids: Vec::new(),
            note_separator: None,
            has_footnote_ref: false,
            has_endnote_ref: false,
            revision: None,
        }
    }

    fn band_table_with_cell_paragraphs(count: usize) -> BodyElement {
        let cell = jade_docx_reader::document::TableCell {
            blocks: (0..count)
                .map(|_| {
                    BodyElement::Paragraph(Box::new(band_test_paragraph(vec![band_plain_run()])))
                })
                .collect(),
            ..Default::default()
        };
        let row = jade_docx_reader::document::TableRow {
            cells: vec![cell],
            ..Default::default()
        };
        BodyElement::Table(Box::new(jade_docx_reader::document::Table {
            rows: vec![row],
            ..Default::default()
        }))
    }

    #[test]
    fn top_level_paragraph_at_index_skips_over_table_cell_paragraphs() {
        // Layout: P0, Table(2 cell paragraphs = indices 1,2), P3.
        let elements = vec![
            BodyElement::Paragraph(Box::new(band_test_paragraph(vec![band_plain_run()]))),
            band_table_with_cell_paragraphs(2),
            BodyElement::Paragraph(Box::new(band_test_paragraph(vec![band_plain_run()]))),
        ];
        // Index 0 → the first top-level paragraph.
        assert!(top_level_paragraph_at_index(&elements, 0).is_some());
        // Indices 1 and 2 fall inside the table cell → not top-level.
        assert!(top_level_paragraph_at_index(&elements, 1).is_none());
        assert!(top_level_paragraph_at_index(&elements, 2).is_none());
        // Index 3 → the second top-level paragraph (after the two cell paragraphs).
        assert!(top_level_paragraph_at_index(&elements, 3).is_some());
        // Out of range.
        assert!(top_level_paragraph_at_index(&elements, 4).is_none());
    }

    #[test]
    fn paragraph_has_floating_or_math_detects_objects() {
        // Plain text paragraph → no floating/math.
        assert!(!paragraph_has_floating_or_math(&band_test_paragraph(vec![
            band_plain_run()
        ])));

        let mut image_run = band_plain_run();
        image_run.image = Some(jade_docx_reader::document::RunImage::default());
        assert!(paragraph_has_floating_or_math(&band_test_paragraph(vec![
            image_run
        ])));

        let mut math_run = band_plain_run();
        math_run.math = Some(jade_docx_reader::document::MathRun::default());
        assert!(paragraph_has_floating_or_math(&band_test_paragraph(vec![
            math_run
        ])));
    }

    #[test]
    fn horizontal_float_wrap_detection_gates_seek_replay() {
        let mut plain = band_plain_run();
        plain.image = Some(jade_docx_reader::document::RunImage {
            layout: RunImageLayout {
                kind: RunImageKind::Floating,
                wrap: WrapMode::Square,
                ..RunImageLayout::default()
            },
            ..Default::default()
        });
        let drawing_document = Document {
            body: Some(Body {
                elements: vec![BodyElement::from_paragraph(band_test_paragraph(vec![
                    plain,
                ]))],
            }),
            ..Document::default()
        };
        assert!(document_has_horizontal_float_wrap(&drawing_document));

        let mut floating_table = jade_docx_reader::document::Table::default();
        floating_table
            .style
            .insert("table-position".into(), "floating".into());
        let table_document = Document {
            body: Some(Body {
                elements: vec![BodyElement::Table(Box::new(floating_table))],
            }),
            ..Document::default()
        };
        assert!(document_has_horizontal_float_wrap(&table_document));
        assert!(!document_has_horizontal_float_wrap(
            &doc_with_paragraph_texts(&["plain"])
        ));
    }

    #[test]
    fn cached_command_replay_filters_selection_highlights_for_js_overlay() {
        let commands = vec![
            DrawCommand::FillRect {
                x: 0.0,
                y: 0.0,
                width: 10.0,
                height: 10.0,
                color: Rc::from("#fff"),
            },
            DrawCommand::SelectionHighlight {
                x: 1.0,
                y: 1.0,
                width: 8.0,
                height: 8.0,
            },
            DrawCommand::Text {
                text: Rc::from("abc"),
                x: 2.0,
                y: 3.0,
                style: CmdTextStyle::default(),
            },
        ];

        let filtered = <CanvasRenderer>::cached_commands_for_replay(&commands, true);
        assert_eq!(filtered.len(), 2);
        assert!(!filtered
            .iter()
            .any(|command| matches!(command, DrawCommand::SelectionHighlight { .. })));

        let unfiltered = <CanvasRenderer>::cached_commands_for_replay(&commands, false);
        assert_eq!(unfiltered.len(), commands.len());
    }

    #[test]
    fn keep_lines_requires_page_advance_only_when_paragraph_fits_a_fresh_page() {
        // Fits in the remaining space → no advance needed.
        assert!(!keep_lines_requires_page_advance(100.0, 300.0, 800.0));

        // Does not fit now but fits on a fresh page → advance.
        assert!(keep_lines_requires_page_advance(300.0, 100.0, 800.0));

        // Exactly fills a full page → still honored.
        assert!(keep_lines_requires_page_advance(800.0, 100.0, 800.0));

        // Taller than a full page → cannot be honored, allow normal flow/split.
        assert!(!keep_lines_requires_page_advance(900.0, 100.0, 800.0));
    }

    #[test]
    fn border_edge_width_px_converts_eighths_of_a_point() {
        // 8 eighths = 1pt = 96/72 px ≈ 1.333.
        assert!((border_edge_width_px(Some(8)) - 96.0 / 72.0).abs() < 1e-9);
        // 24 eighths = 3pt = 4px.
        assert!((border_edge_width_px(Some(24)) - 4.0).abs() < 1e-9);
    }

    #[test]
    fn border_edge_width_px_floors_at_one_pixel() {
        // 2 eighths = 0.25pt ≈ 0.333px → clamped up to 1px.
        assert_eq!(border_edge_width_px(Some(2)), 1.0);
        // Absent w:sz assumes 0.5pt ≈ 0.667px → clamped to 1px.
        assert_eq!(border_edge_width_px(None), 1.0);
    }

    #[test]
    fn resolve_line_numbering_applies_word_defaults() {
        use jade_docx_reader::document::LineNumbering;
        // Absent attributes fall back to countBy=1, start=1, restart=newPage,
        // and the default 18pt distance.
        let resolved = resolve_line_numbering(&LineNumbering::default());
        assert_eq!(resolved.count_by, 1);
        assert_eq!(resolved.start, 1);
        assert_eq!(resolved.restart, LineNumberRestart::NewPage);
        assert!(
            (resolved.distance_px - points_to_px(LINE_NUMBER_DEFAULT_DISTANCE_PT)).abs() < 1e-9
        );

        // Explicit values are honoured; restart is matched case-insensitively
        // and `w:distance` is interpreted as twips.
        let resolved = resolve_line_numbering(&LineNumbering {
            count_by: Some(5),
            start: Some(3),
            restart: Some("continuous".to_string()),
            distance: Some(360),
        });
        assert_eq!(resolved.count_by, 5);
        assert_eq!(resolved.start, 4);
        assert_eq!(resolved.restart, LineNumberRestart::Continuous);
        // 360 twips = 18pt.
        assert!((resolved.distance_px - points_to_px(18.0)).abs() < 1e-9);

        // countBy is clamped to at least 1 to avoid a divide-by-zero cadence.
        let resolved = resolve_line_numbering(&LineNumbering {
            count_by: Some(0),
            ..Default::default()
        });
        assert_eq!(resolved.count_by, 1);
        let bounds = resolve_line_numbering(&LineNumbering {
            start: Some(u32::MAX),
            count_by: Some(u32::MAX),
            ..Default::default()
        });
        assert_eq!(bounds.start, 32768);
        assert_eq!(bounds.count_by, 100);
    }

