    #[test]
    fn margin_line_number_uses_default_style_and_captures_painted_geometry() {
        let (mut renderer, painter) = recording_renderer();
        let styles = StylesPart::from_xml(
            r#"<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
              <w:docDefaults><w:rPrDefault><w:rPr><w:sz w:val="20"/></w:rPr></w:rPrDefault></w:docDefaults>
              <w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:rPr><w:sz w:val="24"/></w:rPr></w:style>
              <w:style w:type="character" w:styleId="opaque"><w:name w:val="Line Number"/><w:rPr><w:color w:val="112233"/></w:rPr></w:style>
            </w:styles>"#,
        ).unwrap();
        renderer.set_style_context(Some(Rc::new(styles)), None);
        renderer.auxiliary_story_capture_mode = AuxiliaryStoryCaptureMode::Auxiliary;
        renderer
            .draw_line_number(10, 100.0, 24.0, &mut None, 0, renderer.margin_left)
            .unwrap();
        let captured = renderer.auxiliary_story_debug_lines();
        assert_eq!(captured.len(), 1);
        assert_eq!(captured[0].story, "line_number");
        let line = &captured[0].line;
        assert_eq!(line.text, "10");
        assert_eq!(line.baseline, 100.0);
        assert!((line.end_x - (renderer.margin_left - 24.0)).abs() < 1e-9);
        assert!((line.end_x - line.start_x - 20.0).abs() < 1e-9);
        use jade_painter::recording::Op;
        assert!(
            painter.count(|op| matches!(op, Op::SetFont(font) if font.contains("12.00pt"))) > 0
        );
        assert!(
            painter.count(|op| matches!(op, Op::SetFillStyle(color) if color == "#112233")) > 0
        );
        assert!(renderer.selection.paragraphs().is_empty());
    }

    #[test]
    fn margin_line_number_style_refresh_and_column_anchor_do_not_enter_selection() {
        let (mut renderer, painter) = recording_renderer();
        renderer.auxiliary_story_capture_mode = AuxiliaryStoryCaptureMode::Auxiliary;
        for (size, column) in [(8, 200.0), (16, 400.0)] {
            let styles = StylesPart::from_xml(&format!(
                "<w:styles xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:style w:type=\"character\" w:styleId=\"LineNumber\"><w:rPr><w:sz w:val=\"{}\"/></w:rPr></w:style></w:styles>", size * 2
            )).unwrap();
            renderer.set_style_context(Some(Rc::new(styles)), None);
            renderer
                .draw_line_number(11, 100.0, 24.0, &mut None, 3, column)
                .unwrap();
            let line = &renderer.auxiliary_story_debug_lines().last().unwrap().line;
            assert_eq!(line.paragraph, 3);
            assert!((line.end_x - (column - 24.0)).abs() < 1e-9);
            assert_eq!(
                renderer
                    .line_number_run_properties
                    .as_ref()
                    .unwrap()
                    .font_size,
                Some(size as f32)
            );
        }
        use jade_painter::recording::Op;
        assert!(painter.count(|op| matches!(op, Op::SetFont(font) if font.contains("8.00pt"))) > 0);
        assert!(
            painter.count(|op| matches!(op, Op::SetFont(font) if font.contains("16.00pt"))) > 0
        );
        renderer.set_auxiliary_story_capture_enabled(false);
        renderer
            .draw_line_number(12, 120.0, 24.0, &mut None, 3, 400.0)
            .unwrap();
        assert!(renderer.auxiliary_story_debug_lines().is_empty());
        assert!(renderer.selection.paragraphs().is_empty());
    }

    #[test]
    fn line_number_to_display_honours_count_by_and_start() {
        // countBy = 1: every line is numbered from `start`.
        let every = ResolvedLineNumbering {
            count_by: 1,
            start: 1,
            restart: LineNumberRestart::NewPage,
            distance_px: 24.0,
        };
        assert_eq!(line_number_to_display(1, &every), Some(1));
        assert_eq!(line_number_to_display(2, &every), Some(2));
        assert_eq!(line_number_to_display(0, &every), None);

        // countBy = 5: only multiples of 5 are shown.
        let by_five = ResolvedLineNumbering {
            count_by: 5,
            start: 1,
            restart: LineNumberRestart::NewPage,
            distance_px: 24.0,
        };
        assert_eq!(line_number_to_display(1, &by_five), None);
        assert_eq!(line_number_to_display(4, &by_five), None);
        // 5th counted line displays value 5.
        assert_eq!(line_number_to_display(5, &by_five), Some(5));
        assert_eq!(line_number_to_display(10, &by_five), Some(10));

        // A non-default start shifts the displayed value; cadence still keys off
        // the displayed number being a multiple of countBy.
        let start_ten = ResolvedLineNumbering {
            count_by: 5,
            start: 10,
            restart: LineNumberRestart::Continuous,
            distance_px: 24.0,
        };
        // line 1 → displayed 10 (multiple of 5) → shown.
        assert_eq!(line_number_to_display(1, &start_ten), Some(10));
        // line 2 → displayed 11 → hidden.
        assert_eq!(line_number_to_display(2, &start_ten), None);
        // line 6 → displayed 15 → shown.
        assert_eq!(line_number_to_display(6, &start_ten), Some(15));
    }

    #[test]
    fn resolve_paragraph_borders_drops_nil_edges_and_defaults_color() {
        use jade_docx_reader::document::{BorderEdge, ParagraphBorders};
        let borders = ParagraphBorders {
            top: Some(BorderEdge {
                val: Some("single".to_string()),
                size_eighths: Some(24),
                space: Some(1),
                color: None,
            }),
            bottom: Some(BorderEdge {
                val: Some("nil".to_string()),
                ..Default::default()
            }),
            left: Some(BorderEdge {
                val: Some("double".to_string()),
                size_eighths: Some(8),
                space: None,
                color: Some("#112233".into()),
            }),
            ..Default::default()
        };
        let resolved = resolve_paragraph_borders(&borders).expect("visible borders");
        let top = resolved.top.expect("top");
        assert_eq!(top.width_px, 4.0);
        assert_eq!(
            &*top.color, "#000000",
            "auto/absent color defaults to black"
        );
        assert_eq!(
            top.kind,
            BorderKind::Single,
            "single val resolves to Single"
        );
        assert!(resolved.bottom.is_none(), "nil edge is dropped");
        let left = resolved.left.expect("left");
        assert_eq!(&*left.color, "#112233");
        assert_eq!(
            left.kind,
            BorderKind::Double,
            "double val resolves to Double"
        );
        assert!(resolved.right.is_none());
    }

    #[test]
    fn border_band_offsets_splits_double_and_triple_into_parallel_lines() {
        // Single/unknown kinds collapse to one full-thickness band.
        assert_eq!(
            border_band_offsets(BorderKind::Single, 3.0),
            vec![(0.0, 3.0)]
        );
        assert_eq!(
            border_band_offsets(BorderKind::Dashed, 3.0),
            vec![(0.0, 3.0)]
        );

        // Double: two equal lines (1/3 each) separated by an equal gap (1/3).
        let double = border_band_offsets(BorderKind::Double, 3.0);
        assert_eq!(double, vec![(0.0, 1.0), (2.0, 1.0)]);

        // Triple: three equal lines (1/5 each) with equal gaps (1/5).
        let triple = border_band_offsets(BorderKind::Triple, 5.0);
        assert_eq!(triple, vec![(0.0, 1.0), (2.0, 1.0), (4.0, 1.0)]);

        // Non-positive thickness yields no bands (nothing to paint).
        assert!(border_band_offsets(BorderKind::Double, 0.0).is_empty());
        assert!(border_band_offsets(BorderKind::Single, -1.0).is_empty());
    }

    #[test]
    fn border_dash_segments_emits_pattern_for_dashed_kinds() {
        // Solid kinds span the full length in one run regardless of thickness.
        assert_eq!(
            border_dash_segments(BorderKind::Single, 10.0, 1.0),
            vec![(0.0, 10.0)]
        );
        assert_eq!(
            border_dash_segments(BorderKind::Double, 10.0, 1.0),
            vec![(0.0, 10.0)]
        );

        // Dashed: on=3 units, off=2 units; with thickness 1px the period is 5px.
        // length 11 -> runs at 0..3, 5..8, 10..11 (last run clipped to length).
        assert_eq!(
            border_dash_segments(BorderKind::Dashed, 11.0, 1.0),
            vec![(0.0, 3.0), (5.0, 3.0), (10.0, 1.0)]
        );

        // Dotted: on=1, off=1; period 2px -> dots at 0,2,4 within length 5.
        assert_eq!(
            border_dash_segments(BorderKind::Dotted, 5.0, 1.0),
            vec![(0.0, 1.0), (2.0, 1.0), (4.0, 1.0)]
        );

        // Thickness scales the pattern: dashed at thickness 2 -> period 10px.
        assert_eq!(
            border_dash_segments(BorderKind::Dashed, 6.0, 2.0),
            vec![(0.0, 6.0)]
        );

        // DotDash alternates a long dash then a dot.
        assert_eq!(
            border_dash_segments(BorderKind::DotDash, 7.0, 1.0),
            vec![(0.0, 4.0), (6.0, 1.0)]
        );

        // Non-positive length yields no segments.
        assert!(border_dash_segments(BorderKind::Dashed, 0.0, 1.0).is_empty());
    }

