    #[test]
    fn resolve_page_borders_resolves_edges_and_offset() {
        use jade_docx_reader::document::{BorderEdge, PageBorders};
        let borders = PageBorders {
            top: Some(BorderEdge {
                val: Some("single".to_string()),
                size_eighths: Some(24),
                space: Some(24),
                color: Some("#FF0000".into()),
            }),
            bottom: Some(BorderEdge {
                val: Some("nil".to_string()),
                ..Default::default()
            }),
            left: Some(BorderEdge {
                val: Some("double".to_string()),
                size_eighths: Some(8),
                space: None,
                color: None,
            }),
            right: None,
            offset_from: Some("page".to_string()),
        };
        let resolved = resolve_page_borders(&borders).expect("visible borders");
        assert_eq!(resolved.offset_from, PageBorderOffsetFrom::Page);
        let top = resolved.top.expect("top");
        assert_eq!(top.val.as_deref(), Some("single"));
        assert_eq!(top.size_eighths, Some(24));
        assert_eq!(top.color.as_deref(), Some("#FF0000"));
        assert!(resolved.bottom.is_none(), "nil edge dropped");
        let left = resolved.left.expect("left");
        assert_eq!(
            left.val.as_deref(),
            Some("double"),
            "double style preserved"
        );
        assert_eq!(
            left.color, None,
            "auto color stays None (defaulted at draw)"
        );
        assert!(resolved.right.is_none());
    }

