    struct LegacyParagraphWrapCache {
        entries: indexmap::IndexMap<ParagraphWrapCacheKey, LegacyParagraphWrapCacheEntry>,
        capacity: usize,
    }

    #[derive(Clone)]
    struct LegacyParagraphWrapCacheEntry {
        lines: Vec<WrappedLine>,
    }

    impl LegacyParagraphWrapCache {
        fn new(capacity: usize) -> Self {
            Self {
                entries: indexmap::IndexMap::with_capacity(capacity),
                capacity,
            }
        }

        fn get(&mut self, key: &ParagraphWrapCacheKey) -> Option<Vec<WrappedLine>> {
            if let Some(index) = self.entries.get_index_of(key) {
                self.entries.move_index(index, self.entries.len() - 1);
                self.entries.get(key).map(|entry| entry.lines.clone())
            } else {
                None
            }
        }

        fn insert(&mut self, key: ParagraphWrapCacheKey, lines: Vec<WrappedLine>) {
            if self.entries.contains_key(&key) {
                self.entries.shift_remove(&key);
            } else if self.entries.len() >= self.capacity {
                self.entries.shift_remove_index(0);
            }
            self.entries
                .insert(key, LegacyParagraphWrapCacheEntry { lines });
        }
    }

    /// Host double with no canvas at all.
    ///
    /// `context()` is `unreachable!` on purpose: it is the assertion that the
    /// renderer reaches a surface only where it genuinely must. Measurement is
    /// answered from a table instead, which is what a non-canvas host does for
    /// real — the native backend answers the same calls from shaped glyph
    /// advances rather than from a canvas.
    #[derive(Default)]
    struct TestRenderHost {
        /// Advance width per string. A string with no entry falls back to
        /// `char count * FALLBACK_ADVANCE`, so a test only lists the widths it
        /// actually reasons about.
        advances: FxHashMap<String, f64>,
        /// Descriptors passed to `set_font`, in order. Measurement is the
        /// hottest call in wrapping and the renderer is supposed to apply the
        /// font only on a real change; this makes that assertable.
        fonts_applied: Rc<RefCell<Vec<String>>>,
    }

    impl TestRenderHost {
        /// Width of a character with no explicit entry. Any value works; a
        /// round one keeps expected positions readable in assertions.
        const FALLBACK_ADVANCE: f64 = 10.0;

        fn with_advances(advances: &[(&str, f64)]) -> Self {
            Self {
                advances: advances
                    .iter()
                    .map(|(text, advance)| ((*text).to_string(), *advance))
                    .collect(),
                fonts_applied: Rc::new(RefCell::new(Vec::new())),
            }
        }

        fn advance_of(&self, text: &str) -> f64 {
            if let Some(advance) = self.advances.get(text) {
                return *advance;
            }
            text.chars()
                .map(|ch| {
                    self.advances
                        .get(&ch.to_string())
                        .copied()
                        .unwrap_or(Self::FALLBACK_ADVANCE)
                })
                .sum()
        }
    }

    impl crate::render_host::CanvasRenderHost for TestRenderHost {
        /// The tests that paint hand their own [`RecordingPainter`] to the
        /// drawing function, so the host is never asked for one. Naming the
        /// canvas painter here would be a lie — this host has no canvas — and
        /// `unreachable!` keeps that visible if a path ever does ask.
        type Painter = jade_canvas_painter::Canvas2dPainter<web_sys::CanvasRenderingContext2d>;

        fn painter(&self) -> Self::Painter {
            unreachable!("test host: painter() must not be called")
        }

        fn device_pixel_ratio(&self) -> f64 {
            1.0
        }

        fn update_device_pixel_ratio(&mut self) -> Result<bool, JsValue> {
            Ok(false)
        }

        fn reset_pages(&mut self) -> Result<(), JsValue> {
            Ok(())
        }

        fn configure_base_canvas(
            &mut self,
            _width: f64,
            _height: f64,
            _pageless: bool,
            _margin_top: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }

        fn clear(
            &mut self,
            _page_width: f64,
            _pageless: bool,
            _full_height: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }

        fn ensure_pageless_height(
            &mut self,
            _required_height: f64,
            _margin_bottom: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }

        fn start_new_page(
            &mut self,
            _width: f64,
            _height: f64,
            _margin_top: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }

        fn context(&self) -> &web_sys::CanvasRenderingContext2d {
            unreachable!("test host: context() must not be called")
        }

        fn set_font(&self, font_descriptor: &str) {
            // Recorded rather than applied: `advance_of` is font-independent,
            // which keeps a painting test from also depending on font metrics.
            self.fonts_applied
                .borrow_mut()
                .push(font_descriptor.to_string());
        }

        fn measure_text_width(&self, text: &str) -> Result<f64, JsValue> {
            Ok(self.advance_of(text))
        }

        fn measure_text_metrics(&self, text: &str) -> Result<jade_painter::TextMetrics, JsValue> {
            let width = self.advance_of(text);
            Ok(jade_painter::TextMetrics {
                width,
                font_bounding_box_ascent: 8.0,
                font_bounding_box_descent: 2.0,
                actual_bounding_box_ascent: 8.0,
                actual_bounding_box_descent: 2.0,
                actual_bounding_box_right: width,
            })
        }

        fn context_mut(&mut self) -> &mut web_sys::CanvasRenderingContext2d {
            unreachable!("test host: context_mut() must not be called")
        }

        fn device_to_css(&self, value: f64) -> f64 {
            value
        }

        fn canvas_css_size(&self) -> (f64, f64) {
            (0.0, 0.0)
        }

        fn take_paged_snapshots(&mut self) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }

        fn take_paged_snapshots_for_pages(
            &mut self,
            _pages: Option<&[usize]>,
        ) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }

        fn page_count(&self) -> usize {
            1
        }

        fn page_dimensions(&self, _page_index: usize) -> Option<(f64, f64)> {
            Some((0.0, 0.0))
        }

        fn create_page_bitmap(&self, _page_index: usize) -> Result<js_sys::Promise, JsValue> {
            Err(JsValue::from_str(
                "test host: create_page_bitmap not supported",
            ))
        }
    }

    pub(super) fn test_renderer() -> CanvasRenderer {
        CanvasRenderer::with_host(Box::new(TestRenderHost::default()), false)
            .expect("test renderer")
    }

    pub(super) fn recording_table_renderer(
        painter: jade_painter::recording::RecordingPainter,
    ) -> CanvasRenderer<jade_painter::recording::RecordingPainter> {
        CanvasRenderer::with_host(Box::new(NonCanvasHost { painter }), true)
            .expect("recording table renderer")
    }

    /// Pageless mode makes `should_draw_current_page_for_render` unconditional,
    /// so decoration geometry can be asserted without staging page state.
    fn pageless_test_renderer() -> CanvasRenderer {
        CanvasRenderer::with_host(Box::new(TestRenderHost::default()), true)
            .expect("pageless test renderer")
    }

    /// Records what a decoration paints, with `fill` already applied the way the
    /// glyph pass leaves it.
    fn decoration_painter(fill: &str) -> jade_painter::recording::RecordingPainter {
        let painter = jade_painter::recording::RecordingPainter::new();
        Painter::set_fill_style_str(&painter, fill);
        painter
    }

    /// [`renderer_measuring`] plus the log of descriptors the host was asked to
    /// apply, so a test can assert how often the font was actually set.
    fn renderer_measuring_logging_fonts(
        advances: &[(&str, f64)],
    ) -> (CanvasRenderer, Rc<RefCell<Vec<String>>>) {
        let host = TestRenderHost::with_advances(advances);
        let fonts = Rc::clone(&host.fonts_applied);
        let renderer =
            CanvasRenderer::with_host(Box::new(host), true).expect("measuring test renderer");
        (renderer, fonts)
    }

    /// Measurement no longer needs a drawing surface, so the numbers that drive
    /// pagination can be pinned without a browser.
    #[test]
    fn line_box_height_sums_the_hosts_font_bounding_box() {
        let renderer = renderer_measuring(&[]);

        let height = LineWrapContext::measure_line_box_height(&renderer, "12pt serif")
            .expect("test host measures without a canvas");

        // The host reports an 8px ascent and a 2px descent.
        assert_eq!(height, Some(10.0));
    }

    #[test]
    fn a_descriptor_is_applied_once_however_often_it_is_measured() {
        let (renderer, fonts) = renderer_measuring_logging_fonts(&[("ab", 20.0)]);

        for _ in 0..5 {
            renderer
                .measure_text_cached("ab", "12pt serif")
                .expect("infallible");
        }

        // Measuring is the hottest call during wrapping; re-applying the font
        // on every one of them is what the cache exists to avoid.
        assert_eq!(*fonts.borrow(), vec!["12pt serif".to_string()]);
    }

    #[test]
    fn switching_descriptors_reapplies_the_font() {
        let (renderer, fonts) = renderer_measuring_logging_fonts(&[]);

        // Distinct texts so every call is a cache miss and therefore actually
        // reaches the host.
        for (text, descriptor) in [
            ("a", "12pt serif"),
            ("b", "14pt serif"),
            ("c", "12pt serif"),
        ] {
            renderer
                .measure_text_cached(text, descriptor)
                .expect("infallible");
        }

        // Tracking records the last descriptor, not every one it has seen, so
        // returning to an earlier font applies it again.
        assert_eq!(
            *fonts.borrow(),
            vec![
                "12pt serif".to_string(),
                "14pt serif".to_string(),
                "12pt serif".to_string()
            ]
        );
    }

    #[test]
    fn a_cached_width_costs_no_font_application_at_all() {
        let (renderer, fonts) = renderer_measuring_logging_fonts(&[]);

        renderer
            .measure_text_cached("a", "12pt serif")
            .expect("infallible");
        renderer
            .measure_text_cached("b", "14pt serif")
            .expect("infallible");
        let before = fonts.borrow().len();

        // A hit returns without touching the surface, so it neither applies a
        // font nor disturbs the one already active — which is why the tracked
        // descriptor may lag the last descriptor asked for.
        renderer
            .measure_text_cached("a", "12pt serif")
            .expect("infallible");

        assert_eq!(fonts.borrow().len(), before);
    }

    /// A host that paints somewhere other than a canvas.
    ///
    /// This is the shape a native backend takes: it names its own painter, and
    /// the only thing it borrows from the browser is the error type. It exists
    /// to prove the renderer is no longer canvas-bound — if `CanvasRenderer`
    /// regains a hard dependency on `Canvas2dPainter`, this stops compiling.
    ///
    /// `context()` stays `unreachable!` because a non-canvas host has no canvas
    /// to hand back. Everything a first native render needs is answered here;
    /// the page and bitmap machinery is browser-side bookkeeping and is stubbed.
    struct NonCanvasHost {
        painter: jade_painter::recording::RecordingPainter,
    }

    impl crate::render_host::CanvasRenderHost for NonCanvasHost {
        type Painter = jade_painter::recording::RecordingPainter;

        fn painter(&self) -> Self::Painter {
            // Clones share one operation log, exactly as a real backend's
            // clones share one surface.
            self.painter.clone()
        }

        fn draw_image_data_uri(
            &self,
            _uri: &str,
            x: f64,
            y: f64,
            width: f64,
            height: f64,
            _crop: Option<crate::render_host::ImageCropMapping>,
        ) -> bool {
            self.painter.fill_rect(x, y, width, height);
            true
        }

        fn device_pixel_ratio(&self) -> f64 {
            1.0
        }
        fn update_device_pixel_ratio(&mut self) -> Result<bool, JsValue> {
            Ok(false)
        }
        fn reset_pages(&mut self) -> Result<(), JsValue> {
            Ok(())
        }
        fn configure_base_canvas(
            &mut self,
            _width: f64,
            _height: f64,
            _pageless: bool,
            _margin_top: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }
        fn clear(&mut self, _page_width: f64, _pageless: bool, _full: f64) -> Result<(), JsValue> {
            Ok(())
        }
        fn ensure_pageless_height(&mut self, _h: f64, _mb: f64) -> Result<(), JsValue> {
            Ok(())
        }
        fn start_new_page(&mut self, _w: f64, _h: f64, _mt: f64) -> Result<(), JsValue> {
            Ok(())
        }
        fn device_to_css(&self, value: f64) -> f64 {
            value
        }
        fn canvas_css_size(&self) -> (f64, f64) {
            (816.0, 1056.0)
        }
        fn page_count(&self) -> usize {
            1
        }
        fn page_dimensions(&self, _page_index: usize) -> Option<(f64, f64)> {
            Some((816.0, 1056.0))
        }
        fn take_paged_snapshots(&mut self) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }
        fn take_paged_snapshots_for_pages(
            &mut self,
            _pages: Option<&[usize]>,
        ) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }
        fn context(&self) -> &web_sys::CanvasRenderingContext2d {
            unreachable!("non-canvas host: context() must not be called")
        }
        fn context_mut(&mut self) -> &mut web_sys::CanvasRenderingContext2d {
            unreachable!("non-canvas host: context_mut() must not be called")
        }
        fn create_page_bitmap(&self, _page_index: usize) -> Result<js_sys::Promise, JsValue> {
            unreachable!("non-canvas host: bitmap snapshots are browser-side")
        }

        fn measure_text_width(&self, text: &str) -> Result<f64, JsValue> {
            Ok(text.chars().count() as f64 * 10.0)
        }

        fn measure_text_metrics(&self, text: &str) -> Result<jade_painter::TextMetrics, JsValue> {
            let width = text.chars().count() as f64 * 10.0;
            Ok(jade_painter::TextMetrics {
                width,
                font_bounding_box_ascent: 8.0,
                font_bounding_box_descent: 2.0,
                actual_bounding_box_ascent: 8.0,
                actual_bounding_box_descent: 2.0,
                actual_bounding_box_right: width,
            })
        }
    }

    /// [`NonCanvasHost`] with the paged host's page bookkeeping, so a test can
    /// see how many pages a render pass leaves behind.
    struct PageCountingHost {
        inner: NonCanvasHost,
        extra_pages: usize,
        cursor: usize,
    }

    impl crate::render_host::CanvasRenderHost for PageCountingHost {
        type Painter = jade_painter::recording::RecordingPainter;

        fn painter(&self) -> Self::Painter {
            self.inner.painter()
        }
        fn draw_image_data_uri(
            &self,
            uri: &str,
            x: f64,
            y: f64,
            width: f64,
            height: f64,
            crop: Option<crate::render_host::ImageCropMapping>,
        ) -> bool {
            self.inner
                .draw_image_data_uri(uri, x, y, width, height, crop)
        }
        fn device_pixel_ratio(&self) -> f64 {
            1.0
        }
        fn update_device_pixel_ratio(&mut self) -> Result<bool, JsValue> {
            Ok(false)
        }
        fn begin_render(&mut self, reuse_pages: bool) -> Result<(), JsValue> {
            if reuse_pages {
                self.cursor = 0;
                Ok(())
            } else {
                self.reset_pages()
            }
        }
        fn reset_pages(&mut self) -> Result<(), JsValue> {
            self.extra_pages = 0;
            self.cursor = 0;
            Ok(())
        }
        fn configure_base_canvas(
            &mut self,
            width: f64,
            height: f64,
            pageless: bool,
            margin_top: f64,
        ) -> Result<(), JsValue> {
            self.inner
                .configure_base_canvas(width, height, pageless, margin_top)
        }
        fn clear(&mut self, page_width: f64, pageless: bool, full: f64) -> Result<(), JsValue> {
            self.inner.clear(page_width, pageless, full)
        }
        fn ensure_pageless_height(&mut self, h: f64, mb: f64) -> Result<(), JsValue> {
            self.inner.ensure_pageless_height(h, mb)
        }
        fn start_new_page(&mut self, _w: f64, _h: f64, _mt: f64) -> Result<(), JsValue> {
            self.cursor += 1;
            self.extra_pages = self.extra_pages.max(self.cursor);
            Ok(())
        }
        fn device_to_css(&self, value: f64) -> f64 {
            value
        }
        fn canvas_css_size(&self) -> (f64, f64) {
            self.inner.canvas_css_size()
        }
        fn page_count(&self) -> usize {
            1 + self.extra_pages
        }
        fn truncate_pages(&mut self, total_pages: usize) -> Result<(), JsValue> {
            self.extra_pages = self.extra_pages.min(total_pages.saturating_sub(1));
            Ok(())
        }
        fn page_dimensions(&self, page_index: usize) -> Option<(f64, f64)> {
            self.inner.page_dimensions(page_index)
        }
        fn take_paged_snapshots(&mut self) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }
        fn take_paged_snapshots_for_pages(
            &mut self,
            _pages: Option<&[usize]>,
        ) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }
        fn context(&self) -> &web_sys::CanvasRenderingContext2d {
            unreachable!("non-canvas host: context() must not be called")
        }
        fn context_mut(&mut self) -> &mut web_sys::CanvasRenderingContext2d {
            unreachable!("non-canvas host: context_mut() must not be called")
        }
        fn create_page_bitmap(&self, _page_index: usize) -> Result<js_sys::Promise, JsValue> {
            unreachable!("non-canvas host: bitmap snapshots are browser-side")
        }
        fn measure_text_width(&self, text: &str) -> Result<f64, JsValue> {
            self.inner.measure_text_width(text)
        }
        fn measure_text_metrics(&self, text: &str) -> Result<jade_painter::TextMetrics, JsValue> {
            self.inner.measure_text_metrics(text)
        }
    }

    /// Lays a multi-page document out completely, as the renderer does after
    /// a theme, zoom or device-pixel-ratio switch, and returns the renderer,
    /// the document and its page count.
    fn fully_laid_out_multi_page_renderer() -> (
        CanvasRenderer<jade_painter::recording::RecordingPainter>,
        Rc<Document>,
        usize,
    ) {
        let texts = vec!["body paragraph"; 160];
        let document = Rc::new(doc_with_paragraph_texts(&texts));
        let mut renderer = CanvasRenderer::with_host(
            Box::new(PageCountingHost {
                inner: NonCanvasHost {
                    painter: jade_painter::recording::RecordingPainter::new(),
                },
                extra_pages: 0,
                cursor: 0,
            }),
            false,
        )
        .unwrap();
        renderer.set_layout_page_limit(None);
        renderer
            .render_with_numbering_rc(
                Rc::clone(&document),
                &Options::default(),
                None,
                None,
                None,
                None,
            )
            .unwrap();
        assert!(renderer.last_layout_complete());
        let pages = renderer.host.page_count();
        assert!(pages >= 3, "fixture must span several pages, got {pages}");
        (renderer, document, pages)
    }

    /// Re-renders `document` with paragraph 0 centred — an edit that leaves
    /// the paragraph's height unchanged — the way the non-lazy edit path does.
    fn rerender_with_centred_first_paragraph(
        renderer: &mut CanvasRenderer<jade_painter::recording::RecordingPainter>,
        document: &Document,
        arm: impl FnOnce(&mut CanvasRenderer<jade_painter::recording::RecordingPainter>, f64),
    ) {
        let mut next = document.clone();
        let BodyElement::Paragraph(paragraph) = &mut next.body.as_mut().unwrap().elements[0] else {
            unreachable!();
        };
        paragraph.properties = Some(ParagraphProperties {
            alignment: Some(Rc::from("center")),
            ..ParagraphProperties::default()
        });
        let old_height = renderer.cached_paragraph_height(0).unwrap();
        renderer.set_layout_page_limit(None);
        renderer.set_incremental_dirty_from(0);
        renderer.mark_paragraph_dirty(0);
        arm(renderer, old_height);
        renderer
            .render_with_numbering_rc(Rc::new(next), &Options::default(), None, None, None, None)
            .unwrap();
    }

    #[test]
    fn stable_edit_on_a_complete_layout_keeps_every_later_page() {
        // After a zoom or theme switch the editor lays the whole document out
        // and edits leave lazy mode. A same-height edit (centring a paragraph,
        // typing that does not wrap) is proven stable, so the body walk stops
        // after it — and the pages after it must survive that early stop.
        let (mut renderer, document, pages) = fully_laid_out_multi_page_renderer();
        rerender_with_centred_first_paragraph(&mut renderer, &document, |renderer, height| {
            renderer.arm_fast_replay_for_complete_layout_edit(0, height);
        });
        assert_eq!(renderer.host.page_count(), pages);
        assert!(renderer.last_layout_complete());
    }

    #[test]
    fn stable_edit_on_a_complete_layout_keeps_later_hyperlink_regions() {
        // The stable-edit exit stops the walk after the edited paragraph, so
        // the paragraphs after it never re-record their hyperlink regions. The
        // regions that PDF export reads for a later page must survive it, as
        // the selection tail does.
        let texts = vec!["body paragraph"; 160];
        let mut document = doc_with_paragraph_texts(&texts);
        let BodyElement::Paragraph(linked) = &mut document.body.as_mut().unwrap().elements[120]
        else {
            unreachable!();
        };
        linked.runs[0].hyperlink = Some(crate::document::RunHyperlink {
            target: Some("https://example.com/later".to_string()),
            ..crate::document::RunHyperlink::default()
        });
        let document = Rc::new(document);
        let mut renderer = CanvasRenderer::with_host(
            Box::new(PageCountingHost {
                inner: NonCanvasHost {
                    painter: jade_painter::recording::RecordingPainter::new(),
                },
                extra_pages: 0,
                cursor: 0,
            }),
            false,
        )
        .unwrap();
        renderer.set_layout_page_limit(None);
        renderer
            .render_with_numbering_rc(
                Rc::clone(&document),
                &Options::default(),
                None,
                None,
                None,
                None,
            )
            .unwrap();
        assert!(renderer.last_layout_complete());
        let page = renderer.cached_paragraph_start_page(120).unwrap() - 1;
        assert!(page > 0, "the link must sit after the edited page");
        let regions = |renderer: &CanvasRenderer<jade_painter::recording::RecordingPainter>| {
            format!("{:?}", renderer.page_hyperlink_regions(page))
        };
        assert!(!renderer.page_hyperlink_regions(page).is_empty());
        let before = regions(&renderer);

        rerender_with_centred_first_paragraph(&mut renderer, &document, |renderer, height| {
            renderer.arm_fast_replay_for_complete_layout_edit(0, height);
        });
        assert!(renderer.last_fast_replay_stable());
        assert_eq!(regions(&renderer), before);
    }

    #[test]
    fn stable_edit_repaints_the_rest_of_a_page_it_cleared() {
        // A page whose pixels went to the browser (the snapshots after a theme
        // or zoom switch) is cleared whole before it is drawn again. Stopping
        // the walk at the stable edited paragraph then left the rest of that
        // page blank.
        let (mut renderer, document, _) = fully_laid_out_multi_page_renderer();
        let on_first_page = (0..160)
            .filter(|&index| renderer.cached_paragraph_start_page(index) == Some(1))
            .count();
        assert!(on_first_page > 3);
        let painter = renderer.host.painter();
        painter.clear();
        rerender_with_centred_first_paragraph(&mut renderer, &document, |renderer, height| {
            renderer.arm_fast_replay_for_complete_layout_edit(0, height);
        });
        // Glyphs are drawn one by one; count the lines they sit on.
        let mut baselines: Vec<i64> = painter
            .ops()
            .iter()
            .filter_map(|op| match op {
                jade_painter::recording::Op::FillText(_, _, y) => Some(y.round() as i64),
                _ => None,
            })
            .collect();
        baselines.sort_unstable();
        baselines.dedup();
        assert!(
            baselines.len() >= on_first_page,
            "drew {} lines, the cleared page holds {on_first_page} paragraphs",
            baselines.len()
        );
        // ...without starting on the next page: the first paragraph that
        // overflows into it would leave that page half painted, and it would
        // be handed to the browser as if it were complete.
        let page_clears = painter
            .ops()
            .iter()
            .filter(|op| {
                matches!(op, jade_painter::recording::Op::ClearRect(x, y, ..) if *x == 0.0 && *y == 0.0)
            })
            .count();
        assert_eq!(page_clears, 1, "only the edited page is repainted");
    }

    #[test]
    fn fast_replay_page_cap_does_not_outlive_its_render() {
        // The stable branch caps the walk at the edited page to stop early.
        // That cap belongs to the one render: the non-lazy typing path leaves
        // the limit alone between keystrokes, so a cap that survived would
        // end the next, height-changing edit's walk there and drop every
        // later page.
        let (mut renderer, document, pages) = fully_laid_out_multi_page_renderer();
        rerender_with_centred_first_paragraph(&mut renderer, &document, |renderer, height| {
            renderer.set_fast_replay_trigger(0, height);
        });
        assert_eq!(renderer.layout_page_limit(), None);

        let mut taller = document.as_ref().clone();
        let BodyElement::Paragraph(paragraph) = &mut taller.body.as_mut().unwrap().elements[0]
        else {
            unreachable!();
        };
        paragraph.runs[0].text = "body paragraph ".repeat(40);
        renderer.set_incremental_dirty_from(0);
        renderer.mark_paragraph_dirty(0);
        renderer
            .render_with_numbering_rc(Rc::new(taller), &Options::default(), None, None, None, None)
            .unwrap();
        assert!(renderer.host.page_count() >= pages);
        assert!(renderer.last_layout_complete());
    }

