    #[test]
    fn header_and_footer_copies_leave_no_address_keyed_content_hashes() {
        use jade_painter::recording::RecordingPainter;
        let document = doc_with_paragraph_texts(&["body one", "body two"]);
        let story = |text: &str| doc_with_paragraph_texts(&[text]).body.unwrap();
        let mut renderer = CanvasRenderer::with_host(
            Box::new(NonCanvasHost {
                painter: RecordingPainter::new(),
            }),
            false,
        )
        .unwrap();
        renderer.set_header_footer_bodies(
            Some(story("header")),
            Some(story("footer")),
            None,
            None,
            None,
            None,
        );
        renderer.render(&document, &Options::default()).unwrap();
        // Page chrome is drawn from copies that are dropped afterwards; a
        // hash cached under such an address would be served to whatever body
        // paragraph is allocated there next. Only the two body paragraphs may
        // be cached.
        assert_eq!(renderer.paragraph_content_hash_cache.borrow().len(), 2);
    }

    #[test]
    fn paragraph_border_box_reserves_space_and_width_once_per_box() {
        use jade_docx_reader::document::{BorderEdge, ParagraphBorders};
        use jade_painter::recording::RecordingPainter;
        let texts = [
            "above",
            "rule",
            "after rule",
            "box one",
            "box two",
            "after box",
        ];
        let tops = |document: &Document| {
            let mut renderer = CanvasRenderer::with_host(
                Box::new(NonCanvasHost {
                    painter: RecordingPainter::new(),
                }),
                false,
            )
            .unwrap();
            renderer.render(document, &Options::default()).unwrap();
            (0..texts.len())
                .map(|index| renderer.paragraph_layout_origin(index).unwrap().2)
                .collect::<Vec<_>>()
        };
        let mut document = doc_with_paragraph_texts(&texts);
        let plain = tops(&document);
        let edge = BorderEdge {
            val: Some("single".to_string()),
            size_eighths: Some(8),
            space: Some(4),
            color: None,
        };
        let elements = &mut document.body.as_mut().unwrap().elements;
        let mut set_borders = |index: usize, borders: ParagraphBorders| {
            let BodyElement::Paragraph(paragraph) = &mut elements[index] else {
                unreachable!()
            };
            paragraph.properties = Some(ParagraphProperties {
                borders: Some(borders),
                ..ParagraphProperties::default()
            });
        };
        set_borders(
            1,
            ParagraphBorders {
                bottom: Some(edge.clone()),
                ..ParagraphBorders::default()
            },
        );
        let boxed = ParagraphBorders {
            top: Some(edge.clone()),
            bottom: Some(edge),
            ..ParagraphBorders::default()
        };
        set_borders(3, boxed.clone());
        set_borders(4, boxed);
        // Word for Mac 16.113: 1pt rules 4pt from the text take 5pt; the two
        // boxed paragraphs share one box, so only its outer rules count.
        let shifts = tops(&document)
            .iter()
            .zip(&plain)
            .map(|(bordered, plain)| ((bordered - plain) * 72.0 / 96.0 * 100.0).round() / 100.0)
            .collect::<Vec<_>>();
        assert_eq!(shifts, vec![0.0, 0.0, 5.0, 10.0, 10.0, 15.0]);
    }

    #[test]
    fn replacing_document_rc_discards_old_pointer_hashes_but_keeps_current_ones() {
        let (mut renderer, _) = recording_renderer();
        let document = Rc::new(doc_with_paragraph_texts(&["body"]));
        renderer
            .render_with_numbering_rc(
                Rc::clone(&document),
                &Options::default(),
                None,
                None,
                None,
                None,
            )
            .unwrap();
        assert_eq!(renderer.paragraph_content_hash_cache.borrow().len(), 1);
        let mut next = (*document).clone();
        let BodyElement::Paragraph(paragraph) = &mut next.body.as_mut().unwrap().elements[0] else {
            unreachable!();
        };
        paragraph.properties = Some(ParagraphProperties {
            spacing: Some(Spacing {
                after: Some(12.0),
                ..Spacing::default()
            }),
            ..ParagraphProperties::default()
        });
        let next = Rc::new(next);
        renderer
            .render_with_numbering_rc(
                Rc::clone(&next),
                &Options::default(),
                None,
                None,
                None,
                None,
            )
            .unwrap();
        let old = document.body.as_ref().unwrap().elements[0]
            .as_paragraph()
            .unwrap();
        let old_key = old as *const Paragraph as usize;
        assert!(!renderer
            .paragraph_content_hash_cache
            .borrow()
            .contains_key(&old_key));
        assert_eq!(renderer.paragraph_content_hash_cache.borrow().len(), 1);
        let current = renderer.paragraph_content_hash_cache.borrow().clone();
        renderer.mark_full_repaint();
        renderer
            .render_with_numbering_rc(next, &Options::default(), None, None, None, None)
            .unwrap();
        assert_eq!(*renderer.paragraph_content_hash_cache.borrow(), current);
    }

    #[test]
    fn markup_reuses_revision_free_unnumbered_paragraph_paint() {
        let document = doc_with_paragraph_texts(&["plain text", "another paragraph"]);
        let (mut renderer, _) = recording_renderer();
        let options = Options {
            render_changes: true,
            show_formatting_marks: false,
            ..Options::default()
        };
        renderer.render(&document, &options).unwrap();
        let origins = (0..2)
            .map(|index| renderer.paragraph_layout_origin(index))
            .collect::<Vec<_>>();
        renderer.mark_full_repaint();
        renderer.render(&document, &options).unwrap();
        assert!(renderer.paragraph_render_cache_stats().hits > 0);
        assert_eq!(
            (0..2)
                .map(|index| renderer.paragraph_layout_origin(index))
                .collect::<Vec<_>>(),
            origins,
        );
    }

    #[test]
    fn markup_keeps_revision_and_numbering_paragraphs_out_of_paint_cache() {
        for numbered in [false, true] {
            let mut document = doc_with_paragraph_texts(&["conservative fallback"]);
            let BodyElement::Paragraph(paragraph) =
                &mut document.body.as_mut().unwrap().elements[0]
            else {
                unreachable!()
            };
            if numbered {
                paragraph.properties = Some(ParagraphProperties {
                    numbering: Some(Numbering {
                        id: Some("1".into()),
                        level: Some(0),
                    }),
                    ..ParagraphProperties::default()
                });
            } else {
                paragraph.runs = vec![build_revision_run(RevisionKind::Deleted)];
            }
            let (mut renderer, _) = recording_renderer();
            let options = Options {
                render_changes: true,
                show_formatting_marks: false,
                ..Options::default()
            };
            renderer.render(&document, &options).unwrap();
            renderer.mark_full_repaint();
            renderer.render(&document, &options).unwrap();
            assert_eq!(renderer.paragraph_render_cache_stats().hits, 0);
            assert_eq!(renderer.paragraph_render_cache_stats().cached_entries, 0);
        }
    }

    #[test]
    fn cached_predecessor_preserves_collapsed_spacing_before_uncached_paragraph() {
        use jade_painter::recording::RecordingPainter;
        let mut document = doc_with_paragraph_texts(&["cached predecessor", "picture", "tail"]);
        for element in &mut document.body.as_mut().unwrap().elements {
            let BodyElement::Paragraph(paragraph) = element else {
                unreachable!()
            };
            paragraph.properties = Some(ParagraphProperties {
                spacing: Some(Spacing {
                    before: Some(6.0),
                    after: Some(6.0),
                    ..Spacing::default()
                }),
                ..ParagraphProperties::default()
            });
        }
        if let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[1]
        {
            paragraph.runs[0].image = Some(RunImage {
                data_uri: Some("data:image/png;base64,eA==".into()),
                width_px: Some(10.0),
                height_px: Some(10.0),
                ..RunImage::default()
            });
        }
        let mut renderer = CanvasRenderer::with_host(
            Box::new(NonCanvasHost {
                painter: RecordingPainter::new(),
            }),
            false,
        )
        .unwrap();
        let options = Options {
            show_formatting_marks: false,
            ..Options::default()
        };
        renderer.render(&document, &options).unwrap();
        let origins = (0..3)
            .map(|index| renderer.paragraph_layout_origin(index))
            .collect::<Vec<_>>();
        renderer.mark_full_repaint();
        renderer.render(&document, &options).unwrap();
        assert_eq!(
            (0..3)
                .map(|index| renderer.paragraph_layout_origin(index))
                .collect::<Vec<_>>(),
            origins,
            "cached predecessor must retain the spacing-after consumed by the next paragraph"
        );
        assert!(renderer.paragraph_render_cache_stats().hits > 0);
        for after in [0.0, 12.0] {
            let BodyElement::Paragraph(first) = &mut document.body.as_mut().unwrap().elements[0]
            else {
                unreachable!()
            };
            first
                .properties
                .as_mut()
                .unwrap()
                .spacing
                .as_mut()
                .unwrap()
                .after = Some(after);
            renderer.mark_full_repaint();
            renderer.render(&document, &options).unwrap();
            let mut cold = CanvasRenderer::with_host(
                Box::new(NonCanvasHost {
                    painter: RecordingPainter::new(),
                }),
                false,
            )
            .unwrap();
            cold.render(&document, &options).unwrap();
            assert_eq!(
                (0..3)
                    .map(|index| renderer.paragraph_layout_origin(index))
                    .collect::<Vec<_>>(),
                (0..3)
                    .map(|index| cold.paragraph_layout_origin(index))
                    .collect::<Vec<_>>()
            );
        }
    }

    #[test]
    fn native_image_drawing_preserves_rotation_flips_and_canvas_state() {
        use jade_painter::recording::{Op, RecordingPainter};
        let painter = RecordingPainter::new();
        let renderer = CanvasRenderer::with_host(
            Box::new(NonCanvasHost {
                painter: painter.clone(),
            }),
            false,
        )
        .unwrap();
        let image = RunImage {
            data_uri: Some("data:image/png;base64,eA==".into()),
            ..RunImage::default()
        };
        renderer
            .draw_image_element(
                &image,
                ImageDrawSpec {
                    x: 10.0,
                    y: 20.0,
                    width: 80.0,
                    height: 40.0,
                    rotation_deg: 90.0,
                    flip_horizontal: true,
                    flip_vertical: false,
                    crop: None,
                    paragraph_index: 0,
                    run_index: 0,
                },
            )
            .unwrap();
        let ops = painter.ops();
        assert!(ops.contains(&Op::Translate(50.0, 40.0)));
        assert!(ops.contains(&Op::Rotate(std::f64::consts::FRAC_PI_2)));
        assert!(ops.contains(&Op::Scale(-1.0, 1.0)));
        assert!(ops.contains(&Op::Translate(-50.0, -40.0)));
        assert!(ops.contains(&Op::FillRect(10.0, 20.0, 80.0, 40.0)));
        assert!(matches!(ops.last(), Some(Op::Restore)));
    }

    #[test]
    fn unspecified_endnote_format_uses_words_lower_roman_default() {
        let (mut renderer, _) = recording_renderer();
        for (ordinal, roman) in [(1, "i"), (2, "ii"), (4, "iv")] {
            assert_eq!(renderer.format_note_number(ordinal, false), roman);
            assert_eq!(
                renderer.format_note_number(ordinal, true),
                ordinal.to_string()
            );
        }
        renderer.endnote_number_format = Some("decimal".into());
        renderer.endnote_number_start = Some(7);
        assert_eq!(renderer.format_note_number(1, false), "7");
        renderer.section_endnote_numbering = vec![ResolvedNoteNumbering {
            format: Some("upperletter".into()),
            start: Some(3),
            restart: NoteRestart::Continuous,
        }];
        assert_eq!(renderer.format_note_number(1, false), "C");
        assert_eq!(renderer.format_note_number(1, true), "1");
    }

    #[test]
    fn distributed_final_line_paint_and_selection_use_shared_character_advances() {
        use jade_painter::recording::Op;
        let mut document = doc_with_paragraph_texts(&["ABCD"]);
        let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[0]
        else {
            unreachable!()
        };
        paragraph.properties = Some(ParagraphProperties {
            alignment: Some("distribute".into()),
            ..ParagraphProperties::default()
        });
        let (mut renderer, painter) = recording_renderer();
        for _ in 0..2 {
            painter.clear();
            renderer.mark_full_repaint();
            renderer
                .render(
                    &document,
                    &Options {
                        show_formatting_marks: false,
                        ..Options::default()
                    },
                )
                .unwrap();
            let lines = renderer.layout_debug_lines();
            let line = &lines[0];
            let glyphs = line
                .fragments
                .iter()
                .flat_map(|f| {
                    f.glyphs.iter().map(|g| {
                        (
                            g.text.clone(),
                            f.x + g.x - 2.0 * line.report_x_offset,
                            g.width,
                        )
                    })
                })
                .collect::<Vec<_>>();
            assert_eq!(glyphs.len(), 4);
            let paint = painter
                .ops()
                .into_iter()
                .filter_map(|op| match op {
                    Op::FillText(text, x, _) if ["A", "B", "C", "D"].contains(&text.as_str()) => {
                        Some((text, x))
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(paint.len(), 4);
            for ((text, x), (captured_text, captured_x, _)) in paint.iter().zip(&glyphs) {
                assert_eq!(text, captured_text);
                assert!((x - captured_x).abs() < 1e-6);
            }
            let left = renderer.current_column_x();
            let right = left + renderer.current_column_width();
            assert!((glyphs[0].1 - left).abs() < 1e-6);
            assert!((glyphs[3].1 + glyphs[3].2 - right).abs() < 1e-6);
            let gaps = glyphs
                .windows(2)
                .map(|g| g[1].1 - g[0].1 - g[0].2)
                .collect::<Vec<_>>();
            assert!(gaps.iter().all(|gap| gap.abs() < 1e-6));
            assert!(glyphs[0].2 > glyphs[3].2 * 2.0);
        }
    }

    #[test]
    fn debug_fragments_preserve_painted_baselines_across_cache_replay() {
        use jade_painter::recording::Op;

        let mut document = doc_with_paragraph_texts(&["A"]);
        let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[0]
        else {
            unreachable!()
        };
        let template = paragraph.runs[0].clone();
        paragraph.runs = [
            ("A", None, None),
            ("B", Some("superscript"), None),
            ("C", None, Some(-3.0)),
        ]
        .into_iter()
        .map(|(text, baseline, position)| {
            let mut run = template.clone();
            run.text = text.into();
            run.properties = Some(RunProperties {
                font_size: Some(12.0),
                baseline: baseline.map(Rc::from),
                text_position: position,
                ..RunProperties::default()
            });
            run
        })
        .collect();
        let (mut renderer, painter) = recording_renderer();
        for _ in 0..2 {
            painter.clear();
            renderer.mark_full_repaint();
            renderer
                .render(
                    &document,
                    &Options {
                        show_formatting_marks: false,
                        ..Options::default()
                    },
                )
                .unwrap();
            let painted = painter
                .ops()
                .into_iter()
                .filter_map(|op| match op {
                    Op::FillText(text, x, y) if ["A", "B", "C"].contains(&text.as_str()) => {
                        Some((text, x, y))
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            let lines = renderer.layout_debug_lines();
            let mut captured = Vec::new();
            for line in &lines {
                for fragment in &line.fragments {
                    let metadata = serde_json::to_value(fragment).unwrap();
                    let baseline = metadata
                        .get("baseline")
                        .and_then(serde_json::Value::as_f64)
                        .unwrap_or(line.baseline);
                    for glyph in &fragment.glyphs {
                        captured.push((
                            glyph.text.clone(),
                            fragment.x + glyph.x - 2.0 * line.report_x_offset,
                            baseline,
                        ));
                    }
                }
            }
            assert_eq!(captured.len(), 3);
            assert_eq!(captured, painted);
        }
    }

