    #[test]
    fn generated_numbering_keeps_regular_widths_under_balanced_sbcs() {
        let renderer = CanvasRenderer::with_host(
            Box::new(NonCanvasHost {
                painter: jade_painter::recording::RecordingPainter::with_width_per_char(7.0),
            }),
            true,
        )
        .unwrap();
        let style = renderer.resolve_applied_run_style_cached(Some(&RunProperties {
            font_size: Some(10.5),
            char_spacing: Some(0.25),
            ..RunProperties::default()
        }));
        let mut paragraph_style = ParagraphStyle {
            word_platform: jade_docx_layout::line_metrics::WordLayoutPlatform::Windows,
            enable_line_break_rules: true,
            doc_grid_char_space_px: Some(0.5),
            ..ParagraphStyle::default()
        };
        for label in ["(17)\u{3000}", "42. ", "III. "] {
            let context = NumberingTextContext {
                margin_line_number: false,
                paragraph_style: Some(&paragraph_style),
                suffix_space: label.ends_with(' '),
                following_grapheme: Some("本文"),
            };
            let regular = renderer
                .measure_numbering_text_plan(label, &style, context)
                .unwrap();
            paragraph_style
                .east_asian_rules
                .balance_single_byte_double_byte_width = true;
            let balanced = renderer
                .measure_numbering_text_plan(
                    label,
                    &style,
                    NumberingTextContext {
                        margin_line_number: false,
                        paragraph_style: Some(&paragraph_style),
                        suffix_space: label.ends_with(' '),
                        following_grapheme: Some("本文"),
                    },
                )
                .unwrap();
            assert_eq!(balanced, regular, "generated label {label}");
            paragraph_style
                .east_asian_rules
                .balance_single_byte_double_byte_width = false;
        }
    }

    #[test]
    fn numbering_space_suffix_paints_in_hansi_font_with_following_tracking() {
        use jade_painter::recording::Op;
        let (mut renderer, painter) = recording_renderer();
        let pending = PendingNumberingRender {
            paragraph_index: 0,
            number_x: 0.0,
            display_text: "1. ".into(),
            display_props: Some(RunProperties {
                font_size: Some(10.0),
                char_spacing: Some(-1.0),
                fonts: Some(RunFonts {
                    ascii: Some("MS Gothic".into()),
                    h_ansi: Some("Arial".into()),
                    ..RunFonts::default()
                }),
                ..RunProperties::default()
            }),
            deleted_text: None,
            suffix_space: true,
            following_grapheme: Some("A".into()),
            picture: None,
        };
        renderer
            .draw_pending_numbering_marker(&pending, 20.0, 16.0, None, &mut None)
            .unwrap();
        let mut active_font = String::new();
        let mut painted = Vec::new();
        for op in painter.ops() {
            match op {
                Op::SetFont(font) => active_font = font,
                Op::FillText(text, _, _) => painted.push((text, active_font.clone())),
                _ => {}
            }
        }
        assert_eq!(painted.len(), 3);
        assert!(painted[0].1.contains("MS Gothic"));
        assert!(painted[1].1.contains("MS Gothic"));
        assert!(
            painted[2].1.contains("Arial"),
            "suffix font: {}",
            painted[2].1
        );
        let style = renderer
            .apply_run_style(pending.display_props.as_ref())
            .unwrap();
        let context = NumberingTextContext {
            margin_line_number: false,
            paragraph_style: None,
            suffix_space: true,
            following_grapheme: None,
        };
        let terminal_width = renderer
            .measure_numbering_text_plan(&pending.display_text, &style, context)
            .unwrap();
        let followed_width = renderer
            .measure_numbering_text_plan(
                &pending.display_text,
                &style,
                NumberingTextContext {
                    margin_line_number: false,
                    following_grapheme: Some("A"),
                    ..context
                },
            )
            .unwrap();
        assert!((followed_width - terminal_width - points_to_px(-1.0)).abs() < 1e-9);
    }

    #[test]
    fn numbering_advances_and_paint_skip_unused_ink_box_queries() {
        use jade_painter::recording::Op;
        for label in ["17. ", "第１７条"] {
            let (mut renderer, painter) = recording_renderer();
            let pending = PendingNumberingRender {
                paragraph_index: 0,
                number_x: 40.0,
                display_text: label.into(),
                display_props: Some(RunProperties {
                    font_size: Some(10.0),
                    bold: Some(true),
                    fonts: Some(RunFonts {
                        ascii: Some("Yu Gothic Light".into()),
                        h_ansi: Some("Arial".into()),
                        east_asia: Some("MS Gothic".into()),
                        ..RunFonts::default()
                    }),
                    char_spacing: Some(-0.25),
                    ..RunProperties::default()
                }),
                deleted_text: None,
                suffix_space: label.ends_with(' '),
                following_grapheme: Some("A".into()),
                picture: None,
            };
            let style = renderer
                .apply_run_style(pending.display_props.as_ref())
                .unwrap();
            let context = NumberingTextContext {
                margin_line_number: false,
                paragraph_style: None,
                suffix_space: pending.suffix_space,
                following_grapheme: pending.following_grapheme.as_deref(),
            };
            let width = renderer
                .measure_numbering_text_plan(label, &style, context)
                .unwrap();
            assert!(width.is_finite() && width > 0.0);
            assert!(
                renderer.font_vertical_metrics_cache.borrow().is_empty(),
                "width-only numbering must not query an unused ink box"
            );
            renderer
                .draw_pending_numbering_marker(&pending, 60.0, 16.0, None, &mut None)
                .unwrap();
            assert!(renderer.font_vertical_metrics_cache.borrow().is_empty());
            let painted: Vec<_> = painter
                .ops()
                .into_iter()
                .filter(|op| matches!(op, Op::FillText(..)))
                .collect();
            assert_eq!(painted.len(), label.chars().count());

            painter.clear();
            renderer.set_auxiliary_story_capture_enabled(true);
            renderer
                .draw_pending_numbering_marker(&pending, 60.0, 16.0, None, &mut None)
                .unwrap();
            let captured_paint: Vec<_> = painter
                .ops()
                .into_iter()
                .filter(|op| matches!(op, Op::FillText(..)))
                .collect();
            assert_eq!(painted, captured_paint, "capture cannot move marker ink");
            assert!(!renderer.font_vertical_metrics_cache.borrow().is_empty());
            let marker = &renderer.auxiliary_story_debug_lines()[0].line;
            assert!(marker.top.is_finite() && marker.height > 0.0);
            assert!((marker.end_x - marker.start_x - width).abs() < 1e-9);

            // An empty numbered paragraph does consume the marker's box for
            // its content top/height, even with diagnostic capture disabled.
            renderer.set_auxiliary_story_capture_enabled(false);
            renderer.font_vertical_metrics_cache.borrow_mut().clear();
            let (top, height) = renderer
                .empty_paragraph_content_metrics(Some(&pending), 16.0, false)
                .unwrap();
            assert!(top.is_finite() && height > 0.0);
            assert!(!renderer.font_vertical_metrics_cache.borrow().is_empty());
        }
    }

    /// An empty numbered paragraph's line holds only its label. Where text
    /// lines take Word's line box per face, the label line does too, over
    /// every glyph of the label: the ideographic space of `(6)　` brings
    /// ＭＳ 明朝's box, so the label sits where a text line's baseline would
    /// (contract-clause-page-top, Word for Mac 16.114).
    #[test]
    fn empty_numbered_line_takes_words_line_box_over_the_whole_label() {
        let (mut renderer, _) = recording_renderer();
        let pending = PendingNumberingRender {
            paragraph_index: 0,
            number_x: 40.0,
            display_text: "(6)　".into(),
            display_props: Some(RunProperties {
                font_size: Some(10.5),
                fonts: Some(RunFonts {
                    ascii: Some("Times New Roman".into()),
                    h_ansi: Some("ＭＳ 明朝".into()),
                    east_asia: Some("ＭＳ 明朝".into()),
                    ..RunFonts::default()
                }),
                ..RunProperties::default()
            }),
            deleted_text: None,
            suffix_space: false,
            following_grapheme: None,
            picture: None,
        };
        let style = renderer
            .apply_run_style(pending.display_props.as_ref())
            .unwrap();
        let box_of = |grapheme: &str| {
            let script = jade_docx_layout::line_wrap::classify_script(grapheme);
            jade_docx_layout::line_metrics::word_font_vertical_metrics_px(
                style.resolved.descriptor_for_grapheme(grapheme, script),
            )
            .unwrap()
        };
        let (ascent, descent) = ["(", "6", ")", "　"]
            .into_iter()
            .map(box_of)
            .fold((0.0_f64, 0.0_f64), |(a, d), (ga, gd)| {
                (a.max(ga), d.max(gd))
            });
        assert!(
            box_of("　") != box_of("6"),
            "the faces must differ for the test"
        );
        let (top, height) = renderer
            .empty_paragraph_content_metrics(Some(&pending), 24.0, true)
            .unwrap();
        assert!((top + ascent).abs() < 1e-9, "{top} vs {ascent}");
        assert!((height - (ascent + descent)).abs() < 1e-9);
    }

    #[test]
    fn numbering_capture_records_painted_glyphs_only_when_requested() {
        use jade_painter::recording::Op;

        let (mut renderer, painter) = recording_renderer();
        renderer.current_page_number = 3;
        renderer.page_offset_y = 2400.0;
        let pending = PendingNumberingRender {
            paragraph_index: 7,
            number_x: 40.0,
            display_text: "第４４条".into(),
            display_props: Some(RunProperties {
                char_spacing: Some(2.0),
                baseline: Some("superscript".into()),
                ..RunProperties::default()
            }),
            deleted_text: Some("第４３条".into()),
            suffix_space: false,
            following_grapheme: None,
            picture: None,
        };
        renderer
            .draw_pending_numbering_marker(&pending, 60.0, 16.0, None, &mut None)
            .unwrap();
        assert!(renderer.auxiliary_story_debug_lines().is_empty());

        painter.clear();
        renderer.set_auxiliary_story_capture_enabled(true);
        renderer
            .draw_pending_numbering_marker(&pending, 60.0, 16.0, None, &mut None)
            .unwrap();
        let painted = painter
            .ops()
            .into_iter()
            .filter_map(|op| match op {
                Op::FillText(text, x, y) => Some((text, x, y)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let captured = renderer
            .auxiliary_story_debug_lines()
            .iter()
            .flat_map(|entry| {
                assert_eq!(entry.story, "numbering");
                assert_eq!(entry.page, 2);
                assert_eq!(entry.line.paragraph, 7);
                assert_eq!(entry.line.report_x_offset, 0.0);
                assert_eq!(entry.line.absolute_baseline, entry.line.baseline + 2400.0);
                entry.line.fragments.iter().flat_map(|fragment| {
                    fragment.glyphs.iter().map(|glyph| {
                        (
                            glyph.text.clone(),
                            fragment.x + glyph.x,
                            entry.line.baseline,
                        )
                    })
                })
            })
            .collect::<Vec<_>>();
        assert!(!painted.is_empty());
        assert_eq!(captured, painted);
        assert!(renderer.selection.paragraphs().is_empty());
    }

    #[test]
    fn numbered_first_line_unions_label_ascent_without_its_descent_or_continuation() {
        use jade_docx_layout::line_metrics::{set_word_layout_platform, WordLayoutPlatform};
        set_word_layout_platform(WordLayoutPlatform::Mac);
        let numbering = NumberingPart::from_xml(
            r#"<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
              <w:abstractNum w:abstractNumId="1"><w:lvl w:ilvl="0">
                <w:start w:val="1"/><w:numFmt w:val="decimal"/>
                <w:lvlText w:val="第%1条"/><w:suff w:val="nothing"/>
                <w:rPr><w:rFonts w:ascii="Meiryo" w:eastAsia="Meiryo"/><w:sz w:val="21"/><w:b/></w:rPr>
              </w:lvl></w:abstractNum><w:num w:numId="1"><w:abstractNumId w:val="1"/></w:num>
            </w:numbering>"#,
        ).unwrap();
        let mut document = doc_with_paragraph_texts(&["ああ\nいい"]);
        document.default_section = Some(SectionProperties {
            doc_grid: Some(DocGrid {
                grid_type: Some("lines".into()),
                line_pitch: Some(18.0),
                char_space: None,
            }),
            ..Default::default()
        });
        let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[0]
        else {
            unreachable!()
        };
        paragraph.runs[0].properties = Some(RunProperties {
            font_family: Some("MS Mincho".into()),
            font_size: Some(10.5),
            ..Default::default()
        });
        paragraph.properties = Some(ParagraphProperties {
            snap_to_grid: Some(true),
            ..Default::default()
        });
        let (mut plain, _) = recording_renderer();
        plain.render(&document, &Options::default()).unwrap();
        let plain_lines = plain.layout_debug_lines();
        let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[0]
        else {
            unreachable!()
        };
        paragraph.properties.as_mut().unwrap().numbering =
            Some(jade_docx_reader::document::Numbering {
                id: Some("1".into()),
                level: Some(0),
            });
        let (mut numbered, _) = recording_renderer();
        numbered
            .render_with_numbering(
                &document,
                &Options::default(),
                Some(&numbering),
                None,
                None,
                None,
            )
            .unwrap();
        let numbered_lines = numbered.layout_debug_lines();
        assert_eq!(plain_lines.len(), 2);
        assert_eq!(numbered_lines.len(), 2);
        let first_shift_pt = (numbered_lines[0].baseline - plain_lines[0].baseline) * 0.75;
        assert!(
            (first_shift_pt - 1.427).abs() <= 0.375,
            "label ascent shift {first_shift_pt}"
        );
        assert!(
            (numbered_lines[1].baseline - plain_lines[1].baseline).abs() < 1e-6,
            "label descent must not consume a second grid pitch or affect continuation"
        );
        set_word_layout_platform(WordLayoutPlatform::Windows);
    }

