    #[test]
    fn numbering_marker_cache_replay_preserves_initial_glyph_positions() {
        use jade_painter::recording::{Op, RecordingPainter};
        let text_ops = |painter: &RecordingPainter| {
            let mut font = String::new();
            painter
                .ops()
                .into_iter()
                .filter_map(|op| match op {
                    Op::SetFont(value) => {
                        font = value;
                        None
                    }
                    Op::FillText(text, x, y) => Some((text, x, y, font.clone())),
                    _ => None,
                })
                .collect::<Vec<_>>()
        };
        for (text, spacing, deleted, suffix_space) in [
            ("第４４条", 0.0, None, false),
            ("A１２項", 2.0, Some("A１１項"), false),
            ("1. ", -1.0, None, true),
        ] {
            let painter = RecordingPainter::new();
            let mut renderer = CanvasRenderer::with_host(
                Box::new(NonCanvasHost {
                    painter: painter.clone(),
                }),
                false,
            )
            .unwrap();
            let pending = PendingNumberingRender {
                paragraph_index: 0,
                number_x: 10.0,
                display_text: text.into(),
                display_props: Some(RunProperties {
                    char_spacing: Some(spacing),
                    fonts: Some(RunFonts {
                        ascii: Some("MS Gothic".into()),
                        h_ansi: Some("Arial".into()),
                        ..RunFonts::default()
                    }),
                    ..RunProperties::default()
                }),
                deleted_text: deleted.map(str::to_string),
                suffix_space,
                following_grapheme: Some("A".into()),
                picture: None,
            };
            let mut commands = Vec::new();
            renderer
                .draw_pending_numbering_marker(&pending, 20.0, 16.0, None, &mut Some(&mut commands))
                .unwrap();
            let initial = text_ops(&painter);
            painter.clear();
            execute_commands_with_font_state(&painter, &commands, &mut FontStateTracker::new())
                .unwrap();
            assert_eq!(
                text_ops(&painter),
                initial,
                "marker {text} changed when cached"
            );
        }
    }

    #[test]
    fn first_paint_keeps_character_effects_without_waiting_for_cache_replay() {
        use jade_painter::recording::{Op, RecordingPainter};
        for (effect, props) in [
            (
                "outline",
                RunProperties {
                    outline: Some(true),
                    ..RunProperties::default()
                },
            ),
            (
                "shadow",
                RunProperties {
                    shadow: Some(true),
                    ..RunProperties::default()
                },
            ),
            (
                "emboss",
                RunProperties {
                    emboss: Some(true),
                    ..RunProperties::default()
                },
            ),
            (
                "imprint",
                RunProperties {
                    imprint: Some(true),
                    ..RunProperties::default()
                },
            ),
        ] {
            let mut document = doc_with_paragraph_texts(&["Effect", "Plain"]);
            let BodyElement::Paragraph(paragraph) =
                &mut document.body.as_mut().unwrap().elements[0]
            else {
                panic!("paragraph")
            };
            paragraph.runs[0].properties = Some(props);
            let painter = RecordingPainter::new();
            let mut renderer = CanvasRenderer::with_host(
                Box::new(NonCanvasHost {
                    painter: painter.clone(),
                }),
                false,
            )
            .unwrap();
            renderer.mark_full_repaint();
            renderer
                .render(
                    &document,
                    &Options {
                        show_formatting_marks: false,
                        show_crop_marks: false,
                        ..Options::default()
                    },
                )
                .unwrap();
            let ops = painter.ops();
            if effect == "outline" {
                assert!(
                    ops.iter().any(|op| matches!(op, Op::StrokeText(..))),
                    "first paint lost {effect}"
                );
            } else {
                assert!(
                    ops.iter().any(
                        |op| matches!(op, Op::SetShadowColor(color) if color != "rgba(0, 0, 0, 0)")
                    ),
                    "first paint lost {effect}"
                );
                let shadow_end = ops
                    .iter()
                    .rposition(
                        |op| matches!(op, Op::SetShadowColor(color) if color == "rgba(0, 0, 0, 0)"),
                    )
                    .unwrap();
                let plain = ops
                    .iter()
                    .position(|op| matches!(op, Op::FillText(text, ..) if text == "P"))
                    .unwrap();
                assert!(
                    shadow_end < plain,
                    "{effect} leaked into following paragraph"
                );
            }
        }
    }

    /// The renderer runs against a painter that is not the canvas.
    ///
    /// Everything before this could only ever paint through
    /// `Canvas2dPainter`; the defaulted type parameter is what lets a second
    /// backend exist without the browser build changing a line.
    #[test]
    fn the_renderer_can_be_built_on_a_non_canvas_painter() {
        use jade_painter::recording::RecordingPainter;

        let painter = RecordingPainter::new();
        let renderer = CanvasRenderer::<RecordingPainter>::with_host(
            Box::new(NonCanvasHost {
                painter: painter.clone(),
            }),
            true,
        )
        .expect("build a renderer on a non-canvas host");

        // Measuring is the first thing layout asks for, and it is answered
        // without a canvas anywhere in the call.
        let width = renderer
            .measure_text_cached("abcd", "12pt serif")
            .expect("measure without a canvas");
        assert_eq!(width, 40.0);
    }

    /// Table cells measure through the painter, so `MeasureText` operations on
    /// the recording painter are exactly the table's measurements.
    fn table_measure_document() -> Document {
        let cell = |text: &str| jade_docx_reader::document::TableCell {
            blocks: vec![BodyElement::from_paragraph(
                doc_with_paragraph_texts(&[text])
                    .body
                    .and_then(|body| body.elements.into_iter().next())
                    .and_then(|element| match element {
                        BodyElement::Paragraph(paragraph) => Some(*paragraph),
                        _ => None,
                    })
                    .expect("one paragraph"),
            )],
            ..Default::default()
        };
        let row = |left: &str, right: &str| jade_docx_reader::document::TableRow {
            cells: vec![cell(left), cell(right)],
            ..Default::default()
        };
        Document {
            body: Some(Body {
                elements: vec![BodyElement::Table(Box::new(
                    jade_docx_reader::document::Table {
                        rows: vec![
                            row("甲の条項 alpha", "乙 beta"),
                            row("丙 gamma", "丁の欄 delta"),
                        ],
                        ..Default::default()
                    },
                ))],
            }),
            ..Document::default()
        }
    }

    /// Re-renders the table from scratch (as an edit above it would), returning
    /// the texts measured and painted by that second render.
    fn rerender_table_measurements(
        autofit_cache: bool,
    ) -> (Vec<String>, Vec<jade_painter::recording::Op>) {
        use jade_painter::recording::Op;

        let (mut renderer, painter) = recording_renderer();
        renderer.set_table_autofit_cache_enabled(autofit_cache);
        let document = table_measure_document();
        let options = Options::default();
        renderer.render(&document, &options).expect("first render");
        assert!(painter.count(|op| matches!(op, Op::MeasureText(_))) > 0);

        painter.clear();
        renderer.clear_paragraph_wrap_cache();
        renderer.clear_paragraph_layout_cache();
        renderer.clear_paragraph_render_cache();
        renderer.skip_change_detection_once();
        renderer.render(&document, &options).expect("second render");
        let ops = painter.ops();
        let measured = ops
            .iter()
            .filter_map(|op| match op {
                Op::MeasureText(text) => Some(text.clone()),
                _ => None,
            })
            .collect();
        let painted = ops
            .into_iter()
            .filter(|op| matches!(op, Op::FillText(..)))
            .collect();
        (measured, painted)
    }

    #[test]
    fn table_glyph_measurements_outlive_one_table_render() {
        let (cached_measured, cached_painted) = rerender_table_measurements(true);
        let (fresh_measured, fresh_painted) = rerender_table_measurements(false);

        // Per-table caches made every re-layout measure each grapheme again
        // (its advance and its ink overhang). Shared caches leave only the
        // paint pass's one whole-cell measurement per cell.
        let cells = ["甲の条項 alpha", "乙 beta", "丙 gamma", "丁の欄 delta"];
        assert_eq!(cached_measured, cells);
        assert!(fresh_measured.iter().any(|text| text == "甲"));
        assert!(fresh_measured.len() > 4 * cached_measured.len());
        assert!(!cached_painted.is_empty());
        assert_eq!(cached_painted, fresh_painted);
    }

    #[test]
    fn clearing_the_measure_cache_also_clears_table_measurements() {
        use jade_painter::recording::Op;

        let (mut renderer, painter) = recording_renderer();
        let document = table_measure_document();
        let options = Options::default();
        renderer.render(&document, &options).expect("first render");

        painter.clear();
        renderer.clear_text_measure_cache();
        renderer.clear_paragraph_wrap_cache();
        renderer.clear_paragraph_layout_cache();
        renderer.clear_paragraph_render_cache();
        renderer.skip_change_detection_once();
        renderer.render(&document, &options).expect("second render");
        // Font loads clear the measure cache; table cells must re-measure too.
        assert!(painter.count(|op| matches!(op, Op::MeasureText(_))) > 0);
    }

    #[test]
    fn boxed_math_keeps_structure_authored_font_and_captured_baselines() {
        use jade_painter::recording::Op;
        let math = jade_docx_reader::parser::math::parse_math_paragraph(
            r#"<m:oMath xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><m:sSup><m:e><m:r><m:rPr><m:sty m:val="p"/></m:rPr><w:rPr><w:rFonts w:ascii="Cambria Math"/><w:sz w:val="20"/></w:rPr><m:t>x</m:t></m:r></m:e><m:sup><m:r><m:rPr><m:sty m:val="p"/></m:rPr><w:rPr><w:rFonts w:ascii="Cambria Math"/><w:sz w:val="20"/></w:rPr><m:t>2</m:t></m:r></m:sup></m:sSup></m:oMath>"#.to_string(),
        ).unwrap();
        let (mut renderer, painter) = recording_renderer();
        let blocks = [BodyElement::Math(Box::new(math))];
        let measured = renderer
            .measure_text_box_blocks(&blocks, 10.0, 250.0, &mut NumberingCounter::new())
            .unwrap();
        let height = measured.height;
        assert_eq!(measured.line_count, 1);
        painter.clear();
        let mut y = 100.0;
        renderer
            .render_text_box_blocks(
                &blocks,
                10.0,
                250.0,
                &mut y,
                300.0,
                false,
                &mut NumberingCounter::new(),
                0.0,
                &mut 0,
                &mut measured.math_plans.iter(),
            )
            .unwrap();
        assert_eq!(
            painter.count(|op| matches!(op, Op::MeasureText(_))),
            0,
            "painting must reuse measured glyphs"
        );
        let drawn = painter
            .ops()
            .into_iter()
            .filter_map(|op| match op {
                Op::FillText(text, x, y) => Some((text, x, y)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            drawn.iter().map(|x| x.0.as_str()).collect::<Vec<_>>(),
            ["x", "2"]
        );
        assert!(
            drawn[1].2 < drawn[0].2,
            "superscript must paint above the base"
        );
        assert!(
            (y - 100.0 - height).abs() < 1e-9,
            "measurement and paint consume the same height"
        );
        let fonts = effective_fill_text_fonts(&painter.ops());
        assert!(fonts[0].1.contains("13.33px") && fonts[0].1.contains("Cambria Math"));
        assert!(
            fonts[1].1.contains("9.33px"),
            "Cambria fallback scripts scale to 70% of base size"
        );
        let lines = renderer.layout_debug_lines();
        let fragments = &lines[0].fragments;
        assert_eq!(fragments.len(), 2);
        assert!(fragments[1].baseline < fragments[0].baseline);
        assert!(fragments.iter().all(|f| !f.glyphs.is_empty()));
        assert_eq!(lines[0].text, "x2");
    }

