    #[test]
    fn shape_blur_effects_combine_scale_and_restore_painter_state() {
        use jade_painter::recording::{Op, RecordingPainter};

        let painter = RecordingPainter::new();
        assert!(<CanvasRenderer>::begin_shape_blur_effects(
            &painter,
            None,
            Some(3.0),
            2.0,
            4.0,
        ));
        painter.fill_rect(0.0, 0.0, 10.0, 10.0);
        painter.restore();

        assert_eq!(
            painter.ops(),
            vec![
                Op::Save,
                Op::SetBlurFilter(9.0),
                Op::FillRect(0.0, 0.0, 10.0, 10.0),
                Op::Restore,
            ]
        );
        assert!(<CanvasRenderer>::begin_shape_blur_effects(
            &painter,
            Some(3.0),
            Some(4.0),
            1.0,
            1.0,
        ));
        painter.restore();
        assert!(painter.ops().contains(&Op::SetBlurFilter(5.0)));
        assert!(!<CanvasRenderer>::begin_shape_blur_effects(
            &painter, None, None, 1.0, 1.0,
        ));
    }

    #[test]
    fn nested_shape_group_maps_coordinates_and_records_child_hyperlinks() {
        use jade_painter::recording::Op;

        let (mut renderer, painter) = recording_renderer();
        let nested = RunShapeGroup {
            x: 200.0,
            y: 100.0,
            width: 400.0,
            height: 300.0,
            child_offset_x: 10.0,
            child_offset_y: 20.0,
            child_extent_width: 200.0,
            child_extent_height: 100.0,
            rotation_deg: 45.0,
            children: vec![RunGroupShape {
                x: 60.0,
                y: 45.0,
                width: 100.0,
                height: 50.0,
                fill_color: Some("#00AAFF".to_string()),
                hyperlink: Some(crate::document::RunHyperlink {
                    target: Some("https://example.com/nested".to_string()),
                    ..crate::document::RunHyperlink::default()
                }),
                ..RunGroupShape::default()
            }],
            ..RunShapeGroup::default()
        };
        let group = RunShapeGroup {
            child_extent_width: 1000.0,
            child_extent_height: 1000.0,
            groups: vec![nested],
            ..RunShapeGroup::default()
        };
        let draw_spec = ImageDrawSpec {
            x: 0.0,
            y: 0.0,
            width: 100.0,
            height: 100.0,
            rotation_deg: 0.0,
            flip_horizontal: false,
            flip_vertical: false,
            crop: None,
            paragraph_index: 7,
            run_index: 3,
        };

        renderer
            .draw_shape_group(&group, draw_spec)
            .expect("paint nested group");
        let ops = painter.ops();
        assert!(ops.contains(&Op::SetFillStyle("#00AAFF".to_string())));
        assert!(ops.iter().any(|op| {
            matches!(
                op,
                Op::Rect(x, y, width, height)
                    if (*x - 30.0).abs() < 0.000_001
                        && (*y - 17.5).abs() < 0.000_001
                        && (*width - 20.0).abs() < 0.000_001
                        && (*height - 15.0).abs() < 0.000_001
            )
        }));
        assert!(ops.iter().any(|op| {
            matches!(op, Op::Rotate(radians) if (*radians - 45_f64.to_radians()).abs() < 0.000_001)
        }));

        renderer.record_shape_group_hyperlinks(&group, draw_spec, 3, 3, None);
        let region = renderer
            .hyperlink_regions
            .last()
            .expect("nested hyperlink region");
        assert_eq!(region.paragraph, 7);
        assert_eq!(region.target.as_deref(), Some("https://example.com/nested"));
        // The nested group's 45-degree transform must enlarge the axis-aligned
        // hit box beyond the unrotated 20x15 child rectangle.
        assert!(region.width > 20.0);
        assert!(region.height > 15.0);
    }

    #[test]
    fn nested_shape_group_text_is_captured_as_a_text_box_story() {
        let (mut renderer, _) = recording_renderer();
        renderer.set_auxiliary_story_capture_enabled(true);
        let group = RunShapeGroup {
            child_extent_width: 1000.0,
            child_extent_height: 1000.0,
            groups: vec![RunShapeGroup {
                x: 100.0,
                y: 100.0,
                width: 800.0,
                height: 800.0,
                child_extent_width: 100.0,
                child_extent_height: 100.0,
                children: vec![RunGroupShape {
                    width: 100.0,
                    height: 100.0,
                    text: "nested".to_string(),
                    insets: TextBoxInsets {
                        left_px: 0.0,
                        top_px: 0.0,
                        right_px: 0.0,
                        bottom_px: 0.0,
                    },
                    ..RunGroupShape::default()
                }],
                ..RunShapeGroup::default()
            }],
            ..RunShapeGroup::default()
        };
        let draw_spec = ImageDrawSpec {
            x: 0.0,
            y: 0.0,
            width: 100.0,
            height: 100.0,
            rotation_deg: 0.0,
            flip_horizontal: false,
            flip_vertical: false,
            crop: None,
            paragraph_index: 0,
            run_index: 0,
        };

        renderer
            .draw_shape_group(&group, draw_spec)
            .expect("paint nested group");
        let lines = renderer.auxiliary_story_debug_lines();
        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].story, "text_box");
        assert_eq!(lines[0].line.text, "nested");
        assert_eq!(lines[0].page, lines[0].line.page);

        let (mut renderer, _) = recording_renderer();
        let mut document = doc_with_paragraph_texts(&["body"]);
        let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[0]
        else {
            panic!("expected paragraph");
        };
        let mut group_run = build_run(None);
        group_run.text.clear();
        group_run.image = Some(RunImage {
            width_px: Some(100.0),
            height_px: Some(100.0),
            shape_group: Some(group),
            ..RunImage::default()
        });
        paragraph.runs.push(group_run);
        renderer
            .render(&document, &Options::default())
            .expect("render grouped shape");
        let snapshot = renderer.capture_full_layout_debug().expect("full capture");
        assert!(snapshot.body_lines.iter().any(|line| line.text == "body"));
        assert!(!snapshot.body_lines.iter().any(|line| line.text == "nested"));
        assert!(snapshot
            .auxiliary_lines
            .iter()
            .any(|entry| entry.story == "text_box" && entry.line.text == "nested"));
        let region = snapshot
            .grouped_shape_text_regions
            .first()
            .expect("nested shape text region");
        assert_eq!(region.paragraph_index, 0);
        assert_eq!(region.run_index, 1);
        assert_eq!(region.group_path, vec![0]);
        assert_eq!(region.child_index, 0);
        assert!(snapshot.source_text_stories.iter().any(|source| {
            source.kind == "grouped_shape_text"
                && source.paragraph_index == region.paragraph_index
                && source.run_index == region.run_index
                && source.group_path == region.group_path
                && source.child_index == Some(region.child_index)
        }));
        assert_eq!(
            region.content_paragraph_end,
            region.content_paragraph_start + 1
        );
        assert!(snapshot.auxiliary_lines.iter().any(|entry| {
            entry.story == "text_box" && entry.line.paragraph == region.content_paragraph_start
        }));
        assert!(snapshot.known_uncaptured_stories.contains(&"text_boxes"));
        assert!(snapshot.text_box_source_inventory_complete);
    }

    #[test]
    fn full_layout_capture_links_rendered_text_box_region_to_story_line() {
        let (mut renderer, _) = recording_renderer();
        let mut document = doc_with_paragraph_texts(&["body"]);
        let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[0]
        else {
            panic!("expected paragraph");
        };
        let mut box_run = build_run(None);
        box_run.text.clear();
        box_run.text_box = Some(page_anchored_text_box(
            None,
            vec![text_box_run("inside", None)],
        ));
        paragraph.runs.push(box_run);
        renderer
            .render(&document, &Options::default())
            .expect("render text box");

        let snapshot = renderer.capture_full_layout_debug().expect("full capture");
        let region = snapshot
            .text_box_regions
            .first()
            .expect("rendered box region");
        assert!(snapshot.source_text_stories.iter().any(|source| {
            source.kind == "text_box"
                && source.paragraph_index == region.paragraph_index
                && source.run_index == region.run_index
        }));
        assert_eq!(
            region.content_paragraph_end,
            region.content_paragraph_start + 1
        );
        assert!(snapshot.auxiliary_lines.iter().any(|entry| {
            entry.story == "text_box"
                && entry.line.paragraph == region.content_paragraph_start
                && entry.line.text == "inside"
        }));
        assert!(!snapshot.body_lines.iter().any(|line| line.text == "inside"));
        assert!(snapshot.known_uncaptured_stories.contains(&"text_boxes"));
        assert!(snapshot.text_box_source_inventory_complete);
    }

    #[test]
    fn text_box_inventory_excludes_unindexed_note_header_and_nested_boxes() {
        let (mut renderer, _) = recording_renderer();
        let mut document = doc_with_paragraph_texts(&["body"]);
        renderer.last_document = Some(Rc::new(document.clone()));
        assert!(renderer.text_box_source_inventory_complete());

        let mut box_run = build_run(None);
        box_run.text_box = Some(page_anchored_text_box(
            None,
            vec![text_box_run("note", None)],
        ));
        let note_paragraph = BodyElement::from_paragraph(Paragraph {
            runs: vec![box_run.clone()],
            properties: None,
            node_id: None,
            comment_ranges: Vec::new(),
            comment_markers: Vec::new(),
        });
        document.footnotes.insert(
            "1".into(),
            crate::document::Note {
                id: "1".into(),
                note_type: None,
                body: vec![note_paragraph.clone()],
            },
        );
        renderer.last_document = Some(Rc::new(document.clone()));
        assert!(!renderer.text_box_source_inventory_complete());

        document.footnotes.clear();
        renderer.last_document = Some(Rc::new(document.clone()));
        renderer.header_body = Some(Body {
            elements: vec![note_paragraph],
        });
        assert!(!renderer.text_box_source_inventory_complete());

        renderer.header_body = None;
        let mut outer_run = build_run(None);
        outer_run.text_box = Some(page_anchored_text_box(None, vec![box_run]));
        let BodyElement::Paragraph(paragraph) = &mut document.body.as_mut().unwrap().elements[0]
        else {
            panic!("expected paragraph");
        };
        paragraph.runs.push(outer_run);
        renderer.last_document = Some(Rc::new(document));
        assert!(!renderer.text_box_source_inventory_complete());
    }

    #[test]
    fn source_surface_inventory_includes_endnotes_after_body_and_footnotes() {
        let mut document = doc_with_paragraph_texts(&["body"]);
        let note_body = doc_with_paragraph_texts(&["note"]).body.unwrap().elements;
        for (notes, id) in [
            (&mut document.footnotes, "1"),
            (&mut document.endnotes, "2"),
        ] {
            notes.insert(
                id.into(),
                crate::document::Note {
                    id: id.into(),
                    note_type: None,
                    body: note_body.clone(),
                },
            );
        }
        assert_eq!(source_renderer_paragraph_indices(&document), vec![0, 1, 2]);
        let (stories, complete) = source_text_stories(&document);
        assert!(complete);
        assert!(stories.is_empty());
    }

    #[test]
    fn styles_part_wins_over_styles_with_effects() {
        // `table-repeating-header.docx` carries both parts; its Title is 22pt
        // in `styles.xml` (what Word for Mac prints) and 26pt in the Word 2007
        // `stylesWithEffects.xml` copy.
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let bytes =
            std::fs::read(root.join("public/fixtures/table-repeating-header.docx")).unwrap();
        let model =
            futures::executor::block_on(WordDocument::load(&bytes, &Options::default())).unwrap();
        let document = model.document.as_ref().unwrap();
        let BodyElement::Paragraph(title) = &document.body.as_ref().unwrap().elements[0] else {
            panic!("expected the title paragraph");
        };
        assert_eq!(
            title.runs[0]
                .properties
                .as_ref()
                .and_then(|props| props.font_size),
            Some(22.0)
        );
    }

    #[test]
    fn source_surface_inventory_matches_pinned_docx_corpus() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let corpus: serde_json::Value = serde_json::from_slice(
            &std::fs::read(root.join("tests/word-oracle/release-corpus.json")).unwrap(),
        )
        .unwrap();
        let mut failures = Vec::new();
        for fixture in corpus["fixtures"].as_array().unwrap() {
            let name = fixture["fixture"].as_str().unwrap();
            let bytes = std::fs::read(root.join(format!("public/fixtures/{name}.docx"))).unwrap();
            let model =
                futures::executor::block_on(WordDocument::load(&bytes, &Options::default()))
                    .unwrap_or_else(|error| panic!("load {name}: {error}"));
            let document = model.document.as_ref().unwrap();
            let indices = source_renderer_paragraph_indices(document);
            if indices.len() != model.paragraph_count() || !source_text_stories(document).1 {
                failures.push(format!(
                    "{name}: diagnostic {} / model {}",
                    indices.len(),
                    model.paragraph_count()
                ));
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

