    #[test]
    fn shape_group_hyperlink_bounds_follow_group_and_outer_rotation() {
        let group = RunShapeGroup {
            child_offset_x: 100.0,
            child_offset_y: 200.0,
            child_extent_width: 1000.0,
            child_extent_height: 500.0,
            children: vec![RunGroupShape {
                x: 200.0,
                y: 250.0,
                width: 400.0,
                height: 100.0,
                ..RunGroupShape::default()
            }],
            ..RunShapeGroup::default()
        };
        let mut draw_spec = ImageDrawSpec {
            x: 10.0,
            y: 20.0,
            width: 200.0,
            height: 100.0,
            rotation_deg: 0.0,
            flip_horizontal: false,
            flip_vertical: false,
            crop: None,
            paragraph_index: 0,
            run_index: 0,
        };

        let bounds =
            <CanvasRenderer>::shape_group_child_bounds(&group, &group.children[0], draw_spec)
                .expect("child bounds");
        assert_eq!(bounds, (30.0, 30.0, 80.0, 20.0));

        draw_spec.rotation_deg = 90.0;
        let rotated =
            <CanvasRenderer>::shape_group_child_bounds(&group, &group.children[0], draw_spec)
                .expect("rotated child bounds");
        assert!((rotated.0 - 130.0).abs() < 0.000_001);
        assert!((rotated.1 + 10.0).abs() < 0.000_001);
        assert!((rotated.2 - 20.0).abs() < 0.000_001);
        assert!((rotated.3 - 80.0).abs() < 0.000_001);
    }

