    pub fn sample_line() -> SelectionLineLayout {
        let glyphs: Vec<GlyphBox> = (0..5)
            .map(|i| GlyphBox {
                start: i,
                end: i + 1,
                x: i as f64 * 10.0,
                width: 10.0,
            })
            .collect();
        let fragment = SelectionFragmentLayout {
            baseline_shift_px: 0.0,
            start: 0,
            end: 5,
            x: 10.0,
            width: 50.0,
            glyphs: glyphs.into(),
        };

        SelectionLineLayout {
            top: 0.0,
            absolute_top: 0.0,
            height: 12.0,
            baseline: 12.0,
            start_x: 10.0,
            cursor_end_x: 60.0,
            allowed_trailing_overflow_width: 0.0,
            content_top: 0.0,
            absolute_content_top: 0.0,
            content_height: 12.0,
            fragments: vec![fragment].into(),
            break_range: None,
            tab_leaders: Rc::from([]),
            tab_stops: Rc::from([]),
            column_index: 0,
            vertical: false,
            vertical_reversed: false,
        }
    }

