    #[test]
    fn determine_prefix_replay_until_is_disabled_when_render_cache_ineligible_options_enabled() {
        let mut renderer = test_renderer();
        let options = crate::Options {
            render_comments: true,
            ..Default::default()
        };
        // Keep last_options identical so the "options changed" guard would not trigger.
        renderer.last_options = Some(options.clone());

        renderer.incremental_layout_enabled = true;
        renderer.forced_dirty_from = Some(2);
        // Comment decoration only gates the render-cache fast-paths when the
        // document actually carries comments.
        renderer.document_has_comments = true;

        let doc = doc_with_paragraph_texts(&["a", "b", "c"]);
        let dirty = renderer.determine_prefix_replay_until(&doc, &options);
        // Prefix replay (dirty detection) can still be enabled, but unchecked cache replay is gated
        // separately by `can_use_unchecked_cache_replay`.
        assert_eq!(dirty, Some(2));
        assert!(!renderer.can_use_unchecked_cache_replay(&options));
    }

