    #[test]
    fn paragraph_content_hash_changes_when_character_indent_changes() {
        let renderer = test_renderer();
        let mut doc = doc_with_paragraph_texts(&["hello"]);
        let body = doc.body.as_mut().expect("document body");
        let paragraph = body.elements[0].as_paragraph_mut().expect("paragraph");

        let hash_without_indent = renderer.compute_paragraph_content_hash(paragraph);

        paragraph
            .properties
            .get_or_insert_with(Default::default)
            .indent = Some(Indent {
            left_chars: Some(100),
            ..Indent::default()
        });
        let hash_with_one_char = renderer.compute_paragraph_content_hash(paragraph);

        paragraph
            .properties
            .get_or_insert_with(Default::default)
            .indent = Some(Indent {
            left_chars: Some(200),
            ..Indent::default()
        });
        let hash_with_two_chars = renderer.compute_paragraph_content_hash(paragraph);

        assert_ne!(hash_without_indent, hash_with_one_char);
        assert_ne!(hash_with_one_char, hash_with_two_chars);
    }

    #[test]
    fn temporary_note_paragraphs_do_not_reuse_or_populate_address_hash_memo() {
        for measuring in [false, true] {
            let mut renderer = test_renderer();
            let mut paragraph = band_test_paragraph(vec![band_plain_run()]);
            let body_hash = renderer.paragraph_content_hash_cached(&paragraph);
            let body_memo = renderer.paragraph_content_hash_cache.borrow().clone();
            renderer.rendering_note_story = !measuring;
            renderer.measuring_notes = measuring;
            paragraph.runs[0].text = "temporary note content".into();
            let expected = renderer.compute_paragraph_content_hash(&paragraph);
            assert_ne!(expected, body_hash);
            assert_eq!(renderer.paragraph_content_hash_cached(&paragraph), expected);
            let other = band_test_paragraph(vec![band_plain_run()]);
            assert_eq!(
                renderer.paragraph_content_hash_cached(&other),
                renderer.compute_paragraph_content_hash(&other)
            );
            assert_eq!(*renderer.paragraph_content_hash_cache.borrow(), body_memo);
            renderer.rendering_note_story = false;
            renderer.measuring_notes = false;
            assert_eq!(
                renderer.paragraph_content_hash_cached(&paragraph),
                body_hash
            );
        }
    }

