    #[test]
    fn wrap_cache_returns_fresh_segment_properties_on_color_change() {
        // End-to-end assertion for the middle-paragraph scenario: given identical
        // text and run boundaries, a color change must produce a different cache
        // key so the next lookup misses and the fresh WrappedLine — carrying the
        // new color in its segments — gets inserted and returned by the cache.
        let text = "Hello world";
        let black = Some(RunProperties {
            color: Some("#000000".into()),
            ..RunProperties::default()
        });
        let red = Some(RunProperties {
            color: Some("#ff0000".into()),
            ..RunProperties::default()
        });

        let black_runs = [RunStyle {
            start: 0,
            end: text.len(),
            properties: black.clone().map(Rc::new),
            revision: None,
            hyperlink: None,
            inline_object: None,
        }];
        let red_runs = [RunStyle {
            start: 0,
            end: text.len(),
            properties: red.clone().map(Rc::new),
            revision: None,
            hyperlink: None,
            inline_object: None,
        }];

        let black_hash = <CanvasRenderer>::compute_wrap_content_hash(text, &black_runs);
        let red_hash = <CanvasRenderer>::compute_wrap_content_hash(text, &red_runs);
        assert_ne!(
            black_hash, red_hash,
            "color-only changes must produce distinct wrap cache keys"
        );

        let mut cache = ParagraphWrapCache::new(8);
        let black_key = ParagraphWrapCacheKey::new(black_hash, 0.0, 400.0, 0.0, 0.0, 0);
        cache.insert(
            black_key.clone(),
            vec![WrappedLine {
                segments: vec![TextSegment {
                    text: text.to_string(),
                    start: 0,
                    end: text.len(),
                    properties: black.clone().map(Rc::new),
                    revision: None,
                    hyperlink: None,
                    leading_width: 0.0,
                }],
                break_kind: LineBreakKind::ParagraphEnd,
                break_range: None,
                break_properties: None,
                leaders: Vec::new(),
                tab_stops: Vec::new(),
                clusters: Vec::new(),
            }]
            .into(),
        );

        let red_key = ParagraphWrapCacheKey::new(red_hash, 0.0, 400.0, 0.0, 0.0, 0);
        assert!(
            cache.get(&red_key).is_none(),
            "red lookup must miss while only the black entry is cached"
        );

        cache.insert(
            red_key.clone(),
            vec![WrappedLine {
                segments: vec![TextSegment {
                    text: text.to_string(),
                    start: 0,
                    end: text.len(),
                    properties: red.clone().map(Rc::new),
                    revision: None,
                    hyperlink: None,
                    leading_width: 0.0,
                }],
                break_kind: LineBreakKind::ParagraphEnd,
                break_range: None,
                break_properties: None,
                leaders: Vec::new(),
                tab_stops: Vec::new(),
                clusters: Vec::new(),
            }]
            .into(),
        );

        let refreshed = cache.get(&red_key).expect("red wrap cache hit");
        assert_eq!(
            refreshed[0].segments[0]
                .properties
                .as_ref()
                .and_then(|props| props.color.as_deref()),
            Some("#ff0000")
        );
    }

