    #[test]
    fn run_style_identity_cache_retains_and_distinguishes_rc_allocations() {
        let mut renderer = test_renderer();
        let first = Rc::new(RunProperties {
            bold: Some(true),
            ..RunProperties::default()
        });
        let equal_but_distinct = Rc::new((*first).clone());

        let first_style = renderer.resolve_applied_run_style_cached_rc(Some(&first));
        let first_again = renderer.resolve_applied_run_style_cached_rc(Some(&first));
        let equal_style = renderer.resolve_applied_run_style_cached_rc(Some(&equal_but_distinct));

        assert!(Rc::ptr_eq(&first_style, &first_again));
        assert!(Rc::ptr_eq(&first_style, &equal_style));
        assert_eq!(renderer.applied_run_style_identity_cache.borrow().len(), 2);
        assert!(Rc::strong_count(&first) >= 2);

        renderer.current_doc_grid_char_spacing_px = Some(2.0);
        let grid_style = renderer.resolve_applied_run_style_cached_rc(Some(&first));
        assert!(!Rc::ptr_eq(&first_style, &grid_style));
        // Grid pitch belongs to the shared paragraph advance, not tracking.
        assert_eq!(grid_style.letter_spacing_px, 0.0);
        assert_eq!(renderer.applied_run_style_identity_cache.borrow().len(), 3);
    }

    #[test]
    #[ignore]
    fn benchmark_paragraph_wrap_cache_lru_hot_path() {
        const CAPACITY: usize = 256;
        const UNIQUE_KEYS: usize = 2048;
        const ITERS: usize = 100_000;

        let keys: Vec<ParagraphWrapCacheKey> = (0..UNIQUE_KEYS)
            .map(|i| {
                ParagraphWrapCacheKey::new(
                    i as u64,
                    10.0 + (i % 7) as f64,
                    200.0 + (i % 19) as f64,
                    (i % 3) as f64,
                    (i % 5) as f64,
                    (i % 29) as u64,
                )
            })
            .collect();
        let mut access_pattern = Vec::with_capacity(ITERS);
        for i in 0..ITERS {
            access_pattern.push((i * 13) % UNIQUE_KEYS);
        }

        let mut legacy = LegacyParagraphWrapCache::new(CAPACITY);
        let legacy_start = Instant::now();
        for &index in &access_pattern {
            let key = &keys[index];
            if legacy.get(key).is_none() {
                legacy.insert(key.clone(), Vec::new());
            }
        }
        let legacy_elapsed = legacy_start.elapsed();

        let mut current = ParagraphWrapCache::new(CAPACITY);
        let current_start = Instant::now();
        for &index in &access_pattern {
            let key = &keys[index];
            if current.get(key).is_none() {
                current.insert(key.clone(), Vec::new().into());
            }
        }
        let current_elapsed = current_start.elapsed();

        black_box((&legacy, &current));
        println!(
            "paragraph wrap cache benchmark: legacy={}us current={}us iterations={} unique_keys={} capacity={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
            UNIQUE_KEYS,
            CAPACITY,
        );
    }

