    #[test]
    #[ignore]
    fn benchmark_font_switch_tracking_hot_path() {
        fn sample_descriptors() -> Vec<Rc<str>> {
            (0..128)
                .map(|i| {
                    if i % 9 == 0 {
                        Rc::from("12pt East")
                    } else if i % 5 == 0 {
                        Rc::from("12pt Latin Bold")
                    } else {
                        Rc::from("12pt Latin")
                    }
                })
                .collect()
        }

        fn legacy_switch(descriptors: &[Rc<str>]) -> usize {
            let mut total = 0usize;
            for descriptor in descriptors {
                let current = Some(descriptor.to_string());
                total += current.as_deref().map_or(0, str::len);
            }
            black_box(total)
        }

        fn current_switch(descriptors: &[Rc<str>]) -> usize {
            let mut current: Option<Rc<str>> = None;
            let mut total = 0usize;
            for descriptor in descriptors {
                if !current.as_ref().is_some_and(|active| {
                    Rc::ptr_eq(active, descriptor) || active.as_ref() == descriptor.as_ref()
                }) {
                    current = Some(descriptor.clone());
                }
                total += current.as_ref().map_or(0, |active| active.len());
            }
            black_box(total)
        }

        const ITERS: usize = 100_000;
        let descriptors = sample_descriptors();

        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            black_box(legacy_switch(&descriptors));
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            black_box(current_switch(&descriptors));
        }
        let current_elapsed = current_start.elapsed();

        println!(
            "font switch tracking benchmark: legacy={}us current={}us iterations={} descriptors={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
            descriptors.len(),
        );
    }

    #[test]
    #[ignore]
    fn benchmark_cached_draw_font_state_reuse_hot_path() {
        fn sample_command_sets() -> Vec<Rc<[DrawCommand]>> {
            let style = CmdTextStyle::default();
            (0..64)
                .map(|batch| {
                    let fonts = if batch % 11 == 0 {
                        vec![Rc::from("12pt East"), Rc::from("12pt Latin")]
                    } else {
                        vec![Rc::from("12pt Latin"), Rc::from("12pt East")]
                    };
                    let mut text = String::new();
                    let glyphs = (0..32)
                        .map(|i| {
                            let text_start = text.len() as u32;
                            text.push_str(if i % 9 == 0 { "漢" } else { "a" });
                            GlyphRunStep {
                                text_start,
                                text_end: text.len() as u32,
                                font_index: if i % 9 == 0 { 1 } else { 0 },
                                x_offset: i as f64 * 8.0,
                            }
                        })
                        .collect();
                    Rc::from([DrawCommand::TextRun {
                        text: Rc::from(text),
                        x: 10.0,
                        y: 20.0 + batch as f64,
                        style: style.clone(),
                        fonts,
                        glyphs,
                    }])
                })
                .collect()
        }

        fn count_font_switches(
            command_sets: &[Rc<[DrawCommand]>],
            reset_between_sets: bool,
        ) -> usize {
            let mut current_font: Option<&str> = None;
            let mut switches = 0usize;
            for commands in command_sets {
                if reset_between_sets {
                    current_font = None;
                }
                for command in commands.iter() {
                    if let DrawCommand::TextRun { fonts, glyphs, .. } = command {
                        for glyph in glyphs {
                            let Some(font) = fonts.get(glyph.font_index as usize) else {
                                continue;
                            };
                            if current_font != Some(&**font) {
                                current_font = Some(&**font);
                                switches += 1;
                            }
                        }
                    }
                }
            }
            black_box(switches)
        }

        const ITERS: usize = 100_000;
        let command_sets = sample_command_sets();

        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            black_box(count_font_switches(&command_sets, true));
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            black_box(count_font_switches(&command_sets, false));
        }
        let current_elapsed = current_start.elapsed();

        println!(
            "cached draw font state reuse benchmark: legacy={}us current={}us iterations={} command_sets={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
            command_sets.len(),
        );
    }

    #[test]
    #[ignore]
    fn benchmark_text_segment_iteration_hot_path() {
        fn sample_segments() -> Vec<TextSegment> {
            [
                "Alpha", "Beta", "", "Gamma", "Delta", "Epsilon", "", "Zeta", "Eta", "Theta",
                "Iota", "Kappa",
            ]
            .into_iter()
            .enumerate()
            .map(|(i, text)| TextSegment {
                text: text.to_string(),
                start: i * 10,
                end: i * 10 + text.len(),
                properties: None,
                revision: None,
                hyperlink: None,
                leading_width: (i % 3) as f64,
            })
            .collect()
        }

        fn legacy_iterate(segments: Vec<TextSegment>) -> usize {
            let line_segments: Vec<TextSegment> = segments
                .into_iter()
                .filter(|segment| !segment.text.is_empty())
                .collect();
            let mut total = 0;
            for segment_index in 0..line_segments.len() {
                let segment = line_segments[segment_index].clone();
                let next_grapheme_after_segment = line_segments
                    .iter()
                    .skip(segment_index + 1)
                    .find_map(|next| <CanvasRenderer>::first_grapheme(next.text.as_str()));
                total += segment.text.len() + next_grapheme_after_segment.map_or(0, str::len);
                black_box((segment.start, next_grapheme_after_segment));
            }
            total
        }

        fn current_iterate(segments: Vec<TextSegment>) -> usize {
            let mut line_segments = segments
                .into_iter()
                .filter(|segment| !segment.text.is_empty())
                .peekable();
            let mut total = 0;
            while let Some(segment) = line_segments.next() {
                let next_grapheme_after_segment = line_segments
                    .peek()
                    .and_then(|next| <CanvasRenderer>::first_grapheme(next.text.as_str()));
                total += segment.text.len() + next_grapheme_after_segment.map_or(0, str::len);
                black_box((segment.start, next_grapheme_after_segment));
            }
            total
        }

        const ITERS: usize = 200_000;
        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            black_box(legacy_iterate(sample_segments()));
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            black_box(current_iterate(sample_segments()));
        }
        let current_elapsed = current_start.elapsed();

        println!(
            "text segment iteration benchmark: legacy={}us current={}us iterations={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
        );
    }

    #[test]
    fn push_text_commands_for_plan_deduplicates_fonts_by_value() {
        let renderer = test_renderer();
        let mut style = renderer.cmd_text_style(None, &test_applied_style(1.0));
        let latin_shared: Rc<str> = Rc::from("12pt Latin");
        let latin_equal_distinct: Rc<str> = Rc::from("12pt Latin");
        let east: Rc<str> = Rc::from("12pt East");
        style.font_descriptor_latin_ascii = latin_shared;
        style.font_descriptor_latin_hansi = latin_equal_distinct;
        style.font_descriptor_east_asia = east;
        let text = "ab漢";
        let steps = vec![
            PlannedGlyphLayoutStep {
                text_start: 0,
                text_end: 1,
                font_slot: ResolvedFontSlot::LatinAscii,
                x_offset: 0.0,
            },
            PlannedGlyphLayoutStep {
                text_start: 1,
                text_end: 2,
                font_slot: ResolvedFontSlot::LatinHansi,
                x_offset: 8.0,
            },
            PlannedGlyphLayoutStep {
                text_start: 2,
                text_end: 5,
                font_slot: ResolvedFontSlot::EastAsia,
                x_offset: 16.0,
            },
        ];

        let mut buf = Vec::new();
        renderer.push_text_commands_for_plan(&mut buf, 10.0, 20.0, &style, text, &steps);

        let [DrawCommand::TextRun {
            text,
            fonts,
            glyphs,
            ..
        }] = buf.as_slice()
        else {
            panic!("expected a single text run command");
        };
        assert_eq!(text.as_ref(), "ab漢");
        assert_eq!(fonts, &vec![Rc::from("12pt Latin"), Rc::from("12pt East")]);
        assert_eq!(glyphs.len(), 3);
        assert_eq!(glyphs[0].text(text), Some("a"));
        assert_eq!(glyphs[1].text(text), Some("b"));
        assert_eq!(glyphs[2].text(text), Some("漢"));
        assert_eq!(glyphs[0].font_index, 0);
        assert_eq!(glyphs[1].font_index, 0);
        assert_eq!(glyphs[2].font_index, 1);
    }

    #[test]
    fn spelling_waves_use_the_recording_painter_and_are_suppressed_for_export() {
        use jade_painter::recording::Op;
        let (mut renderer, painter) = recording_renderer();
        let body = Body {
            elements: vec![BodyElement::from_paragraph(note_test_paragraph(
                "😀 helllo",
                None,
            ))],
        };
        renderer.spelling_cache.borrow_mut().configure(true, 1);
        renderer
            .render_header_footer_body_at(&body, 20.0, 100, true, None)
            .unwrap();
        let requests = renderer.spelling_cache.borrow_mut().take_pending();
        let request = requests
            .iter()
            .find(|request| request.text.contains("helllo"))
            .unwrap();
        renderer
            .spelling_cache
            .borrow_mut()
            .apply(1, &request.key, &[(5, 11)]);
        renderer.clear_paragraph_render_cache();
        painter.clear();
        renderer
            .render_header_footer_body_at(&body, 20.0, 100, true, None)
            .unwrap();
        assert!(painter
            .ops()
            .contains(&Op::SetStrokeStyle("#e53935".into())));
        assert!(painter.count(|op| matches!(op, Op::Stroke)) > 0);
        renderer.set_spelling_export_mode(true);
        painter.clear();
        renderer
            .render_header_footer_body_at(&body, 20.0, 100, true, None)
            .unwrap();
        assert!(!painter
            .ops()
            .contains(&Op::SetStrokeStyle("#e53935".into())));
        assert!(painter.count(|op| matches!(op, Op::FillText(..))) > 0);
    }

