    #[test]
    #[ignore]
    fn benchmark_lazy_selection_debug_text() {
        const ITERS: usize = 1_000_000;
        let text = "契約条項の本文です。This is a representative paragraph. ".repeat(8);

        let copied_start = Instant::now();
        for _ in 0..ITERS {
            let mut debug_text = String::new();
            debug_text.push_str(black_box(&text));
            black_box(debug_text);
        }
        let copied_elapsed = copied_start.elapsed();

        let lazy_start = Instant::now();
        for _ in 0..ITERS {
            let debug_text: Option<String> = None;
            black_box(debug_text.as_deref().unwrap_or(black_box(&text)));
        }
        let lazy_elapsed = lazy_start.elapsed();

        println!(
            "lazy selection debug text benchmark: copied={}us lazy={}us iterations={} bytes={}",
            copied_elapsed.as_micros(),
            lazy_elapsed.as_micros(),
            ITERS,
            text.len(),
        );
    }

    #[test]
    #[ignore]
    fn benchmark_font_descriptor_resolution_hot_path() {
        fn sample_steps(resolved: &ResolvedRunStyle) -> Vec<(&str, ScriptCategory, &str, u64)> {
            (0..128)
                .map(|i| {
                    if i % 11 == 0 {
                        (
                            "漢",
                            ScriptCategory::EastAsia,
                            resolved.font_descriptor_east_asia.as_ref(),
                            resolved.font_descriptor_east_asia_hash,
                        )
                    } else if i % 7 == 0 {
                        (
                            "é",
                            ScriptCategory::Latin,
                            resolved.font_descriptor_latin_hansi.as_ref(),
                            resolved.font_descriptor_latin_hansi_hash,
                        )
                    } else {
                        (
                            "a",
                            ScriptCategory::Latin,
                            resolved.font_descriptor_latin_ascii.as_ref(),
                            resolved.font_descriptor_latin_ascii_hash,
                        )
                    }
                })
                .collect()
        }

        fn legacy_resolve(
            resolved: &ResolvedRunStyle,
            steps: &[(&str, ScriptCategory, &str, u64)],
        ) -> Vec<Rc<str>> {
            let latin_ascii_descriptor: Rc<str> = Rc::clone(&resolved.font_descriptor_latin_ascii);
            let latin_hansi_descriptor: Rc<str> = Rc::clone(&resolved.font_descriptor_latin_hansi);
            let east_asia_descriptor: Rc<str> = Rc::clone(&resolved.font_descriptor_east_asia);
            let complex_descriptor: Rc<str> = Rc::clone(&resolved.font_descriptor_complex);
            let mut glyph_descriptors = Vec::with_capacity(steps.len());
            for (_, _, font_descriptor, font_descriptor_hash) in steps {
                let font_descriptor =
                    if *font_descriptor_hash == resolved.font_descriptor_latin_ascii_hash {
                        latin_ascii_descriptor.clone()
                    } else if *font_descriptor_hash == resolved.font_descriptor_latin_hansi_hash {
                        latin_hansi_descriptor.clone()
                    } else if *font_descriptor_hash == resolved.font_descriptor_east_asia_hash {
                        east_asia_descriptor.clone()
                    } else if *font_descriptor_hash == resolved.font_descriptor_complex_hash {
                        complex_descriptor.clone()
                    } else {
                        Rc::from(*font_descriptor)
                    };
                glyph_descriptors.push(font_descriptor.clone());
            }
            glyph_descriptors
        }

        fn current_resolve(
            resolved: &ResolvedRunStyle,
            steps: &[(&str, ScriptCategory, &str, u64)],
        ) -> Vec<Rc<str>> {
            let mut glyph_descriptors = Vec::with_capacity(steps.len());
            for (grapheme, script, _, _) in steps {
                glyph_descriptors.push(resolved.descriptor_for_grapheme_rc(grapheme, *script));
            }
            glyph_descriptors
        }

        fn slot_resolve(
            resolved: &ResolvedRunStyle,
            steps: &[(&str, ScriptCategory, &str, u64)],
        ) -> Vec<ResolvedFontSlot> {
            let mut glyph_slots = Vec::with_capacity(steps.len());
            for (grapheme, script, _, _) in steps {
                glyph_slots.push(resolved.font_slot_for_grapheme(grapheme, *script));
            }
            glyph_slots
        }

        fn copy_stored_slots(slots: &[ResolvedFontSlot]) -> Vec<ResolvedFontSlot> {
            slots.to_vec()
        }

        const ITERS: usize = 100_000;
        let style = test_applied_style(1.0);
        let resolved = style.resolved.as_ref();
        let steps = sample_steps(resolved);
        let stored_slots = steps
            .iter()
            .map(|(grapheme, script, _, _)| resolved.font_slot_for_grapheme(grapheme, *script))
            .collect::<Vec<_>>();

        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            black_box(legacy_resolve(resolved, &steps));
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            black_box(current_resolve(resolved, &steps));
        }
        let current_elapsed = current_start.elapsed();

        let slot_start = Instant::now();
        for _ in 0..ITERS {
            black_box(slot_resolve(resolved, &steps));
        }
        let slot_elapsed = slot_start.elapsed();

        let stored_slot_start = Instant::now();
        for _ in 0..ITERS {
            black_box(copy_stored_slots(&stored_slots));
        }
        let stored_slot_elapsed = stored_slot_start.elapsed();

        println!(
            "font descriptor resolution benchmark: legacy={}us current={}us slots={}us stored_slots={}us iterations={} glyphs={} rc_step_bytes={} slot_step_bytes={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            slot_elapsed.as_micros(),
            stored_slot_elapsed.as_micros(),
            ITERS,
            steps.len(),
            std::mem::size_of::<(u32, u32, Rc<str>, f64)>(),
            std::mem::size_of::<PlannedGlyphLayoutStep>(),
        );
    }

    #[test]
    #[ignore]
    fn benchmark_text_run_command_packing_hot_path() {
        fn sample_steps() -> (String, Vec<PlannedGlyphLayoutStep>) {
            let mut text = String::new();
            let steps = (0..64)
                .map(|i| {
                    let grapheme = if i % 7 == 0 { "漢" } else { "a" };
                    let text_start = text.len() as u32;
                    text.push_str(grapheme);
                    PlannedGlyphLayoutStep {
                        text_start,
                        text_end: text.len() as u32,
                        font_slot: if i % 7 == 0 {
                            ResolvedFontSlot::EastAsia
                        } else {
                            ResolvedFontSlot::LatinAscii
                        },
                        x_offset: i as f64 * 8.0,
                    }
                })
                .collect();
            (text, steps)
        }

        fn legacy_pack(
            x: f64,
            y: f64,
            text_style: &CmdTextStyle,
            segment_text: &str,
            glyph_steps: &[PlannedGlyphLayoutStep],
        ) -> Vec<DrawCommand> {
            let mut buf = Vec::with_capacity(glyph_steps.len());
            for step in glyph_steps {
                buf.push(DrawCommand::Text {
                    text: Rc::from(step.text(segment_text)),
                    x: x + step.x_offset,
                    y,
                    style: text_style.clone(),
                });
            }
            buf
        }

        const ITERS: usize = 100_000;
        let renderer = test_renderer();
        let style = renderer.cmd_text_style(None, &test_applied_style(1.0));
        let (text, steps) = sample_steps();

        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            black_box(legacy_pack(10.0, 20.0, &style, &text, &steps));
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            let mut buf = Vec::new();
            renderer.push_text_commands_for_plan(&mut buf, 10.0, 20.0, &style, &text, &steps);
            black_box(buf);
        }
        let current_elapsed = current_start.elapsed();

        println!(
            "text run command packing benchmark: legacy={}us current={}us iterations={} glyphs={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
            steps.len(),
        );
    }

    #[test]
    #[ignore]
    fn benchmark_cluster_font_metrics_locality_hot_path() {
        fn sample_descriptors() -> Vec<Rc<str>> {
            (0..256)
                .map(|i| {
                    if i % 19 == 0 {
                        Rc::from("12pt East")
                    } else if i % 7 == 0 {
                        Rc::from("12pt Latin Bold")
                    } else {
                        Rc::from("12pt Latin")
                    }
                })
                .collect()
        }

        fn legacy_accumulate(
            descriptors: &[Rc<str>],
            metrics: &FxHashMap<&'static str, (f64, f64)>,
        ) -> usize {
            let mut total = 0usize;
            for descriptor in descriptors {
                let metric = metrics
                    .get(descriptor.as_ref())
                    .copied()
                    .unwrap_or((9.0, 3.0));
                total += descriptor.len() + metric.0 as usize + metric.1 as usize;
            }
            black_box(total)
        }

        fn current_accumulate(
            descriptors: &[Rc<str>],
            metrics: &FxHashMap<&'static str, (f64, f64)>,
        ) -> usize {
            let mut total = 0usize;
            let mut recent: Option<(Rc<str>, (f64, f64))> = None;
            for descriptor in descriptors {
                let metric = if let Some((active, values)) = recent.as_ref() {
                    if Rc::ptr_eq(active, descriptor) || active.as_ref() == descriptor.as_ref() {
                        *values
                    } else {
                        let values = metrics
                            .get(descriptor.as_ref())
                            .copied()
                            .unwrap_or((9.0, 3.0));
                        recent = Some((descriptor.clone(), values));
                        values
                    }
                } else {
                    let values = metrics
                        .get(descriptor.as_ref())
                        .copied()
                        .unwrap_or((9.0, 3.0));
                    recent = Some((descriptor.clone(), values));
                    values
                };
                total += descriptor.len() + metric.0 as usize + metric.1 as usize;
            }
            black_box(total)
        }

        const ITERS: usize = 100_000;
        let descriptors = sample_descriptors();
        let metrics = FxHashMap::from_iter([
            ("12pt Latin", (10.0, 4.0)),
            ("12pt Latin Bold", (10.5, 4.5)),
            ("12pt East", (11.0, 5.0)),
        ]);

        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            black_box(legacy_accumulate(&descriptors, &metrics));
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            black_box(current_accumulate(&descriptors, &metrics));
        }
        let current_elapsed = current_start.elapsed();

        println!(
            "cluster font metrics locality benchmark: legacy={}us current={}us iterations={} descriptors={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
            descriptors.len(),
        );
    }

    #[test]
    #[ignore]
    fn benchmark_cached_hyperlink_region_replay_hot_path() {
        fn sample_regions() -> Vec<HyperlinkRegion> {
            (0..32)
                .map(|i| HyperlinkRegion {
                    page: 1,
                    paragraph: i,
                    start: i * 2,
                    end: i * 2 + 2,
                    x: i as f64 * 12.0,
                    y: i as f64 * 3.0,
                    width: 48.0,
                    height: 14.0,
                    target: Some(format!("https://example.com/{i}")),
                    target_mode: Some("External".to_string()),
                    anchor: Some(format!("section-{i}")),
                    tooltip: Some(format!("tooltip-{i}")),
                    target_frame: Some(format!("report-{i}")),
                })
                .collect()
        }

        fn shared_regions(regions: &[HyperlinkRegion]) -> Vec<CachedHyperlinkRegion> {
            regions
                .iter()
                .map(CachedHyperlinkRegion::from_region)
                .collect()
        }

        fn legacy_append(regions: &[HyperlinkRegion], offset: f64, out: &mut Vec<HyperlinkRegion>) {
            out.reserve(regions.len());
            for region in regions {
                out.push(HyperlinkRegion {
                    page: region.page,
                    paragraph: region.paragraph,
                    start: region.start,
                    end: region.end,
                    x: region.x,
                    y: region.y + offset,
                    width: region.width,
                    height: region.height,
                    target: region.target.clone(),
                    target_mode: region.target_mode.clone(),
                    anchor: region.anchor.clone(),
                    tooltip: region.tooltip.clone(),
                    target_frame: region.target_frame.clone(),
                });
            }
        }

        const ITERS: usize = 100_000;
        let public_regions = sample_regions();
        let cached_regions = shared_regions(&public_regions);
        let offset = 24.0;

        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            let mut out = Vec::with_capacity(public_regions.len());
            legacy_append(&public_regions, offset, &mut out);
            black_box(out);
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            let mut out = Vec::with_capacity(cached_regions.len());
            for region in &cached_regions {
                out.push(region.to_public_with_y_offset(offset));
            }
            black_box(out);
        }
        let current_elapsed = current_start.elapsed();

        println!(
            "cached hyperlink region replay benchmark: legacy={}us current={}us iterations={} regions={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
            cached_regions.len(),
        );
    }

    #[test]
    #[ignore]
    fn benchmark_deferred_cached_draw_queue_hot_path() {
        fn sample_commands() -> Rc<[DrawCommand]> {
            vec![
                DrawCommand::Text {
                    text: Rc::from("sample"),
                    x: 10.0,
                    y: 20.0,
                    style: CmdTextStyle::default(),
                },
                DrawCommand::Underline {
                    x: 10.0,
                    y: 20.0,
                    width: 48.0,
                    font_size_pt: 12.0,
                    color: Rc::from("#000"),
                    kind: None,
                },
            ]
            .into()
        }

        fn legacy_defer(
            deferred: &mut Vec<DeferredCachedDrawEntry>,
            commands: Rc<[DrawCommand]>,
            y_offset: f64,
        ) {
            deferred.push(DeferredCachedDrawEntry {
                command_sets: vec![commands],
                y_offset,
            });
        }

        const ITERS: usize = 100_000;
        let command_sets: Vec<Rc<[DrawCommand]>> = (0..32).map(|_| sample_commands()).collect();

        let legacy_start = Instant::now();
        for _ in 0..ITERS {
            let mut deferred = Vec::new();
            for commands in &command_sets {
                legacy_defer(&mut deferred, commands.clone(), 0.0);
            }
            black_box(deferred);
        }
        let legacy_elapsed = legacy_start.elapsed();

        let current_start = Instant::now();
        for _ in 0..ITERS {
            let mut deferred = Vec::new();
            for commands in &command_sets {
                <CanvasRenderer>::defer_cached_draw_commands(&mut deferred, commands.clone(), 0.0);
            }
            black_box(deferred);
        }
        let current_elapsed = current_start.elapsed();

        println!(
            "deferred cached draw queue benchmark: legacy={}us current={}us iterations={} command_sets={}",
            legacy_elapsed.as_micros(),
            current_elapsed.as_micros(),
            ITERS,
            command_sets.len(),
        );
    }

    #[test]
    fn unchecked_cache_replay_is_disabled_when_notes_enabled() {
        let mut renderer = test_renderer();
        renderer.document_has_notes = true;
        let mut options = crate::Options {
            render_comments: false,
            render_changes: false,
            show_formatting_marks: false,
            render_footnotes: true,
            render_endnotes: false,
            ..Default::default()
        };
        assert!(!renderer.can_use_unchecked_cache_replay(&options));

        options.render_footnotes = false;
        options.render_endnotes = true;
        assert!(!renderer.can_use_unchecked_cache_replay(&options));
    }

    #[test]
    fn comment_free_document_keeps_cache_fast_paths_with_render_comments() {
        let mut renderer = test_renderer();
        renderer.current_text_direction = None;
        renderer.document_has_notes = false;
        renderer.document_has_comments = false;
        let mut options = options_for_seek_tests();
        options.render_comments = true;
        // Comment decoration is enabled by default, but a document without any
        // comments must keep the unchecked-replay and seek fast-paths.
        assert!(renderer.can_use_unchecked_cache_replay(&options));
        assert!(renderer.is_seek_compatible_options(&options));
    }

    #[test]
    fn document_with_comments_disables_cache_fast_paths_when_render_comments() {
        let mut renderer = test_renderer();
        renderer.current_text_direction = None;
        renderer.document_has_notes = false;
        renderer.document_has_comments = true;
        let mut options = options_for_seek_tests();
        options.render_comments = true;
        assert!(!renderer.can_use_unchecked_cache_replay(&options));
        assert!(!renderer.is_seek_compatible_options(&options));
    }

