    #[test]
    fn note_paragraph_leading_space_uses_shared_half_em_without_changing_body_spaces() {
        let _platform = RestoreWordPlatform::mac();
        let mut document = note_test_document();
        let note = document.footnotes.get_mut("2").unwrap();
        note.body = [" Alpha Beta", " Gamma Delta", " Epsilon Zeta"]
            .into_iter()
            .map(|text| BodyElement::from_paragraph(note_test_paragraph(text, None)))
            .collect();
        if let BodyElement::Paragraph(p) = &mut note.body[2] {
            p.runs.insert(0, note_test_run("", None));
        }
        if let BodyElement::Paragraph(p) = &mut document.body.as_mut().unwrap().elements[0] {
            p.runs[0].text = " Control body".into();
        }
        for element in document
            .body
            .as_mut()
            .unwrap()
            .elements
            .iter_mut()
            .chain(note.body.iter_mut())
        {
            if let BodyElement::Paragraph(p) = element {
                for run in &mut p.runs {
                    run.properties = Some(RunProperties {
                        font_size: Some(10.5),
                        font_family: Some(Rc::from("Yu Mincho")),
                        ..RunProperties::default()
                    });
                }
            }
        }
        let original = serde_json::to_value(&document.footnotes).unwrap();
        let (mut renderer, _) = recording_renderer();
        renderer.render(&document, &Options::default()).unwrap();
        let snapshot = renderer.capture_full_layout_debug().unwrap();
        let space_widths = |line: &LayoutLineDebug| {
            line.fragments
                .iter()
                .flat_map(|fragment| fragment.glyphs.iter())
                .filter(|glyph| glyph.text == " ")
                .map(|glyph| glyph.width)
                .collect::<Vec<_>>()
        };
        for text in [" Gamma Delta", " Epsilon Zeta"] {
            let line = &snapshot
                .auxiliary_lines
                .iter()
                .find(|entry| entry.story == "footnote" && entry.line.text == text)
                .expect("subsequent note paragraph")
                .line;
            let widths = space_widths(line);
            assert!((widths[0] - 7.0).abs() < 1e-9, "{text}: {widths:?}");
            assert!((widths[1] - 3.63671875).abs() < 1e-9);
        }
        let control = snapshot
            .body_lines
            .iter()
            .find(|line| line.text == " Control body")
            .unwrap();
        assert!(space_widths(control)
            .iter()
            .all(|width| (*width - 3.63671875).abs() < 1e-9));
        assert_eq!(serde_json::to_value(&document.footnotes).unwrap(), original);
        assert_eq!(renderer.automatic_note_separator_offset, None);
    }

    #[test]
    fn inline_note_separator_survives_floating_box_and_table_registration() {
        let _platform = RestoreWordPlatform::mac();
        let bytes = std::fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../public/fixtures/footnote-table-textbox-order.docx"
        ))
        .unwrap();
        let model = futures::executor::block_on(crate::word_document::WordDocument::load(
            &bytes,
            &Options::default(),
        ))
        .unwrap();
        let mut document = (**model.document.as_ref().unwrap()).clone();
        let body = document.body.as_mut().unwrap();
        let table = body
            .elements
            .iter_mut()
            .find_map(|element| {
                if let BodyElement::Table(table) = element {
                    Some(table)
                } else {
                    None
                }
            })
            .unwrap();
        let paragraph = table.rows[0].cells[0].blocks[0].as_paragraph_mut().unwrap();
        let mut trailing = paragraph.runs[0].clone();
        trailing.text = " Alpha Beta".into();
        trailing.footnote_reference_ids.clear();
        trailing.endnote_reference_ids.clear();
        paragraph.runs.push(trailing);
        let original = serde_json::to_value(&document).unwrap();
        let (mut renderer, _) = recording_renderer();
        renderer.render(&document, &Options::default()).unwrap();
        let snapshot = renderer.capture_full_layout_debug().unwrap();
        for prefix in ["Host5 after box6", "Cell A2 Alpha Beta"] {
            let line = snapshot
                .body_lines
                .iter()
                .find(|line| line.text == prefix)
                .unwrap();
            let widths: Vec<_> = line
                .fragments
                .iter()
                .flat_map(|f| &f.glyphs)
                .filter(|g| g.text == " ")
                .map(|g| g.width)
                .collect();
            let separator = if prefix.starts_with("Host") { 0 } else { 1 };
            assert!(
                (widths[separator] - 7.0).abs() < 1e-9,
                "{prefix}: {widths:?}"
            );
            assert!(
                widths
                    .iter()
                    .enumerate()
                    .filter(|(i, _)| *i != separator)
                    .all(|(_, width)| (*width - 3.63671875).abs() < 1e-9),
                "{prefix}: {widths:?}"
            );
        }
        assert_eq!(serde_json::to_value(&document).unwrap(), original);
    }

