    // Builds a valid column-0 page-top snapshot for a given page, matching the
    // test renderer's geometry so `window_seek_snapshot_is_valid` passes.
    fn page_top_snapshot(renderer: &CanvasRenderer, page: usize) -> PageStartSeekSnapshot {
        PageStartSeekSnapshot {
            paragraph_index: page * 10,
            body_element_index: page * 100,
            section_index: 0,
            page_number: page,
            column_index: 0,
            page_offset_y: 0.0,
            current_y: renderer.margin_top,
            last_line_baseline: renderer.margin_top,
            trailing_spacing_after: None,
            column_layout: renderer.column_layout.clone(),
            current_text_direction: None,
            current_doc_grid: None,
            current_doc_grid_char_spacing_px: None,
            numbering_counter: NumberingCounter::new(),
            footnote_counter: 0,
            endnote_counter: 0,
            margin_top: renderer.margin_top,
            page_height: renderer.page_height,
            page_width: renderer.page_width,
            spanning: false,
            table_counter: 0,
        }
    }

    #[test]
    fn try_prepare_visible_window_page_seek_prefers_exact_over_fallback() {
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        renderer.visible_page_range = Some(5..=6);
        // An exact snapshot for the first visible page AND an earlier one.
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(3, page_top_snapshot(&renderer, 3));
        let exact = page_top_snapshot(&renderer, 5);
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(5, exact.clone());
        let options = options_for_seek_tests();

        let seek = renderer
            .try_prepare_visible_window_page_seek(&options)
            .expect("exact window seek snapshot");
        assert_eq!(seek.page_number, 5, "must prefer the exact-page snapshot");
        assert_eq!(seek.paragraph_index, exact.paragraph_index);
        let (exact_hits, fallback_hits, misses) = renderer.window_seek_stats();
        assert_eq!((exact_hits, fallback_hits, misses), (1, 0, 0));
    }

    #[test]
    fn try_prepare_visible_window_page_seek_uses_default_on_spanning_fallback_not_exact_hit() {
        // A spanning snapshot (S6) keyed at the first visible page K but whose
        // resume anchor is on an EARLIER page P < K must never be returned via the
        // page-top exact-hit path: it resumes mid-page on page P, not at the top of
        // page K. It must be consumed through the spanning fallback, never counted
        // as a page-top exact hit.
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        renderer.visible_page_range = Some(5..=6);
        // Spanning snapshot keyed at page 5 (K) but page_number = 3 (P < K).
        let mut spanning = page_top_snapshot(&renderer, 3);
        spanning.spanning = true;
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(5, spanning);
        let options = options_for_seek_tests();

        assert!(renderer.span_seek_enabled());
        let seek = renderer
            .try_prepare_visible_window_page_seek(&options)
            .expect("default-on spanning fallback");
        assert_eq!(seek.page_number, 3);
        assert!(seek.spanning);
        let (exact_hits, fallback_hits, misses) = renderer.window_seek_stats();
        assert_eq!(
            (exact_hits, fallback_hits, misses),
            (0, 0, 0),
            "spanning fallback must not be classified as an exact page-top hit"
        );
        assert_eq!(renderer.span_seek_stats().1, 1);

        renderer.set_span_seek_enabled(false);
        assert!(renderer
            .try_prepare_visible_window_page_seek(&options)
            .is_none());
    }

