    #[test]
    fn try_prepare_visible_window_page_seek_falls_back_to_greatest_preceding_page() {
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        renderer.visible_page_range = Some(6..=7);
        // No snapshot for page 6 (mid-paragraph page break). Several preceding
        // page-top snapshots exist; the greatest preceding one (page 4) must win.
        for page in [2usize, 4, 3] {
            renderer
                .page_start_seek_cache_by_page
                .borrow_mut()
                .insert(page, page_top_snapshot(&renderer, page));
        }
        let options = options_for_seek_tests();

        let seek = renderer
            .try_prepare_visible_window_page_seek(&options)
            .expect("fallback window seek snapshot");
        assert_eq!(
            seek.page_number, 4,
            "fallback must pick the greatest page strictly before the visible start"
        );
        let (exact_hits, fallback_hits, misses) = renderer.window_seek_stats();
        assert_eq!((exact_hits, fallback_hits, misses), (0, 1, 0));
    }

    #[test]
    fn prepare_layout_extension_seek_resumes_from_greatest_page_top_at_or_before_first_unlaid_page()
    {
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        // Pages 1..=40 were laid out under limit 40; page 41 is where the next
        // chunk (limit 42) starts. Snapshots exist for pages 2, 30 and 41, plus a
        // later one (50, stale from a shrunk limit) that must not be chosen, and
        // a spanning one keyed at 41 that is not a page-top resume point.
        for page in [2usize, 30, 41, 50] {
            renderer
                .page_start_seek_cache_by_page
                .borrow_mut()
                .insert(page, page_top_snapshot(&renderer, page));
        }
        let mut spanning = page_top_snapshot(&renderer, 40);
        spanning.spanning = true;
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(41, spanning);
        // Re-insert the exact page-41 snapshot last so "latest wins" semantics
        // do not matter for this test: the map holds one entry per page, and we
        // want the exact one there.
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(41, page_top_snapshot(&renderer, 41));
        let options = options_for_seek_tests();

        assert!(renderer.prepare_layout_extension_seek(Some(40), 42, &options));
        let seek = renderer
            .forced_seek_snapshot
            .as_ref()
            .expect("extension seek seeds the forced snapshot");
        assert_eq!(seek.page_number, 41);
        assert!(!seek.spanning);
        assert!(!renderer.skip_layout_cache_update);
        assert_eq!(renderer.layout_extension_seek_stats(), (1, 0));
        assert_eq!(
            renderer.layout_extension_seek_frontier_stats(),
            (Some(41), Some(4100), 0, 0)
        );

        // Without a snapshot for page 41 the greatest earlier page-top wins.
        renderer.forced_seek_snapshot = None;
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .remove(&41);
        assert!(renderer.prepare_layout_extension_seek(Some(40), 42, &options));
        assert_eq!(
            renderer
                .forced_seek_snapshot
                .as_ref()
                .map(|s| s.page_number),
            Some(30)
        );
        assert_eq!(renderer.layout_extension_seek_stats(), (2, 0));
        assert_eq!(
            renderer.layout_extension_seek_frontier_stats(),
            (Some(30), Some(3000), 0, 0)
        );
    }

    #[test]
    fn prepare_layout_extension_seek_consumes_spanning_snapshot_when_it_resumes_nearer() {
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        assert!(renderer.span_seek_enabled());
        // Page-top snapshot far back (page 30) and a spanning snapshot keyed at
        // page 41 whose paragraph starts on page 40: the spanning one resumes
        // nearer to the first unlaid page and must win.
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(30, page_top_snapshot(&renderer, 30));
        let mut spanning = page_top_snapshot(&renderer, 40);
        spanning.spanning = true;
        spanning.current_y = renderer.margin_top + 200.0;
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(41, spanning);
        let options = options_for_seek_tests();

        assert!(renderer.prepare_layout_extension_seek(Some(40), 42, &options));
        let seek = renderer
            .forced_seek_snapshot
            .as_ref()
            .expect("spanning extension seek");
        assert_eq!(seek.page_number, 40);
        assert!(seek.spanning);
        let (_, consumed, _, _) = renderer.span_seek_stats();
        assert_eq!(consumed, 1);

        // With span seek disabled only the page-top snapshot remains.
        renderer.forced_seek_snapshot = None;
        renderer.set_span_seek_enabled(false);
        assert!(renderer.prepare_layout_extension_seek(Some(40), 42, &options));
        assert_eq!(
            renderer
                .forced_seek_snapshot
                .as_ref()
                .map(|s| s.page_number),
            Some(30)
        );
    }

    #[test]
    fn page_bitmap_rerenders_preserve_table_editing_metadata() {
        let mut renderer = CanvasRenderer::with_host(
            Box::new(NonCanvasHost {
                painter: jade_painter::recording::RecordingPainter::new(),
            }),
            false,
        )
        .expect("recording renderer");
        let mut page_break = band_test_paragraph(vec![band_plain_run()]);
        page_break.properties = Some(ParagraphProperties {
            page_break_before: Some(true),
            ..Default::default()
        });
        let document = Document {
            body: Some(Body {
                elements: vec![
                    band_table_with_cell_paragraphs(1),
                    BodyElement::from_paragraph(page_break.clone()),
                    band_table_with_cell_paragraphs(1),
                    BodyElement::from_paragraph(page_break),
                    band_table_with_cell_paragraphs(1),
                ],
            }),
            ..Default::default()
        };
        let options = Options::default();
        renderer.render(&document, &options).expect("full layout");
        assert_eq!(renderer.table_layouts.len(), 3);
        let metadata = |renderer: &CanvasRenderer<jade_painter::recording::RecordingPainter>| {
            serde_json::to_value((
                &renderer.table_layouts,
                &renderer.table_handles,
                &renderer.table_row_handles,
            ))
            .unwrap()
        };
        let before = metadata(&renderer);
        for page_index in [1, 0, 2] {
            renderer.set_layout_page_limit(Some(page_index + 1));
            renderer.set_visible_page_range(Some(page_index + 1..=page_index + 1));
            renderer.prepare_rerender_for_page(page_index);
            renderer.freeze_selection_for_pixel_rerender();
            if page_index > 0 {
                assert!(
                    renderer.forced_seek_snapshot.is_some(),
                    "must exercise seek"
                );
            }
            renderer.render(&document, &options).expect("page bitmap");
            assert_eq!(metadata(&renderer), before, "page {page_index}");
            for table_id in 0..3 {
                assert_eq!(renderer.table_order_for(table_id), Some(table_id));
                let cell = renderer
                    .cell_id_for_paragraph(table_id * 2)
                    .and_then(|id| renderer.cell_layout(id))
                    .expect("all table cells stay registered after bitmap refresh");
                assert_eq!(cell.table_id, table_id);
            }
        }
        renderer.set_layout_page_limit(Some(3));
        assert!(renderer.prepare_layout_extension_seek(Some(2), 3, &options));
        renderer
            .render(&document, &options)
            .expect("layout extension");
        assert_eq!(metadata(&renderer), before);
        for table_id in 0..3 {
            let cell = renderer
                .cell_id_for_paragraph(table_id * 2)
                .and_then(|id| renderer.cell_layout(id))
                .expect("skipped cells stay registered after layout extension");
            assert_eq!(cell.table_id, table_id);
            assert_eq!(renderer.table_order_for(cell.table_id), Some(table_id));
        }
    }

    #[test]
    fn prepare_layout_extension_seek_snapshots_carry_the_table_counter() {
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        let mut snapshot = page_top_snapshot(&renderer, 41);
        snapshot.table_counter = 3;
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(41, snapshot);
        let options = options_for_seek_tests();
        assert!(renderer.prepare_layout_extension_seek(Some(40), 42, &options));
        assert_eq!(
            renderer
                .forced_seek_snapshot
                .as_ref()
                .map(|s| s.table_counter),
            Some(3)
        );
        assert_eq!(renderer.forced_dirty_from, Some(410));
    }

    #[test]
    fn prepare_layout_extension_seek_falls_back_when_not_an_extension_or_no_valid_snapshot() {
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(5, page_top_snapshot(&renderer, 5));
        let options = options_for_seek_tests();

        // Unlimited previous layout, a shrink, and an unchanged limit are not
        // extensions.
        assert!(!renderer.prepare_layout_extension_seek(None, 8, &options));
        assert!(!renderer.prepare_layout_extension_seek(Some(10), 8, &options));
        assert!(!renderer.prepare_layout_extension_seek(Some(8), 8, &options));
        // Only a snapshot strictly after page 1 and at or before the first
        // unlaid page can be used: limit 3 → resume bound 4, snapshot at 5 is
        // too far.
        assert!(!renderer.prepare_layout_extension_seek(Some(3), 6, &options));
        assert!(renderer.forced_seek_snapshot.is_none());
        // A pending full repaint or an explicit seek disable also falls back.
        assert!(renderer.prepare_layout_extension_seek(Some(6), 8, &options));
        renderer.forced_seek_snapshot = None;
        renderer.disable_seek_replay_once = true;
        assert!(!renderer.prepare_layout_extension_seek(Some(6), 8, &options));
        renderer.disable_seek_replay_once = false;
        renderer.mark_full_repaint();
        assert!(!renderer.prepare_layout_extension_seek(Some(6), 8, &options));
        assert!(renderer.forced_seek_snapshot.is_none());
        let (hits, misses) = renderer.layout_extension_seek_stats();
        assert_eq!((hits, misses), (1, 6));

        // The escape hatch turns every extension into a from-start walk.
        renderer.clear_dirty_regions();
        assert!(renderer.prepare_layout_extension_seek(Some(6), 8, &options));
        renderer.forced_seek_snapshot = None;
        renderer.set_layout_extension_seek_enabled(false);
        assert!(!renderer.prepare_layout_extension_seek(Some(6), 8, &options));
        assert!(renderer.forced_seek_snapshot.is_none());
        assert_eq!(renderer.layout_extension_seek_last_miss(), "disabled");
    }

    #[test]
    fn try_prepare_visible_window_page_seek_skips_geometry_mismatched_preceding_snapshots() {
        let mut renderer = test_renderer();
        renderer.pageless_mode = false;
        renderer.visible_page_range = Some(6..=7);
        // Page 5 is the greatest preceding page but has a stale geometry
        // (different page_height) so it must be skipped; page 3 is valid and
        // must be chosen instead.
        let mut stale = page_top_snapshot(&renderer, 5);
        stale.page_height += 50.0;
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(5, stale);
        renderer
            .page_start_seek_cache_by_page
            .borrow_mut()
            .insert(3, page_top_snapshot(&renderer, 3));
        let options = options_for_seek_tests();

        let seek = renderer
            .try_prepare_visible_window_page_seek(&options)
            .expect("fallback skips the stale page-5 snapshot");
        assert_eq!(seek.page_number, 3);
        let (exact_hits, fallback_hits, misses) = renderer.window_seek_stats();
        assert_eq!((exact_hits, fallback_hits, misses), (0, 1, 0));
    }

