    #[test]
    fn try_prepare_seek_start_requires_visible_range_start_at_or_after_snapshot_page() {
        let mut renderer = test_renderer();
        let options = options_for_seek_tests();

        renderer.visible_page_range = Some(2..=3);

        let dirty_from = 10;
        renderer.page_start_seek_cache.borrow_mut().insert(
            dirty_from,
            PageStartSeekSnapshot {
                paragraph_index: dirty_from,
                body_element_index: 100,
                section_index: 0,
                page_number: 3,
                column_index: 0,
                page_offset_y: 0.0,
                current_y: renderer.margin_top,
                last_line_baseline: renderer.margin_top,
                trailing_spacing_after: None,
                column_layout: renderer.column_layout.clone(),
                current_text_direction: None,
                current_doc_grid: None,
                current_doc_grid_char_spacing_px: None,
                numbering_counter: NumberingCounter::new(),
                footnote_counter: 0,
                endnote_counter: 0,
                margin_top: renderer.margin_top,
                page_height: renderer.page_height,
                page_width: renderer.page_width,
                spanning: false,
                table_counter: 0,
            },
        );

        // Visible range starts at page 2 (< snapshot page 3) => reject.
        assert!(renderer
            .try_prepare_seek_start(dirty_from, &options)
            .is_none());

        // Visible range starts at page 3 (== snapshot page) => accept.
        renderer.visible_page_range = Some(3..=3);
        assert!(renderer
            .try_prepare_seek_start(dirty_from, &options)
            .is_some());
    }

