    #[test]
    fn vertical_section_paints_each_run_with_its_authored_font() {
        use jade_painter::recording::Op;
        let (mut renderer, painter) = recording_renderer();
        let document = Document {
            body: Some(Body {
                elements: vec![BodyElement::from_paragraph(Paragraph {
                    runs: vec![
                        text_box_run(
                            "あ",
                            Some(RunProperties {
                                font_family: Some(Rc::from("Noto Sans JP")),
                                font_size: Some(17.0),
                                ..Default::default()
                            }),
                        ),
                        text_box_run(
                            "い",
                            Some(RunProperties {
                                font_family: Some(Rc::from("Noto Sans JP")),
                                font_size: Some(23.0),
                                bold: Some(true),
                                ..Default::default()
                            }),
                        ),
                    ],
                    properties: None,
                    node_id: None,
                    comment_ranges: Vec::new(),
                    comment_markers: Vec::new(),
                })],
            }),
            default_section: Some(SectionProperties {
                text_direction: Some(TextDirection::TbRl),
                ..Default::default()
            }),
            ..Default::default()
        };
        renderer
            .render(&document, &options_for_seek_tests())
            .unwrap();
        let mut font = String::new();
        let mut painted = Vec::new();
        for op in painter.ops() {
            match op {
                Op::SetFont(value) => font = value,
                Op::FillText(text, _, _) if text == "あ" || text == "い" => {
                    painted.push((text, font.clone()));
                }
                _ => {}
            }
        }
        assert_eq!(painted.len(), 2);
        assert!(painted[0].1.contains("17.00pt"), "{painted:?}");
        assert!(painted[1].1.contains("23.00pt"), "{painted:?}");
        assert!(painted[1].1.contains("bold"), "{painted:?}");
    }

