    #[test]
    fn try_prepare_seek_start_can_seek_from_page_start_of_dirty_paragraph_page() {
        use jade_docx_layout::layout_cache::ParagraphLayoutResult;

        let mut renderer = test_renderer();
        // Visible range starts AFTER page 3, so we are allowed to seek from a later column
        // on page 3 without blanking any visible pixels.
        renderer.visible_page_range = Some(4..=4);

        // Also provide a column-start snapshot for the dirty paragraph's start column.
        // This should take precedence over page-start.
        renderer.page_column_seek_cache.borrow_mut().insert(
            (3, 2),
            PageStartSeekSnapshot {
                paragraph_index: 6,
                body_element_index: 60,
                section_index: 0,
                page_number: 3,
                column_index: 2,
                page_offset_y: 0.0,
                current_y: renderer.margin_top,
                last_line_baseline: renderer.margin_top,
                trailing_spacing_after: None,
                column_layout: renderer.column_layout.clone(),
                current_text_direction: None,
                current_doc_grid: None,
                current_doc_grid_char_spacing_px: None,
                numbering_counter: NumberingCounter::new(),
                footnote_counter: 0,
                endnote_counter: 0,
                margin_top: renderer.margin_top,
                page_height: renderer.page_height,
                page_width: renderer.page_width,
                spanning: false,
                table_counter: 0,
            },
        );

        // Page 3 starts at paragraph 5.
        renderer.page_start_seek_cache_by_page.borrow_mut().insert(
            3,
            PageStartSeekSnapshot {
                paragraph_index: 5,
                body_element_index: 50,
                section_index: 0,
                page_number: 3,
                column_index: 0,
                page_offset_y: 0.0,
                current_y: renderer.margin_top,
                last_line_baseline: renderer.margin_top,
                trailing_spacing_after: None,
                column_layout: renderer.column_layout.clone(),
                current_text_direction: None,
                current_doc_grid: None,
                current_doc_grid_char_spacing_px: None,
                numbering_counter: NumberingCounter::new(),
                footnote_counter: 0,
                endnote_counter: 0,
                margin_top: renderer.margin_top,
                page_height: renderer.page_height,
                page_width: renderer.page_width,
                spanning: false,
                table_counter: 0,
            },
        );

        // Dirty paragraph is 7, and its cached pre-edit layout says it starts on page 3 (0-indexed=2).
        renderer.paragraph_layout_cache.borrow_mut().insert(
            7,
            ParagraphLayoutResult::new(
                ContentHash::new(1),
                100.0,
                120.0,
                2,
                2,
                0.0,
                0.0,
                2,
                2,
                100.0,
                120.0,
            ),
        );

        let options = options_for_seek_tests();

        let seek = renderer
            .try_prepare_seek_start(7, &options)
            .expect("seek snapshot");
        assert_eq!(seek.page_number, 3);
        assert_eq!(seek.column_index, 2);
        assert_eq!(seek.paragraph_index, 6);
    }

