    #[test]
    fn try_prepare_seek_start_accepts_mid_page_paragraph_seek_on_first_visible_page_when_prefix_is_reconstructable(
    ) {
        use jade_docx_layout::layout_cache::ParagraphLayoutResult;

        let mut renderer = test_renderer();
        renderer.visible_page_range = Some(3..=4);
        renderer.pageless_mode = false;

        let page_0idx = 2usize;
        let page_offset_y = (renderer.page_height + PAGE_GAP_PX) * (page_0idx as f64);
        let dirty_from = 10;

        // Mid-page paragraph seek snapshot at paragraph 10 (dirty paragraph).
        renderer.paragraph_seek_cache.borrow_mut().insert(
            dirty_from,
            PageStartSeekSnapshot {
                paragraph_index: dirty_from,
                body_element_index: 100,
                section_index: 0,
                page_number: 3,
                column_index: 0,
                page_offset_y,
                current_y: renderer.margin_top + 80.0,
                last_line_baseline: renderer.margin_top + 20.0,
                trailing_spacing_after: None,
                column_layout: renderer.column_layout.clone(),
                current_text_direction: None,
                current_doc_grid: None,
                current_doc_grid_char_spacing_px: None,
                numbering_counter: NumberingCounter::new(),
                footnote_counter: 0,
                endnote_counter: 0,
                margin_top: renderer.margin_top,
                page_height: renderer.page_height,
                page_width: renderer.page_width,
                spanning: false,
                table_counter: 0,
            },
        );

        // Provide cached layout for a prefix paragraph on the same page (paragraph 9).
        let p9_start_y = page_offset_y + renderer.margin_top + 10.0;
        let p9_end_y = page_offset_y + renderer.margin_top + 60.0;
        // Anchor paragraph that ends on the previous page, so the backward scan has a stopping point.
        // (Page 2 is 0-indexed=1; its content ends before page 3 starts.)
        let page2_0idx = 1usize;
        let page2_offset_y = (renderer.page_height + PAGE_GAP_PX) * (page2_0idx as f64);
        renderer.paragraph_layout_cache.borrow_mut().insert(
            8,
            ParagraphLayoutResult::new(
                ContentHash::new(8),
                page2_offset_y + renderer.margin_top + 10.0,
                page_offset_y - 10.0,
                page2_0idx,
                page2_0idx,
                page2_offset_y,
                page2_offset_y,
                0,
                0,
                page2_offset_y + renderer.margin_top + 10.0,
                page_offset_y - 10.0,
            ),
        );
        renderer.paragraph_layout_cache.borrow_mut().insert(
            9,
            ParagraphLayoutResult::new(
                ContentHash::new(9),
                p9_start_y,
                p9_end_y,
                page_0idx,
                page_0idx,
                page_offset_y,
                page_offset_y,
                0,
                0,
                p9_start_y,
                p9_end_y,
            ),
        );
        // Also keep pre-edit layout for dirty paragraph as page estimator anchor.
        renderer.paragraph_layout_cache.borrow_mut().insert(
            dirty_from,
            ParagraphLayoutResult::new(
                ContentHash::new(10),
                page_offset_y + renderer.margin_top + 80.0,
                page_offset_y + renderer.margin_top + 120.0,
                page_0idx,
                page_0idx,
                page_offset_y,
                page_offset_y,
                0,
                0,
                page_offset_y + renderer.margin_top + 70.0,
                page_offset_y + renderer.margin_top + 120.0,
            ),
        );

        // Provide cached render for the prefix paragraph so prefix pixels can be reconstructed.
        renderer
            .paragraph_render_cache
            .borrow_mut()
            .entries
            .resize(11, None);
        renderer.paragraph_render_cache.borrow_mut().entries[9] = Some(CachedParagraphRender {
            render_hash: ContentHash::new(9),
            start_y: p9_start_y,
            start_page: page_0idx,
            start_page_offset_y: page_offset_y,
            start_column: 0,
            end_y: p9_end_y,
            end_last_line_baseline: p9_end_y,
            start_spacing_after_input: 0.0,
            start_line_number_state: None,
            end_line_number_state: None,
            end_spacing_after: None,
            numbering_increment: None,
            start_numbering_state: None,
            commands: Vec::new().into(),
            selection_text: "p9".to_string(),
            selection_lines: Vec::new(),
            hyperlink_regions: Vec::new(),
        });

        // Fallback page start exists but should not be chosen when prefix is reconstructable.
        renderer.page_start_seek_cache_by_page.borrow_mut().insert(
            3,
            PageStartSeekSnapshot {
                paragraph_index: 5,
                body_element_index: 50,
                section_index: 0,
                page_number: 3,
                column_index: 0,
                page_offset_y,
                current_y: renderer.margin_top,
                last_line_baseline: renderer.margin_top,
                trailing_spacing_after: None,
                column_layout: renderer.column_layout.clone(),
                current_text_direction: None,
                current_doc_grid: None,
                current_doc_grid_char_spacing_px: None,
                numbering_counter: NumberingCounter::new(),
                footnote_counter: 0,
                endnote_counter: 0,
                margin_top: renderer.margin_top,
                page_height: renderer.page_height,
                page_width: renderer.page_width,
                spanning: false,
                table_counter: 0,
            },
        );

        let options = options_for_seek_tests();
        let seek = renderer
            .try_prepare_seek_start(dirty_from, &options)
            .expect("seek snapshot");
        assert_eq!(seek.page_number, 3);
        assert_eq!(seek.paragraph_index, dirty_from);
        assert!(seek.current_y > renderer.margin_top);
    }

