    #[test]
    fn visible_page_range_gates_dirty_page_drawing_and_promotion() {
        let mut renderer = test_renderer();

        // Pretend we're in a partial repaint pass with a dirty page set.
        renderer.render_full_repaint = false;
        renderer.render_dirty_pages = Some(std::collections::BTreeSet::from([1, 2]));

        // Limit drawing to only page 2 (1-indexed).
        renderer.visible_page_range = Some(2..=2);

        // Page 1 is dirty, but outside the visible range => do not draw.
        assert!(!renderer.should_draw_page_for_current_render(1));
        // Page 2 is dirty and visible => draw.
        assert!(renderer.should_draw_page_for_current_render(2));

        // Promotion should respect visible range too: do not force page 1 dirty.
        renderer
            .promote_page_to_dirty_for_current_render(1)
            .expect("promote page 1");
        assert_eq!(
            renderer.render_dirty_pages.as_ref().unwrap(),
            &std::collections::BTreeSet::from([1, 2])
        );

        // Promotion of a visible page should remain effective (no-op here since it's already dirty).
        renderer
            .promote_page_to_dirty_for_current_render(2)
            .expect("promote page 2");
        assert_eq!(
            renderer.render_dirty_pages.as_ref().unwrap(),
            &std::collections::BTreeSet::from([1, 2])
        );
    }

    /// Records which page-cursor operations the renderer asks of the host, and
    /// lets the walk skip pages without touching them the way the offscreen
    /// host does.
    struct TouchTrackingHost {
        events: Rc<RefCell<Vec<&'static str>>>,
    }

    impl crate::render_host::CanvasRenderHost for TouchTrackingHost {
        type Painter = jade_canvas_painter::Canvas2dPainter<web_sys::CanvasRenderingContext2d>;

        fn painter(&self) -> Self::Painter {
            unreachable!("test host: painter() must not be called")
        }
        fn device_pixel_ratio(&self) -> f64 {
            1.0
        }
        fn update_device_pixel_ratio(&mut self) -> Result<bool, JsValue> {
            Ok(false)
        }
        fn reset_pages(&mut self) -> Result<(), JsValue> {
            Ok(())
        }
        fn configure_base_canvas(
            &mut self,
            _width: f64,
            _height: f64,
            _pageless: bool,
            _margin_top: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }
        fn clear(
            &mut self,
            _page_width: f64,
            _pageless: bool,
            _full_height: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }
        fn ensure_pageless_height(
            &mut self,
            _required_height: f64,
            _margin_bottom: f64,
        ) -> Result<(), JsValue> {
            Ok(())
        }
        fn start_new_page(
            &mut self,
            _width: f64,
            _height: f64,
            _margin_top: f64,
        ) -> Result<(), JsValue> {
            self.events.borrow_mut().push("start-new-page");
            Ok(())
        }
        fn advance_page_without_touch(&mut self, _width: f64, _height: f64) -> bool {
            self.events.borrow_mut().push("advance-without-touch");
            true
        }
        fn jump_to_page_without_touch(&mut self, _page_number: usize) -> bool {
            self.events.borrow_mut().push("jump-without-touch");
            true
        }
        fn activate_current_page(&mut self) -> Result<(), JsValue> {
            self.events.borrow_mut().push("activate-current-page");
            Ok(())
        }
        fn context(&self) -> &web_sys::CanvasRenderingContext2d {
            unreachable!("test host: context() must not be called")
        }
        fn context_mut(&mut self) -> &mut web_sys::CanvasRenderingContext2d {
            unreachable!("test host: context_mut() must not be called")
        }
        fn device_to_css(&self, value: f64) -> f64 {
            value
        }
        fn canvas_css_size(&self) -> (f64, f64) {
            (0.0, 0.0)
        }
        fn take_paged_snapshots(&mut self) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }
        fn take_paged_snapshots_for_pages(
            &mut self,
            _pages: Option<&[usize]>,
        ) -> Result<Option<Vec<JsValue>>, JsValue> {
            Ok(None)
        }
        fn page_count(&self) -> usize {
            3
        }
        fn page_dimensions(&self, _page_index: usize) -> Option<(f64, f64)> {
            Some((0.0, 0.0))
        }
        fn create_page_bitmap(&self, _page_index: usize) -> Result<js_sys::Promise, JsValue> {
            Err(JsValue::from_str(
                "test host: create_page_bitmap not supported",
            ))
        }
    }

    fn touch_tracking_renderer() -> (CanvasRenderer, Rc<RefCell<Vec<&'static str>>>) {
        let events = Rc::new(RefCell::new(Vec::new()));
        let host = TouchTrackingHost {
            events: Rc::clone(&events),
        };
        let mut renderer =
            CanvasRenderer::with_host(Box::new(host) as crate::render_host::BoxedRenderHost, false)
                .expect("test renderer");
        renderer.page_width = 600.0;
        renderer.page_height = 800.0;
        // A partial repaint with only page 1 dirty and pages 1-2 visible: the
        // walk reaches page 2 through the no-touch advance.
        renderer.render_full_repaint = false;
        renderer.render_dirty_pages = Some(std::collections::BTreeSet::from([1]));
        renderer.visible_page_range = Some(1..=2);
        renderer.current_page_number = 1;
        (renderer, events)
    }

    /// The walk reaches a page it will not draw without activating its canvas,
    /// so the drawing context still points at page 1. When a cache miss then
    /// promotes that page mid-walk, the promotion has to activate the page's
    /// canvas first — otherwise page 2's content is painted into page 1, which
    /// is what dragging a floating text box on a multi-page lazy document did.
    #[test]
    fn promoting_page_reached_without_touch_activates_its_canvas() {
        let (mut renderer, events) = touch_tracking_renderer();

        renderer
            .begin_next_page_backing(2)
            .expect("advance to page 2");
        renderer.current_page_number = 2;
        assert_eq!(events.borrow().as_slice(), &["advance-without-touch"]);
        assert!(
            renderer.current_page_started_this_pass,
            "a page advance enters the page at its top"
        );

        // A mid-page resume never clears the page: the pixels above the resume
        // point are not repainted this pass. It still has to activate the
        // canvas, and it is the variant this host (which cannot paint) can run.
        renderer.current_page_started_this_pass = false;
        renderer
            .promote_page_to_dirty_for_current_render(2)
            .expect("promote page 2");
        assert_eq!(
            events.borrow().as_slice(),
            &["advance-without-touch", "activate-current-page"]
        );
        assert!(renderer
            .render_dirty_pages
            .as_ref()
            .expect("dirty set")
            .contains(&2));
        assert!(
            renderer.dirty_regions().iter().any(|rect| rect.page == 1),
            "the host must refresh the promoted page's bitmap"
        );

        // Promoting an already dirty page is a no-op: no second activation.
        renderer
            .promote_page_to_dirty_for_current_render(2)
            .expect("promote page 2 again");
        assert_eq!(events.borrow().len(), 2);
    }

    /// A paragraph that is being painted (cache miss) and crosses onto a page
    /// the caller did not mark dirty has its remaining lines drawn there, so
    /// that page becomes dirty as it starts. Without this, the lines were
    /// gated away and a later promotion of the page started from a clear:
    /// dragging a text box on yokohama left page 2's first paragraph blank.
    #[test]
    fn page_break_inside_a_painted_paragraph_marks_the_next_page_dirty() {
        let (mut renderer, events) = touch_tracking_renderer();
        renderer.drawing_uncached_paragraph = true;

        // Checking the dirty set before the host is asked to start the page
        // keeps this host (which cannot paint) out of the drawn-page path.
        assert!(renderer.mark_page_dirty_for_current_render(2));
        assert!(renderer
            .render_dirty_pages
            .as_ref()
            .expect("dirty set")
            .contains(&2));
        assert!(renderer.dirty_regions().iter().any(|rect| rect.page == 1));
        assert!(!renderer.mark_page_dirty_for_current_render(2));
        assert!(
            !renderer.mark_page_dirty_for_current_render(3),
            "a page outside the visible window stays on the on-demand path"
        );
        assert!(events.borrow().is_empty());

        // A replayed (cached) paragraph never paints, so its page break keeps
        // the no-touch advance.
        renderer.drawing_uncached_paragraph = false;
        renderer.render_dirty_pages = Some(std::collections::BTreeSet::from([1]));
        renderer
            .begin_next_page_backing(2)
            .expect("advance to page 2");
        assert_eq!(events.borrow().as_slice(), &["advance-without-touch"]);
        assert!(!renderer
            .render_dirty_pages
            .as_ref()
            .expect("dirty set")
            .contains(&2));
    }

    /// The renderer's paragraph indices must stay aligned with the document
    /// model's surfaces, which never include a paragraph for a textless shape.
    #[test]
    fn empty_text_box_fallback_registers_no_paragraph() {
        let mut renderer = test_renderer();
        renderer.paragraph_counter = 7;
        let mut cursor_y = 10.0;
        renderer
            .render_empty_text_box_paragraph(0.0, &mut cursor_y, 100.0)
            .expect("fallback");
        assert_eq!(renderer.paragraph_counter, 7);
        assert!(cursor_y > 10.0, "the box still reserves its empty line");
    }

    /// Only the page the walk is currently on maps to the host's page cursor;
    /// promoting any other page must not re-activate a canvas.
    #[test]
    fn promoting_a_page_the_walk_is_not_on_leaves_the_active_canvas_alone() {
        let (mut renderer, events) = touch_tracking_renderer();
        renderer.current_page_number = 1;
        renderer.current_page_started_this_pass = true;

        renderer
            .promote_page_to_dirty_for_current_render(2)
            .expect("promote page 2");
        assert!(events.borrow().is_empty());
        assert!(renderer
            .render_dirty_pages
            .as_ref()
            .expect("dirty set")
            .contains(&2));
    }

    /// A page outside the visible window is never promoted, so its (possibly
    /// shrunk) canvas is never activated either.
    #[test]
    fn shifted_cached_paragraph_outside_visible_window_does_not_paint() {
        use jade_painter::recording::Op;
        for unchecked in [false, true] {
            let (mut renderer, painter) = recording_renderer();
            renderer.pageless_mode = false;
            renderer.current_page_number = 2;
            renderer.current_y = 200.0;
            renderer.last_line_baseline = 200.0;
            renderer.render_full_repaint = true;
            let mut options = Options::default();
            options.set_pageless(false);
            options.show_formatting_marks = false;
            renderer.last_options = Some(options.clone());
            let paragraph = note_test_paragraph("off-window cached paragraph", None);
            renderer
                .render_paragraph_with_numbering(
                    &paragraph,
                    &options,
                    None,
                    &mut NumberingCounter::default(),
                    &mut HashMap::new(),
                    0,
                    0,
                    0,
                )
                .unwrap();
            assert!(painter
                .ops()
                .iter()
                .any(|op| matches!(op, Op::FillText(..))));
            painter.clear();
            renderer.current_y = 220.0;
            renderer.last_line_baseline = 220.0;
            renderer.trailing_spacing_after = None;
            renderer.render_full_repaint = false;
            renderer.render_dirty_pages = Some(std::collections::BTreeSet::new());
            renderer.visible_page_range = Some(1..=1);
            if unchecked {
                renderer.shift_replay_from = Some(0);
            }
            renderer
                .render_paragraph_with_numbering(
                    &paragraph,
                    &options,
                    None,
                    &mut NumberingCounter::default(),
                    &mut HashMap::new(),
                    0,
                    0,
                    0,
                )
                .unwrap();
            assert!(
                !painter
                    .ops()
                    .iter()
                    .any(|op| matches!(op, Op::FillText(..))),
                "unchecked={unchecked}: {:?}",
                painter.ops()
            );
            assert!(renderer.current_y > 220.0);
        }
    }

    #[test]
    fn promoting_an_invisible_page_neither_activates_nor_marks_it() {
        let (mut renderer, events) = touch_tracking_renderer();
        renderer.current_page_number = 3;
        renderer.current_page_started_this_pass = true;

        renderer
            .promote_page_to_dirty_for_current_render(3)
            .expect("promote page 3");
        assert!(events.borrow().is_empty());
        assert!(!renderer
            .render_dirty_pages
            .as_ref()
            .expect("dirty set")
            .contains(&3));
    }

