        assert_eq!(debug_lines.len(), 1);
        assert!((debug_lines[0].start_x - 5.0).abs() < 1e-6);
        assert!((debug_lines[0].cursor_end_x - 55.0).abs() < 1e-6);
        assert!((debug_lines[0].fragments[0].x - 5.0).abs() < 1e-6);
        assert!((debug_lines[0].fragments[0].glyphs[0].x + 5.0).abs() < 1e-6);

        let stored_line = &renderer.selection.paragraphs()[paragraph_index].lines[0];
