    #[test]
    fn cached_numbering_shares_internal_replays_and_refreshes_external_inputs() {
        let mut renderer = pageless_test_renderer();
        let mut numbering = NumberingPart::from_xml(
            r#"<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
              <w:abstractNum w:abstractNumId="0"><w:lvl w:ilvl="0"><w:start w:val="1"/>
                <w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/></w:lvl></w:abstractNum>
              <w:num w:numId="1"><w:abstractNumId w:val="0"/></w:num>
            </w:numbering>"#,
        )
        .unwrap();
        renderer.store_numbering_part(Some(&numbering));
        let saved = renderer.last_numbering_part.clone().unwrap();
        assert_eq!(Rc::strong_count(&saved), 2);
        renderer.store_numbering_part(Some(&saved));
        assert!(Rc::ptr_eq(
            &saved,
            renderer.last_numbering_part.as_ref().unwrap()
        ));
        renderer.store_numbering_part(Some(&numbering));
        assert!(!Rc::ptr_eq(
            &saved,
            renderer.last_numbering_part.as_ref().unwrap()
        ));
        numbering.numbering_instances.clear();
        renderer.store_numbering_part(Some(&numbering));
        assert!(renderer
            .last_numbering_part
            .as_ref()
            .unwrap()
            .numbering_instances
            .is_empty());
        assert_eq!(saved.numbering_instances.len(), 1);
        renderer.store_numbering_part(None);
        assert!(renderer.last_numbering_part.is_none());
        eprintln!(
            "numbering snapshot native slot bytes: owned={} shared={}",
            std::mem::size_of::<Option<NumberingPart>>(),
            std::mem::size_of::<Option<Rc<NumberingPart>>>()
        );
    }

    #[test]
    fn rich_story_borrows_body_selection_storage_without_deep_cloning() {
        for frozen in [false, true] {
            for draw in [false, true] {
                for story in ["header", "footer"] {
                    let (mut renderer, _) = recording_renderer();
                    renderer
                        .selection
                        .append_paragraph_text(0, "body storage must survive");
                    renderer.selection.record_line(0, sample_line());
                    let range =
                        SelectionRange::new(TextPosition::new(0, 0), TextPosition::new(0, 4));
                    renderer.selection.set_selection(Some(range));
                    renderer.selection.record_table_cell(CellLayout {
                        paragraphs: vec![0],
                        left: 0.0,
                        right: 100.0,
                        top: 0.0,
                        bottom: 20.0,
                        table_id: 0,
                        row: 0,
                        column: 0,
                        column_span: 1,
                        order: 0,
                    });
                    renderer.selection.set_cell_selection(0, 0);
                    if frozen {
                        renderer.selection.freeze();
                    }
                    let paragraphs = renderer.selection.paragraphs();
                    let paragraph_storage = paragraphs.as_ptr();
                    let text_storage = paragraphs[0].text.as_ptr();
                    let line_storage = paragraphs[0].lines.as_ptr();
                    let body = Body {
                        elements: vec![BodyElement::from_paragraph(note_test_paragraph(
                            "story", None,
                        ))],
                    };
                    renderer
                        .render_header_footer_body_at(&body, 20.0, 100, draw, Some(story))
                        .expect("isolated rich story");
                    let paragraphs = renderer.selection.paragraphs();
                    assert_eq!(paragraphs.as_ptr(), paragraph_storage);
                    assert_eq!(paragraphs[0].text.as_ptr(), text_storage);
                    assert_eq!(paragraphs[0].lines.as_ptr(), line_storage);
                    assert_eq!(paragraphs[0].text, "body storage must survive");
                    assert_eq!(renderer.selection.selection_range(), Some(range));
                    assert_eq!(renderer.selection.cell_selection_span(), Some((0, 0)));
                    assert_eq!(renderer.selection.is_frozen(), frozen);
                    if draw {
                        assert!(renderer
                            .hf_story_layouts
                            .contains_key(&(0, story == "header")));
                    }
                }
            }
        }
    }

