    #[test]
    fn paragraph_render_hash_with_content_tracks_text_and_run_boundaries() {
        let renderer = test_renderer();
        let options = Options::default();
        let paragraph = |texts: &[&str]| Paragraph {
            runs: texts
                .iter()
                .map(|text| {
                    let mut run = build_run(None);
                    run.text = (*text).to_string();
                    run
                })
                .collect(),
            properties: None,
            node_id: None,
            comment_ranges: Vec::new(),
            comment_markers: Vec::new(),
        };
        let left = paragraph(&["ab", "c"]);
        let right = paragraph(&["a", "bc"]);
        let changed = paragraph(&["ab", "d"]);
        let left_content = renderer.compute_paragraph_content_hash(&left);
        let changed_content = renderer.compute_paragraph_content_hash(&changed);

        assert_ne!(
            renderer.compute_paragraph_render_hash(&left, &options, Some(left_content)),
            renderer.compute_paragraph_render_hash(&changed, &options, Some(changed_content))
        );

        // A shared content digest isolates the per-run lengths: the hash must
        // still distinguish equal concatenated text with different run splits.
        let shared_content = ContentHash::new(7);
        assert_ne!(
            renderer.compute_paragraph_render_hash(&left, &options, Some(shared_content)),
            renderer.compute_paragraph_render_hash(&right, &options, Some(shared_content))
        );
    }

    #[test]
    fn paragraph_hashes_include_pagination_tabs_and_revision_visibility() {
        let renderer = test_renderer();
        let mut options = Options::default();
        options.set_render_changes(false);
        let mut paragraph = Paragraph {
            runs: vec![build_run(None)],
            properties: Some(ParagraphProperties::default()),
            node_id: None,
            comment_ranges: Vec::new(),
            comment_markers: Vec::new(),
        };
        let content_before = renderer.compute_paragraph_content_hash(&paragraph);
        let render_before = renderer.compute_paragraph_render_hash(&paragraph, &options, None);

        let props = paragraph.properties.as_mut().expect("properties");
        props.keep_next = Some(true);
        props.tabs.push(TabStop {
            kind: Some("left".to_string()),
            position: Some(72.0),
            leader: None,
        });
        let content_after = renderer.compute_paragraph_content_hash(&paragraph);
        let render_after = renderer.compute_paragraph_render_hash(&paragraph, &options, None);
        assert_ne!(content_before, content_after);
        assert_ne!(render_before, render_after);

        paragraph.runs[0].revision = Some(RevisionMark {
            kind: RevisionKind::Deleted,
            id: None,
            author: None,
            date: None,
            date_utc: None,
            insertion: None,
        });
        assert_ne!(
            render_after,
            renderer.compute_paragraph_render_hash(&paragraph, &options, None)
        );
    }

    /// Deciding contextual spacing and border boxes per pair on demand answers
    /// exactly what the whole-body scan does, for every element of sequences
    /// mixing styles, contextual spacing, borders and a table between.
    #[test]
    fn on_demand_spacing_pairs_match_the_whole_body_scan() {
        let border = |size: u32| {
            Some(ParagraphBorders {
                top: Some(BorderEdge {
                    val: Some("single".into()),
                    size_eighths: Some(size),
                    ..BorderEdge::default()
                }),
                ..ParagraphBorders::default()
            })
        };
        let mut palette = vec![BodyElement::Table(Box::default())];
        for style in [None, Some("A"), Some("B")] {
            for contextual in [None, Some(true), Some(false)] {
                for borders in [None, border(4), border(8)] {
                    palette.push(BodyElement::Paragraph(Box::new(Paragraph {
                        runs: Vec::new(),
                        properties: Some(ParagraphProperties {
                            style: style.map(Into::into),
                            contextual_spacing: contextual,
                            borders,
                            ..ParagraphProperties::default()
                        }),
                        node_id: None,
                        comment_ranges: Vec::new(),
                        comment_markers: Vec::new(),
                    })));
                }
            }
        }
        palette.push(BodyElement::Paragraph(Box::new(Paragraph {
            runs: Vec::new(),
            properties: None,
            node_id: None,
            comment_ranges: Vec::new(),
            comment_markers: Vec::new(),
        })));
        // Every ordered pair, then the whole palette as one body.
        let mut bodies = Vec::new();
        for upper in &palette {
            for lower in &palette {
                bodies.push(vec![upper.clone(), lower.clone()]);
            }
        }
        bodies.push(palette.clone());

        let (mut renderer, _) = recording_renderer();
        for elements in bodies {
            let (before, after) = compute_contextual_spacing_suppression(&elements);
            let continues = compute_paragraph_border_box_continuations(&elements);
            renderer.last_document = Some(Rc::new(Document {
                body: Some(Body {
                    elements: elements.clone(),
                }),
                ..Document::default()
            }));
            renderer.spacing_scan_from_story = false;
            for index in 0..elements.len() + 1 {
                assert_eq!(
                    renderer.contextual_suppresses_spacing_before(index),
                    before.contains(&index),
                    "before {index}"
                );
                assert_eq!(
                    renderer.contextual_suppresses_spacing_after(index),
                    after.contains(&index),
                    "after {index}"
                );
                assert_eq!(
                    renderer.paragraph_border_box_continues_after(index),
                    continues.contains(&index),
                    "border box {index}"
                );
            }
        }

        // A header/footer story answers from its own scan, not the body's.
        // palette[4]: no style, contextual spacing, no borders.
        let story = vec![palette[4].clone(), palette[4].clone()];
        let (before, after) = compute_contextual_spacing_suppression(&story);
        assert!(before.contains(&1) && after.contains(&0));
        renderer.contextual_suppress_before = before;
        renderer.contextual_suppress_after = after;
        renderer.paragraph_border_box_continues =
            compute_paragraph_border_box_continuations(&story);
        renderer.last_document = Some(Rc::new(Document::default()));
        renderer.spacing_scan_from_story = true;
        assert!(renderer.contextual_suppresses_spacing_before(1));
        assert!(renderer.contextual_suppresses_spacing_after(0));
        renderer.spacing_scan_from_story = false;
        assert!(
            !renderer.contextual_suppresses_spacing_before(1),
            "the empty body has no pair"
        );
    }

    #[test]
    fn contextual_spacing_suppresses_between_same_styled_paragraphs() {
        fn list_paragraph(style: Option<&str>, contextual: Option<bool>) -> BodyElement {
            BodyElement::Paragraph(Box::new(Paragraph {
                runs: Vec::new(),
                properties: Some(ParagraphProperties {
                    style: style.map(Into::into),
                    contextual_spacing: contextual,
                    ..ParagraphProperties::default()
                }),
                node_id: None,
                comment_ranges: Vec::new(),
                comment_markers: Vec::new(),
            }))
        }

        // Three consecutive "ListParagraph" items all declaring contextualSpacing.
        let elements = vec![
            list_paragraph(Some("ListParagraph"), Some(true)),
            list_paragraph(Some("ListParagraph"), Some(true)),
            list_paragraph(Some("ListParagraph"), Some(true)),
        ];
        let (before, after) = compute_contextual_spacing_suppression(&elements);
        // Middle and last items drop space-before; first and middle drop space-after.
        assert!(before.contains(&1));
        assert!(before.contains(&2));
        assert!(!before.contains(&0));
        assert!(after.contains(&0));
        assert!(after.contains(&1));
        assert!(!after.contains(&2));
    }

    #[test]
    fn contextual_spacing_does_not_suppress_across_different_styles_or_when_absent() {
        fn para(style: Option<&str>, contextual: Option<bool>) -> BodyElement {
            BodyElement::Paragraph(Box::new(Paragraph {
                runs: Vec::new(),
                properties: Some(ParagraphProperties {
                    style: style.map(Into::into),
                    contextual_spacing: contextual,
                    ..ParagraphProperties::default()
                }),
                node_id: None,
                comment_ranges: Vec::new(),
                comment_markers: Vec::new(),
            }))
        }

        // Different styles: no suppression even though both declare contextualSpacing.
        let mixed = vec![
            para(Some("Heading1"), Some(true)),
            para(Some("ListParagraph"), Some(true)),
        ];
        let (before, after) = compute_contextual_spacing_suppression(&mixed);
        assert!(before.is_empty());
        assert!(after.is_empty());

        // Same style but neither declares contextualSpacing: no suppression.
        let plain = vec![
            para(Some("ListParagraph"), None),
            para(Some("ListParagraph"), None),
        ];
        let (before, after) = compute_contextual_spacing_suppression(&plain);
        assert!(before.is_empty());
        assert!(after.is_empty());
    }

