    #[test]
    fn default_page_background_shading_matches_white_variants() {
        // White fills (the page color) are recognized so dark mode can skip them.
        assert!(is_default_page_background_shading("#FFFFFF"));
        assert!(is_default_page_background_shading("ffffff"));
        assert!(is_default_page_background_shading("  White  "));
        assert!(is_default_page_background_shading("rgb(255, 255, 255)"));
        // Non-white shading must still paint (genuine highlight/colored bands).
        assert!(!is_default_page_background_shading("#FFFF00"));
        assert!(!is_default_page_background_shading("#000000"));
        assert!(!is_default_page_background_shading("#fefefe"));
    }

