    #[test]
    fn column_layout_splits_width_equally_for_two_columns() {
        let columns = SectionColumns {
            count: Some(2),
            space: Some(21.25),
            ..SectionColumns::default()
        };

        let available_width = 400.0;
        let margin_left = 32.0;
        let layout = ColumnLayout::from_section(&columns, available_width, margin_left);

        assert_eq!(layout.count(), 2);
        let space_px = points_to_px(21.25);
        let width0 = layout.width(0);
        let width1 = layout.width(1);
        assert!((width0 - width1).abs() < 1e-6);

        let start0 = layout.start_x(0);
        let start1 = layout.start_x(1);

        assert!((start0 - margin_left).abs() < 1e-6);
        assert!((start1 - (margin_left + width0 + space_px)).abs() < 1e-6);
    }

    #[test]
    fn column_separator_positions_center_in_each_gutter() {
        // Three equal columns with a separator: two rules, each centered in the
        // gap between adjacent columns.
        let columns = SectionColumns {
            count: Some(3),
            space: Some(18.0),
            separator: Some(true),
            ..SectionColumns::default()
        };
        let layout = ColumnLayout::from_section(&columns, 600.0, 40.0);
        let positions = layout.separator_positions();
        assert_eq!(positions.len(), 2);
        // Each rule sits at the midpoint between one column's right edge and the
        // next column's left edge.
        for (idx, x) in positions.iter().enumerate() {
            let gutter_start = layout.start_x(idx) + layout.width(idx);
            let next_start = layout.start_x(idx + 1);
            assert!((x - (gutter_start + next_start) / 2.0).abs() < 1e-6);
            assert!(*x > gutter_start && *x < next_start);
        }

        // Separator off → no rules even with multiple columns.
        let no_sep = SectionColumns {
            count: Some(2),
            space: Some(18.0),
            separator: Some(false),
            ..SectionColumns::default()
        };
        assert!(ColumnLayout::from_section(&no_sep, 600.0, 40.0)
            .separator_positions()
            .is_empty());

        // Single column → never a separator even if requested.
        let single = SectionColumns {
            count: Some(1),
            separator: Some(true),
            ..SectionColumns::default()
        };
        assert!(ColumnLayout::from_section(&single, 600.0, 40.0)
            .separator_positions()
            .is_empty());
    }

