    #[test]
    fn numbering_fallback_resolves_style_and_theme_without_body_font_overrides() {
        let styles = StylesPart::from_xml(
            r#"<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
              <w:docDefaults><w:rPrDefault><w:rPr><w:sz w:val="22"/></w:rPr></w:rPrDefault></w:docDefaults>
              <w:style w:type="paragraph" w:styleId="heading"><w:rPr>
                <w:rFonts w:asciiTheme="majorHAnsi" w:hAnsiTheme="majorHAnsi"/>
              </w:rPr></w:style></w:styles>"#,
        ).unwrap();
        let paragraph = Paragraph {
            properties: Some(ParagraphProperties {
                style: Some("heading".into()),
                mark_run_properties: Some(RunProperties {
                    font_size: Some(12.0),
                    ..RunProperties::default()
                }),
                ..ParagraphProperties::default()
            }),
            runs: vec![build_run(Some(RunProperties {
                fonts: Some(RunFonts {
                    ascii: Some("MS Mincho".into()),
                    h_ansi: Some("MS Mincho".into()),
                    ..RunFonts::default()
                }),
                ..RunProperties::default()
            }))],
            node_id: None,
            comment_ranges: Vec::new(),
            comment_markers: Vec::new(),
        };
        let (mut renderer, _) = recording_renderer();
        for face in ["Arial", "Courier New", "Arial"] {
            renderer.set_style_context(
                Some(Rc::new(styles.clone())),
                Some(Rc::new(ThemePart {
                    major: crate::theme::ThemeFonts {
                        latin: Some(face.into()),
                        ..crate::theme::ThemeFonts::default()
                    },
                    ..ThemePart::default()
                })),
            );
            let fallback = renderer
                .paragraph_numbering_fallback_props(&paragraph)
                .unwrap();
            assert_eq!(fallback.font_size, Some(12.0));
            assert_eq!(
                fallback.fonts.as_ref().unwrap().h_ansi.as_deref(),
                Some(face)
            );
            let style = renderer.resolve_applied_run_style_cached(Some(&fallback));
            assert!(style.resolved.font_descriptor_latin_hansi.contains(face));
        }
    }

