    #[test]
    fn numbering_font_slot_override_does_not_inherit_a_competing_theme() {
        for (name, theme) in [(Some("MS Gothic"), None), (None, Some("majorHAnsi"))] {
            let primary = RunProperties {
                fonts: Some(RunFonts {
                    ascii: name.map(Into::into),
                    ascii_theme: theme.map(Into::into),
                    ..RunFonts::default()
                }),
                ..RunProperties::default()
            };
            let fallback = RunProperties {
                fonts: Some(RunFonts {
                    ascii: theme.map(|_| "Arial".into()),
                    ascii_theme: name.map(|_| "majorHAnsi".into()),
                    h_ansi_theme: Some("majorHAnsi".into()),
                    ..RunFonts::default()
                }),
                ..RunProperties::default()
            };
            let merged =
                <CanvasRenderer>::merge_numbering_run_props(Some(primary), Some(&fallback))
                    .unwrap()
                    .fonts
                    .unwrap();
            assert_eq!(merged.ascii.as_deref(), name);
            assert_eq!(merged.ascii_theme.as_deref(), theme);
            assert_eq!(merged.h_ansi_theme.as_deref(), Some("majorHAnsi"));
        }
    }

