    #[test]
    fn header_edit_boundary_uses_the_measured_rich_story_height_for_each_page() {
        let mut renderer = test_renderer();

        // HeaderLine is intentionally absent here. A rich header can contain a
        // table, drawing, or text box whose block height cannot be reconstructed
        // from flattened editable lines. The render pass records that consumed
        // height, and every edit-geometry consumer must use it verbatim.
        renderer.current_page_number = 1;
        renderer.record_header_content_height(80.0);
        renderer.current_page_number = 2;
        renderer.record_header_content_height(120.0);

        let page_one_expected = (renderer.header_edit_content_top() + 80.0 + HF_EDIT_LINE_HEIGHT)
            .max(renderer.margin_top);
        let page_two_expected = (renderer.header_edit_content_top() + 120.0 + HF_EDIT_LINE_HEIGHT)
            .max(renderer.margin_top);
        assert_eq!(renderer.header_edit_boundary_for_page(0), page_one_expected);
        assert_eq!(renderer.header_edit_boundary_for_page(1), page_two_expected);
    }

    #[test]
    fn paragraph_break_batch_first_downstream_index_is_first_plus_count_plus_one() {
        assert_eq!(
            <CanvasRenderer>::paragraph_break_batch_first_downstream_index(0, 1),
            2,
            "single-break at index 0 should leave first downstream at 2",
        );
        assert_eq!(
            <CanvasRenderer>::paragraph_break_batch_first_downstream_index(0, 3),
            4,
            "3 breaks at index 0 should leave first downstream at 4 (not 3, the last empty gap)",
        );
        assert_eq!(
            <CanvasRenderer>::paragraph_break_batch_first_downstream_index(7, 5),
            13,
            "5 breaks at index 7 should leave first downstream at 13",
        );
    }

    fn hl(text: &str) -> HeaderLine {
        HeaderLine {
            left: Some(text.to_string()),
            ..HeaderLine::default()
        }
    }

    fn section_set(default: &str, first: Option<&str>, title_page: bool) -> SectionHeaderFooters {
        SectionHeaderFooters {
            header: Some(vec![hl(default)]),
            header_first: first.map(|text| vec![hl(text)]),
            title_page,
            ..SectionHeaderFooters::default()
        }
    }

    /// With per-section stories installed, each page reads the header of the
    /// section that owns it, and `w:titlePg` applies to the first page of
    /// that section rather than page 1 of the document.
    #[test]
    fn header_lines_follow_the_section_that_owns_each_page() {
        let mut renderer = test_renderer();
        renderer.set_section_header_footers(vec![
            section_set("one", Some("one-first"), true),
            section_set("two", None, true),
        ]);
        // Pages 1-2 belong to section 0, pages 3-4 to section 1.
        renderer.page_section_indices = vec![0, 0, 1, 1];

        let header = |renderer: &mut CanvasRenderer<_>, page: usize| {
            renderer.current_page_number = page;
            renderer.active_section_index = renderer.page_section_indices[page - 1];
            renderer
                .active_header_lines()
                .map(|lines| lines[0].left.clone().unwrap_or_default())
        };
        assert_eq!(header(&mut renderer, 1).as_deref(), Some("one-first"));
        assert_eq!(header(&mut renderer, 2).as_deref(), Some("one"));
        // Section 2 has no first-page story of its own; Word would show the
        // inherited one, which the model already folded in, so an absent
        // `header_first` simply falls back to the default variant here.
        assert_eq!(header(&mut renderer, 3).as_deref(), Some("two"));
        assert_eq!(header(&mut renderer, 4).as_deref(), Some("two"));
    }

    #[test]
    fn without_section_stories_the_document_wide_lines_still_apply() {
        let mut renderer = test_renderer();
        renderer.header_lines = Some(vec![hl("doc")]);
        renderer.page_section_indices = vec![0, 1];
        renderer.current_page_number = 2;
        renderer.active_section_index = 1;
        assert_eq!(
            renderer
                .active_header_lines()
                .map(|lines| lines[0].left.clone()),
            Some(Some("doc".to_string()))
        );
    }

