    #[test]
    fn variant_selection_prefers_first_over_even_on_page_1() {
        // Word treats page 1 as the title page regardless of even/odd, so a
        // document that toggles both should still show the first-page variant
        // (not even, since page 1 is odd anyway — but guard against a future
        // bug where ordering gets inverted).
        let default_lines = vec![hl("default")];
        let first_lines = vec![hl("first")];
        let even_lines = vec![hl("even")];

        let got = select_header_footer_variant(
            1,
            true,
            true,
            Some(&default_lines),
            Some(&first_lines),
            Some(&even_lines),
        )
        .unwrap();
        assert_eq!(got, first_lines.as_slice());
    }

    #[test]
    fn variant_selection_falls_back_when_requested_variant_is_missing() {
        let default_lines = vec![hl("default")];

        // title_page set but no first variant -> default
        let got =
            select_header_footer_variant(1, true, false, Some(&default_lines), None, None).unwrap();
        assert_eq!(got, default_lines.as_slice());

        // even flag set but no even variant -> default
        let got =
            select_header_footer_variant(2, false, true, Some(&default_lines), None, None).unwrap();
        assert_eq!(got, default_lines.as_slice());
    }

