    #[test]
    fn section_run_field_resolves_one_based_active_section_index() {
        let mut renderer = test_renderer();
        renderer.active_section_index = 2;
        let field = RunField {
            word_mac_body_result: None,
            kind: RunFieldKind::SectionNumber,
            cached_text: Some("99".to_string()),
            source_field_id: None,
            resolved_value: None,
        };

        // Internal section indices are zero-based, while Word displays the
        // first section as 1. Live layout must replace the stale saved result.
        assert_eq!(renderer.resolve_run_field(&field).as_deref(), Some("3"));
    }

    #[test]
