    #[test]
    fn mac_line_anchored_exclusion_starts_from_the_paragraph_top_before_its_lines() {
        use jade_docx_layout::line_metrics::{
            set_word_layout_platform, word_layout_platform, WordLayoutPlatform,
        };
        let previous = word_layout_platform();
        let renderer = test_renderer();
        // `textbox`: a box 31pt below its double-spaced anchor line, wrapped
        // top and bottom with 12pt distances.
        let layout = RunImageLayout {
            kind: RunImageKind::Floating,
            position_v: Some(ImagePosition {
                relative_from: Some("line".into()),
                offset_px: Some(points_to_px(31.0)),
                align: None,
            }),
            wrap: WrapMode::TopAndBottom,
            dist_top: Some(points_to_px(12.0)),
            dist_bottom: Some(points_to_px(12.0)),
            ..RunImageLayout::default()
        };
        assert!(anchored_to_line(&layout));
        let top_pt = |platform| {
            set_word_layout_platform(platform);
            renderer
                .floating_object_wrap_exclusion(
                    FloatingObjectTarget {
                        paragraph_index: 0,
                        run_index: 0,
                        kind: FloatingObjectKind::TextBox,
                    },
                    points_to_px(250.0),
                    points_to_px(128.0),
                    &layout,
                    points_to_px(100.0),
                    points_to_px(28.6),
                )
                .expect("top-and-bottom wrap exclusion")
                .top
                * 0.75
        };
        let mac = top_pt(WordLayoutPlatform::Mac);
        let windows = top_pt(WordLayoutPlatform::Windows);
        assert!((mac - (100.0 + 31.0 - 12.0)).abs() < 0.01, "Mac {mac}");
        assert!(
            (windows - (100.0 + 28.6 + 31.0 - 12.0)).abs() < 0.01,
            "Windows {windows}"
        );
        set_word_layout_platform(previous);
    }

    #[test]
    fn floating_object_exclusion_transforms_tight_polygon_with_shape() {
        let renderer = test_renderer();
        let mut layout = RunImageLayout {
            kind: RunImageKind::Floating,
            position_h: Some(ImagePosition {
                relative_from: Some("page".into()),
                offset_px: Some(100.0),
                align: None,
            }),
            position_v: Some(ImagePosition {
                relative_from: Some("page".into()),
                offset_px: Some(200.0),
                align: None,
            }),
            rotation_deg: Some(90.0),
            flip_horizontal: true,
            wrap: WrapMode::Tight,
            wrap_polygon: Some(WrapPolygon {
                edited: true,
                points: vec![
                    WrapPolygonPoint { x: 10800, y: 0 },
                    WrapPolygonPoint { x: 21600, y: 21600 },
                    WrapPolygonPoint { x: 0, y: 21600 },
                ],
            }),
            ..RunImageLayout::default()
        };
        let exclusion = renderer
            .floating_object_wrap_exclusion(
                FloatingObjectTarget {
                    paragraph_index: 0,
                    run_index: 0,
                    kind: FloatingObjectKind::Image,
                },
                200.0,
                100.0,
                &layout,
                0.0,
                20.0,
            )
            .expect("tight wrap exclusion");
        let polygon = exclusion.polygon.expect("transformed polygon");
        assert!(!polygon.allow_internal_gaps);

        for (actual, expected) in polygon.points.iter().zip([
            FloatPoint { x: 250.0, y: 250.0 },
            FloatPoint { x: 150.0, y: 150.0 },
            FloatPoint { x: 150.0, y: 350.0 },
        ]) {
            assert!((actual.x - expected.x).abs() < 0.001);
            assert!((actual.y - expected.y).abs() < 0.001);
        }
        assert!((exclusion.left - 150.0).abs() < 0.001);
        assert!((exclusion.right - 250.0).abs() < 0.001);
        assert!((exclusion.top - 150.0).abs() < 0.001);
        assert!((exclusion.bottom - 350.0).abs() < 0.001);

        layout.wrap = WrapMode::Through;
        let through = renderer
            .floating_object_wrap_exclusion(
                FloatingObjectTarget {
                    paragraph_index: 0,
                    run_index: 0,
                    kind: FloatingObjectKind::Image,
                },
                200.0,
                100.0,
                &layout,
                0.0,
                20.0,
            )
            .expect("through wrap exclusion");
        assert!(
            through
                .polygon
                .expect("transformed through polygon")
                .allow_internal_gaps
        );
    }

